        title = "الصُم",
        sections = arrayOf(
            TextSection(
                "",
                "الصمم  او فقدان السمع مرض يمكن ان يصيب الشخص في اي عمر وحسب احصائيات المتخصصين في الصم واضطرابات التواصل تجد ان الامر اصبح يثير القلق اذا يعاني 15%  من الشباب فوق سن 18 عام من مشاكل السمع ويجد ان نسبه الاصابه تصل الى 25% في الفئة  العمريه بين 65 سنه و 74 سنه اما من تجاوز 75 سنه فهم يعانون  من فقدان كل او جزئي للسمع بنسبه تصل الى 50% وتقل  قيمة في النسبه عند الوضع حيث نجد من 2 الى 3 في الالف  يعانون من الصم القابل  للكشف  في اذن  واحدة على الاقل."
            ),
            ImageSection("1/1/1.jpg"),
            TextSection(
                "من هم الصم؟",
