                        "7-\tالمهارات الاجتماعية غير المناسبة لدى الطلبة الصم فبعضهم لا يستطيع المحافظة على علاقات شخصيه .\n" +
                        "8-\t ضعف مفهوم الذات لدى الصم .\n" +
