                        "-\tيحدث بفعل اضطرابات في الاذن الخارجيه او الوسطى مما يجد او يمنع الذبذبات الصوتيه من الانتقال خلال القناه السمعيه \n" +
                        "-\tمن اكثر الانواع شيوعا بين الاطفال \n" +
                        "-\tيمكن علاج هذا النوع من الصمغ \n" +
