                        "4-\t استخدام بعض الأدوية السامه للاذن استخدام فير سليم .\n" +
                        "5-\t اصابه الاطفال حديثي الولاده بمرض اليرقان الوضيم الذي يؤثر على عصب السمع لديهم .\n" +
                        "2- اسباب الصم المكتسبه مثل\n" +
