                        "6-\t انسداد قناه الاذن بالشمع او بالمواد الغريبة .\n" +
                        "7-\tيعد السبب الرئيسي لأصابه الاطفال بفقدان السمع هو الاصابه بالتهاب الوزن الوسطى المزمن .\n"
