                        "8-\t صعوبه الفهم المحادثات الكلاميه .\n" +
                        "9-\t طنين الاذن او الغمغمه المتواصله .\n" +
                        "10-\t لا يوجه الطفل راسه نحو مصدر الصوت .\n" +
                        "11-\t لا يبدي الطفل الرضيع اي اندهاش في حاله وجود ضوضاء اضافيه.\n"
