                        "2-\t فقدان السمع لا يؤثر على القراءه والكتابه ولكن يجب ان يكون هناك استعداد نفسي من قبل الاصم.\n" +
                        "3-\tيجب ان يكون تدريس القراءة في المدارس بالشكل الممتع .\n" +
                        "4-\t لا يمكن تدريس القراءة في ماده العلوم من دون استخدام الوسائل المرئية .\n" +
