                "",
                "حاسة السمع مهمه للفرد من خلال السمع بيقدر الفرد أنه يتواصل مع الأشخاص الآخرين ويفهم المكان و البيئة الموجود فيها ويتبادل الكلام مع الأفراد ويتفاعل معهم."
