                        "-الخصائص الجسمية:.\n" +
                        "الطفل ضعيف السمع يعانى من مشكلات في الاتصال وعدم قدرتهم على أكتشاف البيئة والتفاعل معها لذلك يجب تزويد الأفراد ضعاف السمع بالتدريب اللازم للتواصل مع الآخرين لأن الاعاقه السمعيه قد تفرض قيودا على النمو الحركى \n" +
                        "-الخصائص المعرفية:.\n" +
                        "قدراتهم المعرفية لا تختلف عن قدرات الأفراد العاديين بمعنى أن الطفل الذى يعانى من فقدان السمع يمتلك مستوى من الذكاء يتناسب مع مرحلته العمرية فيكون عارفا للعديد من الأمور المحيطة به مثل أفراد عائلته و طبيعة الأشياء الموجودة حوله\n" +
                        "-الخصائص الاجتماعية:.\n" +
                        "الاعاقه ليها تأثير على الخصائص الاجتماعية لدى الأفراد  من خلال التنشئه الأسرية الخاطئة للطفل من خلال الحماية الزائدة للطفل التي تجعل الطفل معتمدا على الاخرين ويعانوا من الخجل الشديد والانسحاب و مما يؤثر على مفهومهم لنفسهم وذاتهم.\n"
            ), TextSection(
                "اسباب ضعف السمع",
                "اولا الاسباب الاكثر انتشارا لضعف السمع:-\n" +
                        "١-تراكم الشمع في الأذن:.\n" +
                        "يعد تراكم الشمع من اكثر الأسباب انتشاراً لضعف السمع ولكنه قابل للعلاج وخاصه عند كبار السن\n" +
                        "٢-الضجيج:.\n" +
                        "يمكن للضجيج ان يسبب ضعف السمع من خلال التعرض المستمر للضجيج أو الاصوات المرتفعة على الرغم من ان مقاومه الناس لنقص السمع الصادر عن الضجيج متفاوتة ولكن المتوقع أن يصاب كل شخص بدرجه معينه من نقص السمع إذا تعرض للضجيج المرتفع بشكل مستمر\n" +
                        "٣- الشيخوخة:.\n" +
                        "يحد نقص السمع المرتبط بالعمر من خلال القدرة على  سماع الأصوات ذات التردد العالي عن سماع الأصوات ذات التردد المنخفض \n" +
                        "-ثانيا الأسباب الأقل انتشاراً لضعف السمع:.\n" +
