                        "هو أكثر أنواع ضعف السمع انتشاراً يحدث عندما تتلف اعصاب الاذن الداخلية ممكن بسبب العمر او اضرار الضوضاء او اي شيء اخر ويمكن علاجه باستخدام السماعات الطبية\n" +
                        "٢-ضعف السمع التوصيلي:.\n" +
                        "يحدث نتيجة انسداد الاذن الخارجية أو الاذن الوسطي ممكن بسبب السوائل أو الأورام أو شمع الاذن يمنع هذا الانسداد من وصول الصوت الى الأذن الداخلية ويمكن علاجه بالجراحة أو الأدوية \n" +
                        "٣-ضعف السمع المختلط:.\n" +
                        "هو اختلاط أو مزيج من ضعف السمع الحسي العصبي وضعف السمع التوصيلي\n"
            ), TextSection(
                "هل الطفل ضعيف السمع يتكلم؟",
                "قد يساعد سماع الأصوات والكلمات الأطفال على تعلم التحدث والفهم. إذ أن الطفل المصاب بضعف السمع يفقد هذا الأصوات، والذي يؤدي إلى حدوث مشاكل في التحدث والقراءة في المدرسة لذا من المهم أن تخضع لفحص طفلِك إذا كنتِ تعتقدين أنه يعاني من مشكلة في السمع.\n" +
                        "الطفل الذي يعاني من ضعف السمع لا يتعلم الكلام بسرعة الأطفال العاديين الذين يتمتعون بحاسة سمع طبيعية و يجد صعوبة في معرفة المعاني المختلفة للكلمة.، و قد يواجه الطفل مشكلة في فهم واستخدام جمل أكثر من الاطفال ذوي السمع الطبيعي ويواجه مشكله أيضا فى سماع نهاية الكلمات واستخدام الجمل الأكثر تعقيدا.\n"
            ), ImageSection("1/2/3.jpg"), TextSection(
                "ما علاج ضعف السمع",
                "١-التخلص من مع الاذن:.\n" +
                        "يمكن للطبيب إزالة شمع الأذن  لاستعادة القدرة على السمع وذلك عن طريق استخدام أدوات صغيرة لإذابة وشفط هذا الشمع غسل الأذن بواسطة حقنة مطاطية تحتوي على ماء دافئ.\n" +
                        "٢-التدخل الجراحي:.\n" +
                        "يشمل علاج ضعف السمع الناتج عن خلل في تركيب الأذن الوسطى مثل طبلة الأذن أو العظام السمعية.\n" +
                        "يلجأ الطبيب كذلك إلى إجراء جراحي بسيط إذا كنت تتعرض إلى عدوى متكررة في الأذن، لأن ذلك قد يسبب تراكم للسوائل خلف طبلة الأذن، فيعالجه الطبيب بإجراء يُعرف باسم أنابيب الأذن \n" +
                        "٣-سماعات الاذن:.\n" +
                        "إذا كان سبب ضعف السمع وجود مشكلة في الأذن الداخلية، أو تلف في العصب المسؤول عن توصيل الأصوات إلى المخ، فإن استخدام سماعات الأذن قد يكون له تأثير كبير على تحسن القدرة على السمع\n"
            ), TextSection(
                "نصائح للوقاية من ضعف السمع",
                "١-حماية السمع من خلال ارتداء سدادات الأذن فى حالة الذهاب للحفلات الموسيقية أو عند العمل في بيئة صاخبة.. إن استمرار التعرض للضوضاء يمكن أن يسبب تلف في حاسة السمع مع مرور الوقت.\n" +
                        "٢-تجنب سماع التلفزيون أو الموسيقى أو الراديو بصوت عال جدا. يمكنك محاولة استخدام سماعات إلغاء الضوضاء لأنها تسمح لك بالاستماع للصوت بوضوح دون الاضطرار لتعلية الصوت.\n" +
                        "٣-حاول اختيار الأنشطة الترفيهية التي لا تسبب ضوضاء عالية، \n" +
                        "٤-لا تقم بإدخال أشياء صلبة في أذنيك.\n"
            )
        )
    )

    internal val Article_21 = Article(
        id = 21,
        title = "التواصل الكلي",
        sections = arrayOf(
            ImageSection("2/1/1.jpg"),
            TextSection(
                "١) ايه هو التواصل الكلي ؟",
                "انك تستخدم مع طفلك كل طرق الاتصال الممكنة واللي تتناسب مع حالته كطريقة التدريب السمعي حيث يقوم علي تعليم الاطفال ذوي الاعاقة السمعية البسيطة والمتوسطة علي مهارة الاستماع وتطويرها لديهم والتمييز بين الأصوات أو الكلمات باستخدام الوسائل البصرية والمعينات السمعية ، طريقة التواصل الشفوي حيث نقوم فيها بتنمية مهارات الطفل علي قراءة الشفاه وفهمها ويعني ذلك أن يفهم الطفل ذي الهمم الرموز البصرية لحركة الفم و الشفاه أثناء الكلام ،طريقة التواصل اليدوي حيث يتم استخدام لغة الإشارة وتهجئة الأصابع. \n" +
                        "يجب إعطاء كل طفل من ذي الهمم فرصة تعلم جميع الأشكال الممكنة للتواصل سواء أساليب التواصل اللفظية أو اليدوية وذلك من خلال التواصل الكلي حيث يساعد علي المزج بين  توظيف البقايا السمعية إن وجدت وقراءة الشفاه ولغة الإشارة وأبجدية الأصابع والتدريب السمعي . \n" +
                        "ويجب أن نراعي مستوي نمو الطفل وتوافقه العضلي والعصبي ،وقدراته العقلية وكذلك المهارات اللغوية لديه وإكسابه المهارات التواصلية والتفاعل الإيجابي منذ طفولته المبكرة .\n" +
                        "يشتمل أسلوب التواصل الكلي علي صورة الأشكال اللغوية والحركات التعبيرية التي يقوم بها طفلك من نفسه ، وفي الاتصال الكلي يتاح فرصة أمام طفلك لتطوير وتنمية اي جزء تبقي لديه من السمع ،ومن خلال المعين السمعي الذي يستخدمه.\n" +
                        "من خلال التواصل الكلي نقوم بدمج كل طرق التواصل الممكنة وتستخدمها لتعزيز قدرات الأطفال علي التواصل مع الآخرين وفهم العالم المحيط بهم والاندماج فيه .\n" +
                        "في هذه الطريقة نقوم بدمج الكلام ،والإشارات وتهجئة الأصابع ، ولغة الإشارة حتي نسهل للطفل عملية التواصل .\n" +
                        "يعتبر التواصل الكلي أسلوب للاتصال وليس طريقة للاتصال حيث ظهر التواصل الكلي بسبب ظهور بعض السلبيات في كل طريقة من طرق التواصل المختلفة لما نستخدمها  لوحدها.\n" +
                        "وكذلك الفروق الفردية والإمكانات بين الاطفال ذوي الهمم والاختلاف الواضح بينهم والطرق المتاحة لكل طفل في تعلم طريقة تختلف عن طفل آخر . واختلاف موقف الاتصال  يحتاج طرق معينة يتم استخدامها من قبل الطفل ذي الهمم .\n" +
                        "عندما نستخدم اللفظ والإشارة معا اثناء الحديث مع الطفل ذي الهمم  فإن ذلك يساعد في التغلب علي الثغرات التي  قد تنتج عندما نستخدم اي منهما بمفرده ،كما أن هذه الطريقة تستجيب بشكل أفضل الخصائص التي يتميز بها كل طفل ،فالأطفال الذين يجيدون استخدام أبجدية الإشارة نستخدم اللفظ وأبجدية الأصابع أثناء الحديث معهم ، ولكن الأطفال الذين يجيدون لغة الإشارة عند الحديث معهم نستخدم اللفظ مع الإشارة الكلية .\n" +
                        "\n" +
                        "يتضح من ذلك أن عدم قدرة الطفل علي السمع ودرجة الفقدان السمعي والعمر الذي حدثت فيه الإصابة ومدى توافر الخدمات المختلفة والتدريب علي النطق والتدريب السمعي و قواميس لغة الإشارة والمعينات السمعية المختلفة تعتبر عوامل هامة في تحديد طريقة التواصل الطريقة المناسبة التي يجب أن نستخدمها مع الطفل .\n" +
                        "تعد طريقة التواصل الكلي هي الطريقة الأكثر مناسبة لمختلف الأطفال الذين فقدوا سمعهم، حيث أنها تسهل الاتصال فهي توفر فرصة للطفل ذوي الهمم ليتعلم لغة الإشارة من جهة وتنمية قدراته اللفظية من جهة أخرى.\n" +
                        "كذلك  أيضا فإن طريقة التواصل الكلي  تجعل الطفل ذوي الهمم أكثر أهلية للنجاح في الاندماج الاجتماعي، حيث أنها  تسهم في التغلب على الصعوبات التي تنتج عن عدم إتقان الناس السامعين للغة الإشارة من جهة  والمساعدة في توضيح ما يوجد في لفظ الطفل ذوي الهمم من عيوب وعدم وضوح.\n"
            ),
            TextSection(
                "٢) أهداف التواصل الكلي :",
                "1.\tيسهل من عملية التواصل ،حيث يساعد في زيادة قدرة الطفل ذوي الهمم على استخدام القدرات النطقية لديه بشكل جيد مما يمكنه مستقبلا من  تقبل هذه القدرة النطقية بشكل وظيفي.\n" +
                        "2.\tيفتح التواصل الكلي  قنوات اتصال رئيسية بالسرعة والفاعلية الممكنة، وذلك لأنه يعتمد على أكثر من قناة تواصل سواء تواصل يدوي أو شفاهي بالإضافة للتواصل البصري وما لديه من بقايا سمعية في ضوء أسس وقواعد كل طريقة من طرق التواصل.\n" +
                        "3.\tيعمل التواصل الكلي علي استثارة الدافعية وزيادة مستوى الانتباه لدي الطفل ، حيث يكون الطفل ذوي الهمم  أمام موقف تواصل شامل يتوافق مع ما لديه من خبرات وقدرات سمعية.\n" +
                        "4.\tيسهم التواصل الكلي في زيادة مستوى التواصل الكلامي ومدى وضوحه باعتبار أن التواصل الكلي يعتبر التواصل اللفظي القائم على مدى إمكانية استخدام اجهزة النطق لدى الأطفال ذوي الهمم استخداما فعالا مع التواصل اليدوي، اي نستخدم اللفظ مع الإشارة .\n" +
                        "5.\tاستغلال البقايا السمعية، ويعد هذا هو الهدف التربوي الأمثل للتواصل الكلي. \n"
            ),
            ImageSection("2/1/thumb.jpg"),
            TextSection(
                "٣) مميزات التواصل الكلي : ",
                "1.\tلا يلغي التواصل الكلي  استخدام قراءة الشفاه.\n" +
                        "2.\tلا يلغي التواصل الكلي استعمال الأجهزة  السمعية بل يعمل على استغلال أي بقايا سمعية في إدراك الصوت حتى يصبح واضحا في ذهن الطفل ذوي الهمم .\n" +
                        "3.\t يستطيع الطفل ذوي الهمم  من خلال أسلوب التواصل الكلي  اكتساب لغة الإشارة بسرعة أكبر كما يتيح له التعبير عن حاجاته. \n" +
                        "4.\tيصبح من خلال أسلوب التواصل الكلي لدى المدرسة طفل ذوي همم أكثر توافقا مع البيئة المحيطة به.\n" +
                        "5.\t باستخدام التواصل الكلي للحديث والإشارة فإن كل أسرة  لديها طفل ذوي همم تصبح بيئتهم عادية مثل بيئة العاديين.\n"
            )
        )
    )
    internal val Article_22 = Article(
        id = 22,
        title = "قراءة الشفاه",
        sections = arrayOf(
            TextSection(
                "ما هي مهارة قراءة الشفاة؟",
                "هي مهارة تستلزم استخدام حاسة البصر لفهم الكلام ودا ليفهم الصم وضعاف السمع حركات الشفاه واللسان والفك أثناء الكلام من قبل الآخرين، ويعتمد نجاح  الطريقة دي على مدى فهم الصم وضعاف السمع للمثيرات البصرية المصاحبة للكلام زي تعبيرات الوجه وحركة اليدين ومدى سرعة المتحدث ومدى اللغة وموضوع الحديث للمعاق، ومدى مواجهة المتحدث لاصم وضعيف السمع وكمان القدرة العقلية للمعاق سمعياً وعشان كده مهارة قراءة الشفاة تحتاج لتدريب وتعليم للصم وضعاف السمع."
            ),
            TextSection(
                "ما هي شروط قراءة الشفاة؟",
                "-يجب ان تكون درجة الابصار عند الطفل الاصم عادية.\n" +
                        "2-يجب ان يكون المتكلم مقابل الطفل ليشاهد حركة الشفاة.\n" +
                        "3-ينبغي ان يتم التكلم بصورة طبيعية وعادية.\n" +
                        "4-يجب ان يكون النطق واضح ومفهوم ومنبالغش في فتح الفم.\n" +
                        "5-لا يختفي المتكلم عن بصر الاصم او ضعيف السمع.\n" +
                        "6-لا يتحدث المتكلم وهو متجه نحو الحائط او الصبورة.\n" +
                        "7-ان يوجه المتكلم نظره نحو الاصم ودا لان النظر له دور كبير في التعيين وشد الانتباه لضمان الاستمرار والتواصل.\n" +
                        "8-مراعاة مستوي الاصم ومرحلة نموه.\n" +
                        "9- المسافة التي تفصل بين الاصم والمتكلم تكون مسافة معقولة ودا ليستطيع الطفل تركيز انتباهه علي ملامح الوجه.\n" +
                        "10-محاولة التقليل من المشتات.\n" +
                        "11-وجود ضوء علي وجه المتكلم  عشان حركات الوجه والشفتين تكون واضحه للاصم.\n"
            ),
            TextSection(
                "اي الخطوات التي يجب مراعتها لقراءة الشفاة؟",
                "-يجب ان تنطق الكلمة اثناء تطلع الاصم الي الوجه مثلا نقول له \"قف\"فيكون ذلك عندما يتطلع الي وجهة.\n" +
                        "2-يجب ان تتكلم العينان كما تتكلم الشفاة مثلا اذا قولنا للاصم \"تعال\" بحيث تكون العينان فيها الدعوة اثناء مد اليدين مع الضغط علي كلمة\"تعال\"وبتكرار نفس الموقف يفهم الاصم كلمة تعال عندما تنطق بها الشفتان.\n" +
                        "\n" +
                        "3-يجب ان يكون الكلام واضح وبطئ نوعا ما من المتكلم بشرط انه ميبالغش في النطق او في حركات الشفاة او فتح الفم.\n" +
                        "4-يبدأ بالكلمات السهلة والتي يمكن نطقها ورؤيتها بسهولة ولها ارتباط بالواقع.\n"
            ),
            TextSection(
                "ما هي طرق تدريب الصم علي مهارات قراءة الشفاة؟",
                "-الطريقة التحليلية:\n" +
                        "فيها يركز الاصم علي كل حركة من حركات شفتي المتكلم وبعدين ينظمها مع بعضها ليفهم المعني المقصود.\n" +
                        "2-الطريقة التركيبية:\n" +
                        "فيها يركز الاصم علي معني الكلام اكثر من تركيزه علي حركة شفتي المتكلم.\n" +
                        "3-طريقة روشيسير:\n" +
                        "هي دمج طريقه هجاء الاصابع مع قراءة الشفاة ودي طريقة مملة ودا لان الاصم يقوم  بالتعبير عن كل حرف بهجاء الاصابع فيشعر المشاهد بالملل فيكون عليه التركيز بعينه علي كل حرف يقام التعبير عنه بهجاء الاصابع.\n" +
                        "والتتدريب علي قراءة الشفاة مهم جدا مع الالتزام ب:\n" +
                        "-البدء بالامور المتعلقة بحياة الاصم وحاجته الخاصة.\n" +
                        "-ناخد بالنا ان فيه بعض الحروف الساكنة تكون في صورة حركية متشابهة علي الشفاة مثل:حرف(م-ب-ت-د-ح).\n" +
                        "-نساعد الاصم علي التفرقة بين الحروف المتشابهة في طريقة اخراجها من خلال المرآة وملاحظة حركات الشفاة.\n"
            ),
            TextSection(
                "ما هي انواع التدريب علي قراءة الشفاة؟",
                "-التدريب الفردي:\n" +
                        "فيه يتم التدريب علي الكلمات والحروف بصورة مفردة ودا حسب قدرة الاصم ودرجة الفقدان السمعي .\n" +
                        "2-التدريب الروتيني:\n" +
                        "هنستغل فيه ماتعود عليه الطفل في حياته اليومية من عمل اشياء معينة او الذي تعود عليه من تلقي بعض الاوامر زي اجلس ,تعالي...\n" +
                        "3-التدريب الجماعي:\n" +
                        "بعد ان يصل الاصم الي فهم مجموعة من الكلمات والجمل القصيرة من التدريب الفردي والتدريب الروتيني يمكن للمعلم او الاخصائي تدريب مجموعة من التلاميذ تدريب جماعي بس بشرط ان المجموعة تكون صغيرة لا تزيد عن 8 ولا تقل عن 5 وان تكون المجموعة متجانسة في القدرات والميول وعدم الاطالة في زمن التدريب .\n"
            ),
            TextSection(
                "ما هي مراحل تعلم قراءة الشفاة للاصم؟",
                "-مرحلة التطلع الي الوجه:\n" +
                        "تعتمد علي النظر ودرجة القرب بين الاصم والمتكلم ودرجة الاضاءة في المكان.\n" +
                        "والمرحلة دي من اسهل المراحل لمعرفة وتذكر الكلمات والجمل.\n" +
                        "2-مرحلة الربط(بدء الفهم):\n" +
                        "تعتمد علي الربط بين مايراه علي الوجه من تعبيرات وبين الموقف والمرحلة دي لها اهمية كبيرة في تكوين العادات مثل:\n" +
                        "-الابتسامة في وقت الفرح.\n" +
                        "-التكشير في حالة الحزن.\n" +
                        "3-مرحلة الفهم المعنوي(الفهم المجرد):\n" +
                        "تعتمد علي مانتحدث به من كلمات دون النظر الي مانتحدث عنه زي(باب-شباك-كتاب-قلم-ساعة-بابا-ماما....)\n" +
                        "بمعني ان الاصم يقرأ الالفاظ الجديدة بواسطة قراءة الشفاة ويكون وصول الاصم الي المرحلة دي تعبر عن تقدمه في الكلام ورغبته في زيادة معلوماته.\n"
            ),
            TextSection(
                "ما هي قواعد قراءة الشفاه للاتصال مع الاصم؟",
                "-جذب الانتباه.\n" +
                        "-مواجهة الشخص والنظر اليه مباشرة.\n" +
                        "-ابقاء الجسم في حالة ساكنة قدر الامكان واستخدام بعض الايحات البسيطة للتوضيح.\n" +
                        "-رؤية الفم بوضوح ,ميكونش فيه دخان او اقلام او طعام عشان متمنعش رؤية الفم.\n" +
                        "-الوقوف بمواجهة الضوء.\n" +
                        "-التكلم بوضوح وببطئ اقل من العادي وبرده منبالغش في ده .\n" +
                        "-اعادة الجملة اكتر من مرة ودا لو الامر ضروري وبصورة مختلفة.\n" +
                        "-استخدام جمل قصيرة ومفيدة.\n" +
                        "استخدام الكلام المباشر وحاول منع اي تشوش او ضوضاء محيطة بك.\n" +
                        "-استخدام الكتابة اذا كان الشخص الاصم يجد صعوبة في فهمك او قراءة شفاهك.\n" +
                        "-عدم الصراخ,هذا يسبب تشويش وازعاج للشخص المستعمل المعينات السمعية.\n" +
                        "-لازم تبقي صبور وهادئ وتظهر الاهتمام.\n" +
                        "-كن حساس مع الشخص الاصم.\n" +
                        "-ابتعد لمسافة مناسبة ليست بعيدة ولا قريبة وبنفس مستوي الصوت.\n" +
                        "-تحسين جودة الصوت وذلك بوجود غرفة مفروشة بشكل جيد لمنع وجود صدي.\n" +
                        "-الاتصال العيني : الاتصال مباشرة مع الاصم.\n"
            ),
            TextSection(
                "ما هي مزايا قراءة الشفاة؟",
                "تركز قراءة الشفاة علي تعليم الصم وضعاف السمع والتدريب الصحيح للنطق ومهاراته ومحاولة توفير بيئة تعليميه تشابه بين السامعين في مدارس وفصول التربية الخاصة.\n" +
                        "وتتلخص مزايا الطريقة دي في:\n" +
                        "-اعتبار الكلام هو قناة التواصل الرئيسية ودا بالاستفادة بالسمع المتبقي ولازم تنميته من خلال قراءة الكلام.\n" +
                        "-الاصم وضعيف السمع  قادرين علي التعلم اللفظي ودا لو تم تدريبهم من البداية علي النطق ودا لان جهاز النطق المفروض انه سليم.\n" +
                        "- لغة الاشارة مبتساعدش الاصم علي التعبير عن المفاهيم المجردة بشكل كاف.\n" +
                        "-الصم محاطون بناس مبيستعملوش لغة الاشارة ومش بيفهموها .\n" +
                        "- تعليم الكلام للصم يساعد علي التقليل من الشعور بالعزلة والتعايش مع السامعين .\n" +
                        "-قدرة الاصم علي الربط بين صوت معين والحركة التي تصدر عن الشفاة او الحنجرة او اللسان .\n" +
                        "-ترجمة هذه الحركات الي اشكال صوتية(الحروف).\n"
            ),
            TextSection(
                "ما هي عيوب قراءة الشفاه؟",
                "-صعبة للاطفال الصم وده لان الاطفال مش بيسمعوا الاخرين وهما ينطقوا بالكلام.\n" +
                        "-لا يمكن للصم ضبط محاولتهم الصوتية لتقليد الكلام الصادر عن الاخرين.\n" +
                        "-عدد كبير من الكلمات في اللغة يشبه بعضه عند النطق به.\n" +
                        "- المتكلم مش بيرتاج لما الاصم ينظرالي فمه اثناء الكلام.\n" +
                        "-صعوبة قراءة الشفاة في حالة الاضاءة الضعيفة او لما بيكون المتحدث غير مواجه لمن يتحدث اليه ويغطي وجهه وفمه.\n"
            ),
            TextSection("مخارج الحروف:", "\n"),
            ImageSection("2/2/1.jpg"),
            TextSection(" ", ""),
            ImageSection("2/2/2.jpg"),
            TextSection(" ", ""),
            ImageSection("2/2/3.jpg"),
            TextSection(" ", ""),
            ImageSection("2/2/4.jpg"),
            TextSection(" ", ""),
            ImageSection("2/2/5.jpg"),
            TextSection(" ", ""),
            ImageSection("2/2/6.jpg"),
