            ImageSection("2/2/11.jpg"),
        )
    )
    internal val Article_23 = Article(
        id = 23,
        title = "لغة الاشارة",
        sections = arrayOf(
            ImageSection("2/3/1.jpg"),
            TextSection(
                "١)ما هي لغة الإشارة؟",
                "لغة الإشارة هي اللغة الطبيعية لذوي الهمم السمعية حيث تعبر عن الكلمات والمفاهيم والعبارات من خلال حركات اليدين وضعهم، وتعتبر لغة الإشارة وسيلة اتصال تعتمد اعتمادا كبيرا على التناسق بين العين وقدرة الجسم على الحركة.\n" +
                        "تساعد هذه اللغة الطفل ذوي الهمم السمعية في التعبير عن أي فكرة يعبر عنها باللغة المنطوقة ، وتختلف لغة الإشارة من مجتمع إلى آخر. \n" +
                        "بل أن هناك بعض الاختلافات والتي قد نجدها في داخل المجتمع الواحد ،وتعد لغة الإشارة لغة كاملة تسمع بالعين وتنطق باليدين .\n"
            ),
            TextSection(
                "٢)بعض الاعتبارات لمن يتعلم لغة الإشارة:",
                "1.\tأن يكون لديه القناعة بأن لغة الإشارة  لغة مهمة، ومسلم بها وجب تعلمها وضرورة توافر الرغبة في تعلم هذه اللغة.\n" +
                        "2.\t يجب أن تكون صادقا في تعاملك مع الصم، وأن تكون ودودا وأن تكون صارما في بعض الوقت.\n" +
                        "3.\t  إن كتساب الفرد للمفردات اللغوية الإشارية وزيادة ثروته اللغوية سيساعده على تكوين الجمل وسرعة المحادثة.\n" +
                        "4.\t لغة الإشارة ليست صعبة وهي سهلة الاكتساب إذا ما توفرت الإرادة والثقة بالنفس.\n" +
                        "5.\t إن التحدث مع أصحاب اللغة الأصليين سيتيح فرصة التعرف على لغتهم وبالتالي التحدث بطلاقة ويسر فاكتساب اللغة يأتي بالممارسة الفعلية لها وليس بحفظ مفرداتها فقط.\n" +
                        " ضرورة الاحتكاك بالأفراد الصم فالتحاور معهم وحضور مناسباتهم والاهتمام بأمور حياتهم اليومية سيتيح إمكانية تبادل الأفكار وتبادل الخبرات\n"
            ),
            TextSection(
                "٣)أسس وقواعد يجب معرفتها لمن يستخدم لغة الإشارة:",
                "1.\tعندما تتحدث مع صديق  بوجود شخص ذوي همم سمعية  فاستخدم لغة الإشارة بهدف إشراكه في الحديث.\n" +
                        "2.\t لا تبالغ في حركة الشفاه، تكلم بشكل طبيعي  وتذكر أن ٣٠٪ فقط  من كلامك يمكن أن يفهم لذا يجب استخدام لغة الإشارة.\n" +
                        "3.\tتأكد من وجود إضاءة مناسبة عندما تتحدث بلغة الإشارة وتجنب الجلوس بوضع يكون الضوء أو الشمس على عيون المتلقي.\n" +
                        "4.\t لا تغطي فمك إلا إذا تطلبت الإشارة ذلك حتى لا تحجب قراءة الشفاه. \n" +
                        "5.\tفكر بطريقتهم وتكلم بلغتهم وبأسلوبهم حتى تتعرف على مواطن القصور لديهم وتعدلها.\n" +
                        "6.\tكن صبورا وتفاعل مع إشارتك ليظهر التعبير على وجهك وجسمك.\n"
            ),
            TextSection(
                "٤) ما هي فوائد لغة الإشارة ؟",
                "1.\tهي اللغة الطبيعية التي من خلالها يستطيع ذوي الهمم السمعية ان يعبر عن نفسه واحتياجاته.\n" +
                        "2.\t تساعد في توضيح وتوصيل العديد من المفاهيم المادية والمعنوية.\n" +
                        "3.\tتعد الطريقة الاسرع في توصيل المعلومات للفرد ذوي الهمم السمعية\n"
            ),
            TextSection(
                "٥)ما هي عيوب لغة الإشارة؟",
                "1.\tلا يمكن ان نستخدمها في الظلام .\n" +
                        "2.\tسهوله وسرعه تعلم لغة الإشارة لدى الطفل سوف يقلل من عمليه تعلم اللغة المنطوقة.\n" +
                        "3.\tاغلب الأفراد في مجتمع العاديين لا يجيدون استخدام لغة الإشارة\n"
            ),
            TextSection(
                "٦)ما هي وظائف اللغة للأصم :",
                "1.\tالتواصل بين الناس وتبادل المعرفة والمشاعر وإرساء دعائم التفاهم والمشاركة في الحياة.\n" +
                        "2.\tالتعبير عن حاجاته المختلفة .\n" +
                        "3.\tالنمو الذهني المرتبط بالنمو اللغوي وتعلم اللغة الشفوية أو الاشارية يولد لدي الفرد المفاهيم والصور الذهنية .\n" +
                        "4.\tارتباط اللغة بنظم حضارية تضرب عمقا في التاريخ والمجتمع .\n" +
                        "5.\tالوظيفة النفسية فاللغة تنفس عن الإنسان وتخفف من حدة الضغوطات الداخلية التي تواجهه ويبدو ذلك في مواقف الانفعال والتأثر .\n" +
                        "لذلك فإن تطوير وسائل التعبير لدي الفرد ذوي الهمم وإزالة الصعوبات التي تواجهه حتي يستطيع التعبير عن نفسه وحاجاته وميوله ، مما يساعده علي الخروج من عالم العزلة والخوف والإحباط إلي عالم منفتح علي الناس ، وعلي المحيط الذي يعيش فيه ، وذلك يودي إلي التوازن والتكيف وتنمية قدراته للمساهمة في الحياة الاجتماعية ومساعدته علي البذل والعطاء في المجالات المعرفية والمهنية والثقافية.\n"
            ),
            TextSection(
                "٧)ما هي انواع لغة الإشارة:",
                "1.\tالإشارات ذات الدلالة : \n" +
                        "يدل ظاهرها أو شكلها علي الفكرة التي يحاول ذوي الهمم السمعية التعبير عنها ، بالتمثيل بالقلم للتعبير عن الكتابة .\n" +
                        "2.\tالإشارات التقليدية: \n" +
                        "إشارات يصعب علي الشخص العادي فهمها دون أن يعلم معناها كإشارة البن بحركة طحن البن في الآلة .\n" +
                        "3.\tالإشارات الوصفية : \n" +
                        "عبارة عن إشارات يدوية تلقائية تصف فكرة معينة وتساعد علي توضيح صفات الشيء مثل فتح الذراعين للتعبير عن الكثرة وهذه يستخدمها ذوي الهمم السمعية والسامعين .\n" +
                        "4.\tالإشارات الغير وصفية : \n" +
                        "عبارة عن إشارات لها دلالة خاصة ،وتكون بمثابة لغة خاصة متداولة بين الصم مثل الإشارة بالإبهام إلي أعلي للدلالة علي شيء حسن .\n" +
                        "5.\tالإشارات العامة : هي إشارات مستخدمة ومتداولة في المجتمع في الاتصال بين ذوي الهمم السمعية والآخرين وليست مرتبطة بمهنة معينة أو تخصص معين. \n" +
                        "6.\tالإشارات التخصصية : هي إشارات أكثر ارتباطا بالتخصصات الدراسة المختلفة أو المهن المتنوعة ، حيث أن لكل تخصص لغته ولكل مهنة لغتها ،فهي تكون اشارات مرتبطة بلغة التخصص الدراسة والمهنة\n"
            ),
            ImageSection("2/3/4.jpg"),
        )
    )

    internal val Article_31 = Article(
        id = 31,
        title = "الادراك السمعي",
        sections = arrayOf(
            ImageSection("3/1/thumb.jpg"),
            TextSection(
                "مفهوم الإدراك السمعي (Auditory Perception):",
                " هو القدرة على تحديد وتفسير المعلومات والمعاني وربطها بالأصوات، والتييتم استقبالها عبرالسمع، والعضو الحسي \" الأذنين \" على شكل موجات ترددية يمكن سماعها وتنتقل عبر الهواء، أو وسائل أخرى ."
            ), TextSection(
                "أهمية الإدراك السمعي :",
                "الإدراك السمعي أحد أهم العوامل التي تساعد الإنسان على التكيف والتوافق مع البيئة وذلك من خلال :\n" +
                        " فهم حديث الآخرين وإصدار الاستجابات المناسبة.\n" +
                        "  تحقيق عمليات التعلم، التطور، التثقيف.\n" +
                        "  تحديد الزمان والمكان وذلك بإعطاء معاني للأشياء من حيث قربها وبعدها أو وجهتها، ووقت حدوثها. \n" +
                        " حماية النفس من خلال تحديد مصادر التهديد الصوتية وتجنبها مثل صوت الحيوانات أو غيره\n"
            ), TextSection(
                "مراحل الإدراك السمعي :",
                "تمر عملية الإدراك السمعي بثلاثة مراحل أساسية هي:\n" +
                        "الاستقبال :\n" +
                        " تتلقى في هذه المرحلة الأذن المعلومات على شكل موجات صادرة عن الإنسان أو وسائل مختلفة أخرى، كمرحلة أولى من مرحلة الإدراك السمعي وأن الهواء عامل رئيسي في هذه المرحلة إيساعد على نقل الموجات واستقبالها عبرالأذن إلى الأذن الداخلية. \n" +
                        "النقل :\n" +
                        " تنقل الخلايا العصبية في هذه المرحلة إشارة معينة والتي تشكل المعلومات تم سماعها وتوصلها إلى الجسم .\n" +
                        "المعالجة :\n" +
                        " تُرسَل المعلومات في هذه المرحلة إلى القشرة السمعية في الفص الصدغي ليتم معالجتها والتفاعل معها من خلال إصدار الاستجابات الصحيحة المتوافقة معها\n"
            ), TextSection(
                "كيف يعمل الإدراك السمعي ؟",
                "يتطلب فهم عملية الإدراك السمعي بيان التشريح العضوي للجهاز السمعي وفيما يأتي تفاصيله:\n" +
                        "الأذن الخارجية :\n" +
                        " تتكون الأذن الخارجية من الصيوان والقناة السمعية وطبلة الأذن تعمل طبلة الأذن على نقل الأصوات على شكل موجات وتبسيط موجات ضغط الهواء مما يسمح بتمييز الأصوات. \n" +
                        " الأذن الوسطى : \n" +
                        "تقع الأذن الوسطى خلف طبلة الأذن مباشرة مكونة تجويف مملوء بالهواء وتتألف من ثلاثة عظام صغيرة والتي تساعد في نقل الأصوات من طبلة الأذن إلى الأذن الداخلية. \n" +
                        " الأذن الداخلية :\n" +
                        "تضم الأذن الداخلية أنبوب حلزوني الشكل مملوء بالسوائل يطلق عليه اسم قوقعة، وهو العضو الرئيسي الموصل للإشارات السمعية للدماغ والمتكون من غشاء قاعدي والذي يضم خلايا الشعر ( الكلام المستقبل ). \n" +
                        "وتحدث عملية الإدراك السمعي عندما تنتقل الأصوات عبر الأذن الخارجية إلى الوسطى ثم الداخلية و تُحفز اهتزازات المستقبلات السمعية إرسال إشارات كهربائية إلى العصب السمعي المرتبط بالمركز السمعي في الدماغ ليترجم الدماغ النبضات الكهربائية إلى معاني ومعلومات معروفة ومدركة .\n"
            ), TextSection(
                "مهارات الإدراك السمعي :",
                " يتضمن الإدراك السمعي أربع مهارات أساسية هي:\n" +
                        " التمييز:\n" +
                        " يشكل التمييز السمعي قدرة الفرد على تحديد الفروق بين الأصوات المتشابه والتي تكون متشابهة باللفظ ومختلفة في المعنى.\n" +
                        " الإغلاق :\n" +
                        "يشكل الإغلاق السمعي قدرة الفرد على فهم واستيعاب الكلمات أو النصوص التي تنطق بالرغم من أنها تحمل نقص معين.\n" +
                        " التسلسل :\n" +
                        " يشكل التسلسل السمعي قدرة الفرد على تذكر ترتيب الأصوات بنمط محدد.\n" +
                        " الربط :\n" +
                        " يشكل الربط السمعي قدرة الفرد على إكمال الجمل بحيث تكون مترابطه في تركيبها اللغوي.\n"
            ), TextSection(
                "التمييز السمعي :",
                "هو قدرة الشخص على التعرف على أوجه التشابه والاختلاف بين الأصوات المختلفة، إذ يمكن للتمييز السمعي أن يسمح للناس بالتمييز بين صوتيات الكلمات والصوتيات هي أصغر وحدة من وحدات الصوت في لغة معينة، كما يساعد التمييز السمعي الفرد على التفرقة بين الكلمات والأصوات المتشابهة ويمكن أن تشمل أهم مهارات التمييز السمعي ما يأتي :\n" +
                        " جودة اللغة الشفوية : الأشخاص الذين لديهم تمييز سمعي جيد يتمتعون بمهارات اللغة الشفوية الجيدة سواء من حيث القدرة على التعبير، صياغة الجمل يشكل صحيح، الترتيب الجيد للأفكار والنطق الصحيح للكلمات.\n" +
                        " القدرة على تمييز الأصوات والحروف :\n" +
                        "هو قدره الشخص على تمييز أصوات وحروف الكلمات بطريقة صحيحة وهذا يعني أن الأطفال الذين يعانون من ضعف مهارة التمييز السمعي لا يستطيعون تمييز الأصوات والحروف.\n" +
                        " سعة الخيال وتسلسل الأفكار :\n" +
                        "  هو قدرة الشخص على التخيل وتنظيم أفكاره جيدًا بصورة مرتبة ونظام متسلسل إذ أنه لا يشعر بالتأتأة كالأشخاص الذين يعانون من ضعف في مهارة التمييز السمعي.\n" +
                        " القدرة على التفكير الناقد :\n" +
                        " الشخص الذي لديه تمييز سمعي جيد يمتلك مهارة التفكير الناقد التي تكون ناتجة عن سماع أفكار وآراء من حوله بوضوح شديد حول أي موضوع من المواضيع المطروحة .\n" +
                        " امتلاك ذاكرة سمعية جيدة :\n" +
                        "هو امتلاك الشخص لذاكرة سمعية جيدة وهذا يساعده على الاحتفاظ بالمعلومات لمدة طويلة دون نسيان، وهذه المهارة مهمة جدًا للأطفال لزيادة النجاح الدراسي.\n" +
                        " قوة الانتباه والتركيز :\n" +
                        "هي قدرة الشخص على الانتباه والتركيز الجيد والتي تزيد بفضل قدرته على الاستماع لمختلف الموضوعات بدقة كما أن هذه المهارة تزيد لدى الطفل من خلال قدرته على الاستماع الجيد للأناشيد والقصص المختلفة.\n" +
                        "حيث ان :\n" +
                        "إن الطفل الذي يعاني من مشاكل معينة في التمييز السمعي، يعاني من صعوبة في التمييز بين الاختلافات البسيطة في أصوات الكلمات، وهذا يجعله لا يستطيع في كثير من الأحيان فهم ما يقوله له الأشخاص الآخرين من حوله، ويزداد الأمر صعوبة في البيئات شديده الضوضاء .\n" +
                        "إن وجود المهارات السمعية لا سيما مهارات التمييز الصوتي، ينمي لدى الطفل مهارات أخرى كاللغة والقراءة وهذا يعني أن هذه المهارات تتأثر إذا كان الطفل يعاني من مشاكل في الوعي الصوتي.\n" +
                        "كما يمكن للأطفال الذين يعانون من مشاكل في التمييز السمعي أن يواجهوا صعوبة في تذكر تسلسل الكلمات، لذا قد يكتبون بشكل غير صحيح أيضًا ويذكر ان هناك أربعة أنواع من المهارات السمعية الأساسية عند المرء وهي:\n" +
                        " التمييز السمعي : هي القدرة على ملاحظة ومقارنة الأصوات والتمييز بينها لذا فإن الطفل الذي يعاني من صعوبة في التمييز السمعي يخلط بين الكلمات المتماثلة مثل السبعين والسابعة ويواجه صعوبة في تعلم القراءة واتباع التوجيهات حتى وهو منتبه للمتحدث.\n" +
                        " التمييز السمعي بين الشكل والخلفية : هي القدرة على التقاط الأصوات المهمة من الخلفيات الصاخبة، لذا فإن الطفل الذي يعاني من صعوبة التمييز السمعي بين الشكل والخلفية لا يستطيع التقاط الكلمات والمحادثات الهامة حين يكون هناك ضوضاء. \n" +
                        " الذاكرة السمعية :\n" +
                        "هي قدرة الشخص على تذكر ما سمعه بعد مرور فترة من الزمن وتشكل الذاكرة السمعية الذاكرة قصيرة وطويلة المدى، لذا فإن وجود صعوبات مرتبطة بالذاكرة السمعية تجعل صاحبها يعاني من صعوبة في تذكر أسماء الأشخاص وحفظ أرقام الهواتف واتباع التوجيهات المعقدة. \n" +
                        " التسلسل السمعي :\n" +
                        "هي قدرة الشخص على فهم ترتيب الكلمات لذا فإن الأشخاص الذين يعانون من صعوبات في التسلسل السمعي يجدون صعوبة في إدراك الأرقام والتمييز بينها مثل: 93 و 39 كما لا يمكنهم في كثيرمن الأحيان إكمال سلسلة من المهام بالترتيب الصحيح لها.\n" +
                        " التاهيل التخاطبي :\n" +
                        "هو برنامج يهدف إلى تدريب الأشخاص الذين يعانون من ضعف سمع يتـراوح من المــتوسط إلى الشديد ولديهم بقــايــا سمعية يمكن الاستفادة منها في تكوين ثروة لـغوية استقـبالية وتعبـيرية ، على الإحسـاس والــوعي بالأصــوات و تحسين الــمهارات السمــعية عـلى مســتوى التــعرف الســمعي للأصـوات البيئية وامدادهم بالــمثـيرات الســمعية لتـنمية مهارات الانتباه السمعي والإدراك السمعي والذاكرة السمعية .\n" +
                        " أهداف برنامج التأهيل التخاطبي :\n" +
                        "• تحسين المهارات السمعية على مستوى الاستجابة التلقائية للأصوات .\n" +
                        "• تحسين المهارات السمعية على مستوى تحديد مصدر واتجاه الصوت .\n" +
                        "• تحسين المهارات السمعية على مستوى التعرف السمعي والتمييز السمعي للأصوات البيئية وغيرها .\n" +
                        "• تحسين المهارات السمعية على مستوى تمييز أصوات الحروف الهجائية ومقاطع الأصوات والكلمات .\n" +
                        "• تحسين مهارات الطفل السمعية على مستوى الفهم عن طريق السمع .\n" +
                        "• تحسين مهارات اللغة الاستقبالية على مستوى المفردات والأفعال الأساسية والأوامر البسيطة .\n" +
                        " مراحل برنامج التأهيل التخاطبي :\n" +
                        "المرحلة الأولى ويتم التدريب فيها على .\n" +
                        "1 -الاستــجابة التـلـقائية للأصــوات\n" +
                        "2 -الاستجابة المشروطة للأصوات\n" +
                        "\n" +
                        " المرحلة الثانية التعرف على الأصوات :\n" +
                        "يتم التدريب على هذه المهارة بعرض نماذج متنوعة الشدة الصوتية، مع شرح ما تحدث من صوت يتم بعد ذلك استخدامها في تمرين عملي تقوم فيه الحالة بحركة ما عند سماعة الصوت وتتوقف الحركة بعد اختفاء الصوت مع ملاحظة أن لا يرى الطفل المدرب وهو يحدث الصوت .\n" +
                        " المرحلة الثالثة : تحديد مصدر الأصوات أو مكانها :\n" +
                        "• استمرارا للمهارة السابقة وبعد اكتساب الحالة قدرة التعرف على وجود الصوت من عدمه ، يمكن أن تبدأ الحالة في تحديد مصدر الأصوات من حيث الاتجــاه والمكان .\n" +
                        " المرحلة الرابعة تمييز الأصوات :\n" +
                        "يعد التدريب على تمييز الأصوات والتعرف عليها وتقليدها مهارة ضرورية لنمو مهارات الاستماع المؤثر على تعلم اللغة.\n" +
                        " نماذج الأصـوات متنـوعة وينبغي تعـلم التـميـيز بينهـا مثــل : الأجهـزة المنزلية ، الألعاب، الحيوانات والطيور ، الألآت والمحركات ، أصوات أفراد العائلة ، الأصوات الموسيـقـية ، الحــروف ، الكلمـات ،العبارات القصيرة والجمل لذا ينبغي التدرج في التدريب على التعرف والتمييز بين تلك الأصوات كما يلي :\n" +
                        "تمييز الأصوات البيئة المألوفة\n" +
                        "مطابقة صوت بصورة\n" +
                        "تمييز صوت من مجموعة\n" +
                        "تمييز الأصوات المختلفة\n" +
                        "تمييز الأصوات المتشابهة\n" +
                        "تقليد الصوت\n" +
                        "تنفيذ الأمر الصوتي\n" +
                        " ثانياً : تدريبات النطق والكلام : \n" +
                        "تختلف المهارات التي يتم التدريب عليها في البرنامج باختلاف البقايا السمعية والقدرات العقلية خاصة معامل الذكاء وقدرات الحالة الإدراكية والتواصل البصري والانتباه .\n" +
                        "و يركز البرنامج في بداية مراحل العلاج على التدريب المنظم الذي يهدف إلى إخراج أصوات الحروف الهجائية التي تعجز بعض الحالات عن نطقها وعلاج اضطرابات النطق التي تعاني منها الحالة وتكوين كلمات من حصيلة الأصوات المتوافرة لدى الحالة آو تلك التي ينجح التدريب في تحقيقها مع مراعاة انتقاء الحروف الكلمات التي يتم التدريب عليها .\n" +
                        " العوامل التي يجب مراعاتها في انتقاء الحروف الكلمات التي يتم التدريب عليه :\n" +
                        "مراعاة مبدأ التدرج في التدريب على إخراج أصوات الحروف من الأسهل إلى الأصعب .\n" +
                        "سهولة الكلمة ووضوح مخارج حروفها .\n" +
                        "البساطة في شكل الكلمة وعدد حروفها ( بابا * ماما * باب * ولد * بنت )\n" +
                        "أن تكون من الكلمات المألوفة شائعة النطق\n" +
                        "التركيز في بداية التدريب على الكلمات التي لها دلالة حسية\n" +
                        "أن تساعد الطفل على تلبية حاجاته ( ماء * حمام * أكل * أنام * ألعب )\n" +
                        " دور الأسرة في برنامج التأهيل التخاطبي\n" +
                        "عند تصحيح نطق الطفل الخاطئ عدم أجبارة على التصحيح بشكل اجباري، إذ أن هذا السلوك يؤدي إلى عناد الطفل وإصراره على الخطأ ، لذلك عندما تسمع الطفل ينطق كلاماً بطريقة خاطئة يجب على أفراد الأسرة أن يعيدوا على مسامع الطفل الكلمة بنطقها الصحيح دون الضغط عليه .\n" +
                        "على أفراد الأسرة أيضاً عدم المبالغة والإسراف في تصحيح أخطاء الطفل النطقية وخاصة في بداية البرنامج العلاجي مع الطفل حتى لا يؤدي ذلك إلى نتائج سيئة .\n" +
                        "أن يوفر كل أفراد الأسرة الفرصة للطفل للتواصل اللفظي مع الآخرين المحيطين به من الأقارب والجيران وزملائه وأخوته وغيرهم ، إذ تسهم تلك الاتصالات في تنمية مهارات النطق لديه إلى جانب أنه تمنح له الفرصة لإقامة علاقة اجتماعية .\n" +
                        " التدريبات اللازمة مع الأطفال ضعاف السمع وذلك لتقوية جهاز النطق بشكل عام:\n" +
                        "أولا : تمارين تفيد النطق وتدريبات للسمع للأطفال ضعاف السمع :\n" +
                        "أ – تمارين لتقوية عضلات اللسان :\n" +
                        "حركة الثعبان حيث يمد اللسان لخارج الفم وإدخاله بسرعة .\n" +
                        "لف اللسان حركة دائرية حول الفم بأقصى ما يستطيع \n" +
                        "أن يمد لسانه خارج الفم بسرعة وإعادته ببطء والعكس .\n" +
                        "رفع وخفض لسانه لأقصى ما يستطيع الوصول اليه من سقف الحلق .\n" +
                        "لعبة لحس طبق به قليل من السكر أو العسل وكذلك الايس كريم.\n" +
                        "ينطق بطريقة منغمة ومكررة الصوت لا لا لا وحرف الراء ر ر ر .\n" +
                        "تحريك اللسان بطريقة دائرية داخل الفم.\n" +
                        "ب- تمارين لتقوية الفك السفلي:\n" +
                        "تحريك الفك يمينا ويسارا.\n" +
                        "تحريك الفك السفلي لأسفل.\n" +
                        "وضع طوق مطاطي فوق رأس الطفل وأسفل ذقنه وفتح فمه وتحريك الفك لأسفل.\n" +
                        "وضع يد الباحثة أسفل ذقن الطفل ومحاولة الطفل دفعها لأسفل بفكه السفلي.\n" +
                        "مضغ اللبان .\n" +
                        "ج- تمارين لتقوية الجهاز التنفسي:\n" +
                        "قضاء أكبر وقت ممكن في ممارسة التمارين الرياضية لتقوية عضلات اليدين والأقدام والرقبة.\n" +
                        "ممارسة تمارين لتقوية الحجاب الحاجز لزيادة سعة الرئتين وبذلك يقوى النفس فيقوى الصوت المنطلق.\n" +
                        "تمارين نفخ البالونات بقوة.\n" +
                        "نفخ أقلام الرصاص الدائرية الموضوعة افقيا على الطاولة, وكور تنس الطاولة,والمراكب الورقية في الماء,وقصاصات الورق.\n" +
                        "النفخ بالماء والصابون باستخدام انبوب للتحكم في التنفس لتكوين كرات الماء.\n" +
                        "اتباع تمرين الغطس بأن يضع المعالج فمه وأنفه في اناء به ماء ويكتم نفسه لفترات متفاوتة ويحاول الطفل تقليده.\n" +
                        "نفخ الشموع المضاءة ومحاولة اطفاءها على مساحات متفاوتة في الطول.\n" +
                        "تمارين الجري والأتزان بالمشي على حبل في الأرض لتمكنه من التحكم في حركة اعضاءه أثناء الحركة والتنفس والكلام.\n" +
                        "النفخ على مراوح ورقية أو بلاستيكيه صغيره لأدارتها.\n" +
                        "تدريبه على اخذ نفس سريع واخراجه ببطء والعكس وبنفس سريع واخراجه بسرعة والعكس وتدريبه على حبس انفاسه فترة من الزمن.\n" +
                        "د – تمارين لتقوية الشفتين :\n" +
                        "ضم الشفتين ومطهما للإمام .\n" +
                        "تحريك الشفتين تجاه الجانب الأيسر والأيمن وأسفل وأعلى وفتح الشفتين وغلقها بطريقة تكرارية.\n" +
                        "إدخال الشفة العليا والسفلي بين الأسنان بالتبادل ولاقصى مايستطيع الطفل .\n" +
                        "مسك الأقلام أو خافض اللسان بالشفتين لبرهة من الوقت أخذ نفس وحبسه في الفم بالضغط على الشفتين.\n" +
                        "نطق حرف ب ب ب ب بطريقة مستمرة ومنغمة بالحركات الطويلة ( با ، بي ، بو )\n" +
                        "استخدام شفاطات العصير .\n" +
                        "\n" +
                        "هـ – تمارين لتقوية الجهاز الصوتي (الحنجرة والحبال الصوتية) :\n" +
                        "تقليد أصوات الحيوانات والطيور ووسائل المواصلات والآلات .\n" +
                        "نطق الأصوات المهموسة والمجهورة بالتبادل ببطء .\n" +
                        "و – تمارين لتقوية سقف الحلق :\n" +
                        "نطق الأصوات الحلقية بطريقة مستمرة وبالتبادل وبالبيئة وبالحركات الطويلة ( خا – خي – خو )\n" +
                        "( غا – غي – غو) (عا – عي – عو ) (حا – حي – حو )\n" +
                        "تكرار كلمة هو هو هو بقوة عدة مرات والتثاؤب والمضغ .\n" +
                        " ثانيا : مرحلة تهيئة الجهاز السمعي :\n" +
                        "أ – التدريب على التمييز السمعي للأصوات :\n" +
                        "وتستخدم هذه الطريقة في تعليم الأطفال ضعاف السمع و مهارة الاستماع وتطويرها لديهم ومن ثم التمييز بين الأصوات أو الكلمات باستخدام الوسائل البصرية والمعينات السمعية التي تساعد على نجاحها .\n" +
                        " أهداف التدريب السمعي:\n" +
                        "1- استثمار بقايا السمع لدى الطفل ضعاف السمع .\n" +
                        "2- تعزيز قدرة الطفل على التمييز الصوتي ..\n" +
                        "3 - استدارة الطفل تجاه الصوت .\n" +
                        "4 – جذب انتباه الآخرين من خلال إصدار بعض الأصوات .\n" +
                        "5– تقليد كلمة بسيطة.\n" +
                        "6 – التعبير عن حاجاته الشخصية .\n" +
                        "7- استخدام كلمات في جمل مفيدة .\n" +
                        " ومن ثم يتم تدريب الطفل على تمييز بعض أصوات الأشياء المختلفة المحيطة في البيئة من حوله مثل :\n" +
                        "الأصوات الموجودة في المنزل مثل صوت– غلق وفتح الباب – جرس الباب – طرق الباب .\n" +
                        "أصوات الحيوانات والطيور مثل : الحمار – البقرة – الحصان– القطة . \n" +
                        "أصوات الإنسان مثل : الضحك – البكاء – الألم – كحة – عطس .\n" +
                        "آلات : صوت سيارة – قطار – مويسيكل – دق مسمار – منشار – طائرة.\n" +
                        "سماع الأصوات الطبيعية مثل : المطر – رياح ويتم التدريب بأن يسمع الطفل الصوت ويرى الصورة التي تعبر عنه , ويعرض عليه صورتين ويطلب منه أ، يشير الى الصورة صاحبه الصوت ، ثم يعاد سماعة ويعرض عليه ثلاث صور ويختار الصورة المعبر عنه .\n" +
                        "ويتم إشراك الأم فى ذلك حيث أن الأم هى المساعد الأول فى تنمية المهارات السمعية للطفل وذلك بمساعدة الباحثة والتى تقوم دائما بإرشادها إلى تدريب طفلها بشكل دائم على سماع أصوات البيئة المحيطة بالطفل.\n" +
                        "\n" +
                        " ب – التدريب على التمييز السمعي للأصوات :ٌ وذلك من خلال ما يلي :\n" +
                        "1 – التميز السمعي :\n" +
                        "عن طريق الاستماع الى الصوت الصحيح والتفرقه بينه وبين الصوت الخطأ وعرض كلمات بها الصوت في مواضع مختلفة, وتميز الكلمات التي بها الصوت.\n" +
                        "2- التميز اللمسي:\n" +
                        "تدريب الطفل على الشعور بالذبذبات التى تصاحب نطق الصوت والشعور بسخونة أو برودة الهواء المندفع مع النطق,أو الشعور بحركة عضو من أعضاء النطق عند خروج الصوت,واستخدام وسيلة حسية لشعور الطفل بمكان خروج الصوت كخافض اللسان أو سائل النعناع أو الخيط.\n" +
                        "3-تدريبات لتنمية مهارة التمييز البصري:\n" +
                        "تستخدم الباحثة المرآة أو صور الفيديو أو على c.dتوضح وضع اعضاء النطق عند خروج الصوت,أو اقران صورة الحرف بصوته ليتعرف الطفل على صورة وصوت الحرف,رؤية الباحثة وهى تنطق صوت الحرف,أو رؤية تطاير الأوراق أو اقلام الرصاص الدائرية أو كور تنس الطولة نتيجة خروج الهواء عند نطق صوت الحرف.\n" +
                        "4- تدريبات اخراج الصوت في مقطع:\n" +
                        "ويبدأ بتدريب الطفل على نطق الصوت منفرد بالتشكيل ومصاحب لحرف العلة ( أ ، و ، ي ) لمقاطع أحادية ثم في مقاطع ثنائية ثم مقاطع ثلاثية تمهيداٌ لنطقه في كلمات .\n" +
                        "5- تدريبات لنطق الصوت في بداية الكلمة .\n" +
                        "6- تدريبات لنطق الصوت في وسط الكلمة .\n" +
                        "7- تدريبات لنطق الصوت نهاية الكلمة .\n" +
                        "8- تدريبات لنطق الصوت مكررا في كلمة .\n" +
                        "9- تدريبات لنطق الصوت في جملة :\n" +
                        "وتبدأ بجمل قصيرة ثم تزداد في الطول تدريجياٌ .\n" +
                        "وبمجرد أن يبدأ الطفل استعمال الكلمة الواحدة ( عن طريق النطق أو بالإشارة) تقوم الباحثة بتدريب الأطفال بواسطة الخطة العلاجية الشاملة لتنمية لغة التخاطب من كل النواحي ، وقد يركز على تنمية المفردات الغوية ( مهارات دلالية ) في كثير من الأنشطة الكلية والموضوعية ، مثل عرض لأدوات المطبخ وأدوات المائدة مع استخدام المفردات المتعلقة بالطبخ عند إعداد طعام أو الاهتمام بأنشطة التلوين والرسم مع استخدام المفردات المعلقة بالأشغال اليدوية والتلوين أو ربط مخارج الحروف والكلمات بحركات إيقاعية أثناء اللعب والتمثيل وعند الخروج الخروج إلى الشارع والسوق والرحلات ، ومع مرور الوقت نجد أن الطفل اكتسب كلمات ومفردات جديدة كما يستهدف البرنامج العلاجي إلى زيادة عدد الكلمات المستخدمة في الجملة الواحدة تدريجيا ،هناك تعبيرات كثيرة يستطيع الطفل أن يتواصل بها مع الآخرين باستخدام جملة من كلمتين ( على سبيل المثال على كلمة (تفاحة) تدخلها الباحثة فى أكثر من جملة أكل تفاحة،اغسل تفاحة بالميه، أشرب عصير تفاح،أقطع التفاحة بالسكينة، وبذلك نساعد الطفل على استخدام الكلمة الواحدة فى أكثر من جملة بداية بالجملة البسيطة ومن ثم تضاف الجمل المكونة من ثلاث كلمات وتزداد طول الجملة بشكل تدريجى.\n"
            )
        )
    )

    internal val Article_32 = Article(
        id = 32,
        title = "التأهيل التخاطبي",
        sections = arrayOf(
            ImageSection("3/2/thumb.jpg"),
            TextSection(
                "التاهيل التخاطبي :",
                "هو برنامج يهدف إلى تدريب الأشخاص الذين يعانون من ضعف سمع يتـراوح من المــتوسط إلى الشديد ولديهم بقــايــا سمعية يمكن الاستفادة منها في تكوين ثروة لـغوية استقـبالية وتعبـيرية ، على الإحسـاس والــوعي بالأصــوات و تحسين الــمهارات السمــعية عـلى مســتوى التــعرف الســمعي للأصـوات البيئية وامدادهم بالــمثـيرات الســمعية لتـنمية مهارات الانتباه السمعي والإدراك السمعي والذاكرة السمعية ."
            ),
            TextSection(
                "أهداف برنامج التأهيل التخاطبي :",
                "• تحسين المهارات السمعية على مستوى الاستجابة التلقائية للأصوات .\n" +
                        "• تحسين المهارات السمعية على مستوى تحديد مصدر واتجاه الصوت .\n" +
                        "• تحسين المهارات السمعية على مستوى التعرف السمعي والتمييز السمعي للأصوات البيئية وغيرها .\n" +
                        "• تحسين المهارات السمعية على مستوى تمييز أصوات الحروف الهجائية ومقاطع الأصوات والكلمات .\n" +
                        "• تحسين مهارات الطفل السمعية على مستوى الفهم عن طريق السمع .\n" +
                        "• تحسين مهارات اللغة الاستقبالية على مستوى المفردات والأفعال الأساسية والأوامر البسيطة .\n"
            ),
            TextSection(
                "مراحل برنامج التأهيل التخاطبي :",
                "المرحلة الأولى ويتم التدريب فيها على .\n" +
                        "1 -الاستــجابة التـلـقائية للأصــوات\n" +
                        "2 -الاستجابة المشروطة للأصوات\n" +
                        "\n" +
                        " \tالمرحلة الثانية التعرف على الأصوات :\n" +
                        "يتم التدريب على هذه المهارة بعرض نماذج متنوعة الشدة الصوتية، مع شرح ما تحدث من صوت يتم بعد ذلك استخدامها في تمرين عملي تقوم فيه الحالة بحركة ما عند سماعة الصوت وتتوقف الحركة بعد اختفاء الصوت مع ملاحظة أن لا يرى الطفل المدرب وهو يحدث الصوت .\n" +
                        " \tالمرحلة الثالثة : تحديد مصدر الأصوات أو مكانها :\n" +
                        "• استمرارا للمهارة السابقة وبعد اكتساب الحالة قدرة التعرف على وجود الصوت من عدمه ، يمكن أن تبدأ الحالة في تحديد مصدر الأصوات من حيث الاتجــاه والمكان .\n" +
                        " \tالمرحلة الرابعة تمييز الأصوات :\n" +
                        "يعد التدريب على تمييز الأصوات والتعرف عليها وتقليدها مهارة ضرورية لنمو مهارات الاستماع المؤثر على تعلم اللغة.\n" +
                        " نماذج الأصـوات متنـوعة وينبغي تعـلم التـميـيز بينهـا مثــل : الأجهـزة المنزلية ، الألعاب، الحيوانات والطيور ، الألآت والمحركات ، أصوات أفراد العائلة ، الأصوات الموسيـقـية ، الحــروف ، الكلمـات ،العبارات القصيرة والجمل لذا ينبغي التدرج في التدريب على التعرف والتمييز بين تلك الأصوات كما يلي :\n" +
                        "\tتمييز الأصوات البيئة المألوفة\n" +
                        "\tمطابقة صوت بصورة\n" +
                        "\tتمييز صوت من مجموعة\n" +
                        "\tتمييز الأصوات المختلفة\n" +
                        "\tتمييز الأصوات المتشابهة\n" +
                        "\tتقليد الصوت\n" +
                        "\tتنفيذ الأمر الصوتي\n"
            ),
            TextSection(
                "ثانياً : تدريبات النطق والكلام :",
                "تختلف المهارات التي يتم التدريب عليها في البرنامج باختلاف البقايا السمعية والقدرات العقلية خاصة معامل الذكاء وقدرات الحالة الإدراكية والتواصل البصري والانتباه .\n" +
                        "و يركز البرنامج في بداية مراحل العلاج على التدريب المنظم الذي يهدف إلى إخراج أصوات الحروف الهجائية التي تعجز بعض الحالات عن نطقها وعلاج اضطرابات النطق التي تعاني منها الحالة وتكوين كلمات من حصيلة الأصوات المتوافرة لدى الحالة آو تلك التي ينجح التدريب في تحقيقها مع مراعاة انتقاء الحروف الكلمات التي يتم التدريب عليها .\n"
            ),
            TextSection(
                "العوامل التي يجب مراعاتها في انتقاء الحروف الكلمات التي يتم التدريب عليه :",
                "\tمراعاة مبدأ التدرج في التدريب على إخراج أصوات الحروف من الأسهل إلى الأصعب .\n" +
                        "\tسهولة الكلمة ووضوح مخارج حروفها .\n" +
                        "\tالبساطة في شكل الكلمة وعدد حروفها ( بابا * ماما * باب * ولد * بنت )\n" +
                        "\tأن تكون من الكلمات المألوفة شائعة النطق\n" +
                        "\tالتركيز في بداية التدريب على الكلمات التي لها دلالة حسية\n" +
                        "\tأن تساعد الطفل على تلبية حاجاته ( ماء * حمام * أكل * أنام * ألعب )\n"
            ),
            TextSection(
                "دور الأسرة في برنامج التأهيل التخاطبي",
                "\tعند تصحيح نطق الطفل الخاطئ عدم أجبارة على التصحيح بشكل اجباري، إذ أن هذا السلوك يؤدي إلى عناد الطفل وإصراره على الخطأ ، لذلك عندما تسمع الطفل ينطق كلاماً بطريقة خاطئة يجب على أفراد الأسرة أن يعيدوا على مسامع الطفل الكلمة بنطقها الصحيح دون الضغط عليه .\n" +
                        "\tعلى أفراد الأسرة أيضاً عدم المبالغة والإسراف في تصحيح أخطاء الطفل النطقية وخاصة في بداية البرنامج العلاجي مع الطفل حتى لا يؤدي ذلك إلى نتائج سيئة .\n" +
                        "\tأن يوفر كل أفراد الأسرة الفرصة للطفل للتواصل اللفظي مع الآخرين المحيطين به من الأقارب والجيران وزملائه وأخوته وغيرهم ، إذ تسهم تلك الاتصالات في تنمية مهارات النطق لديه إلى جانب أنه تمنح له الفرصة لإقامة علاقة اجتماعية .\n"
            ),
            TextSection(
                "التدريبات اللازمة مع الأطفال ضعاف السمع وذلك لتقوية جهاز النطق بشكل عام:",
                "أولا : تمارين تفيد النطق وتدريبات للسمع للأطفال ضعاف السمع :\n" +
                        "أ – تمارين لتقوية عضلات اللسان :\n" +
                        "\tحركة الثعبان حيث يمد اللسان لخارج الفم وإدخاله بسرعة .\n" +
                        "\tلف اللسان حركة دائرية حول الفم بأقصى ما يستطيع \n" +
                        "\tأن يمد لسانه خارج الفم بسرعة وإعادته ببطء والعكس .\n" +
                        "\tرفع وخفض لسانه لأقصى ما يستطيع الوصول اليه من سقف الحلق .\n" +
                        "\tلعبة لحس طبق به قليل من السكر أو العسل وكذلك الايس كريم.\n" +
                        "\tينطق بطريقة منغمة ومكررة الصوت لا لا لا وحرف الراء ر ر ر .\n" +
                        "\tتحريك اللسان بطريقة دائرية داخل الفم.\n" +
                        "ب- تمارين لتقوية الفك السفلي:\n" +
                        "\tتحريك الفك يمينا ويسارا.\n" +
                        "\tتحريك الفك السفلي لأسفل.\n" +
                        "\tوضع طوق مطاطي فوق رأس الطفل وأسفل ذقنه وفتح فمه وتحريك الفك لأسفل.\n" +
                        "\tوضع يد الباحثة أسفل ذقن الطفل ومحاولة الطفل دفعها لأسفل بفكه السفلي.\n" +
                        "\tمضغ اللبان .\n" +
                        "ج- تمارين لتقوية الجهاز التنفسي:\n" +
                        "\tقضاء أكبر وقت ممكن في ممارسة التمارين الرياضية لتقوية عضلات اليدين والأقدام والرقبة.\n" +
                        "\tممارسة تمارين لتقوية الحجاب الحاجز لزيادة سعة الرئتين وبذلك يقوى النفس فيقوى الصوت المنطلق.\n" +
                        "\tتمارين نفخ البالونات بقوة.\n" +
                        "\tنفخ أقلام الرصاص الدائرية الموضوعة افقيا على الطاولة, وكور تنس الطاولة,والمراكب الورقية في الماء,وقصاصات الورق.\n" +
                        "\tالنفخ بالماء والصابون باستخدام انبوب للتحكم في التنفس لتكوين كرات الماء.\n" +
                        "\tاتباع تمرين الغطس بأن يضع المعالج فمه وأنفه في اناء به ماء ويكتم نفسه لفترات متفاوتة ويحاول الطفل تقليده.\n" +
                        "\tنفخ الشموع المضاءة ومحاولة اطفاءها على مساحات متفاوتة في الطول.\n" +
                        "\tتمارين الجري والأتزان بالمشي على حبل في الأرض لتمكنه من التحكم في حركة اعضاءه أثناء الحركة والتنفس والكلام.\n" +
                        "\tالنفخ على مراوح ورقية أو بلاستيكيه صغيره لأدارتها.\n" +
                        "\tتدريبه على اخذ نفس سريع واخراجه ببطء والعكس وبنفس سريع واخراجه بسرعة والعكس وتدريبه على حبس انفاسه فترة من الزمن.\n" +
                        "د – تمارين لتقوية الشفتين :\n" +
                        "\tضم الشفتين ومطهما للإمام .\n" +
                        "\tتحريك الشفتين تجاه الجانب الأيسر والأيمن وأسفل وأعلى وفتح الشفتين وغلقها بطريقة تكرارية.\n" +
                        "\tإدخال الشفة العليا والسفلي بين الأسنان بالتبادل ولاقصى مايستطيع الطفل .\n" +
                        "\tمسك الأقلام أو خافض اللسان بالشفتين لبرهة من الوقت أخذ نفس وحبسه في الفم بالضغط على الشفتين.\n" +
                        "\tنطق حرف ب ب ب ب بطريقة مستمرة ومنغمة بالحركات الطويلة ( با ، بي ، بو )\n" +
                        "\tاستخدام شفاطات العصير .\n" +
                        "\n" +
                        "هـ – تمارين لتقوية الجهاز الصوتي (الحنجرة والحبال الصوتية) :\n" +
                        "\tتقليد أصوات الحيوانات والطيور ووسائل المواصلات والآلات .\n" +
                        "\tنطق الأصوات المهموسة والمجهورة بالتبادل ببطء .\n" +
                        "و – تمارين لتقوية سقف الحلق :\n" +
                        "\tنطق الأصوات الحلقية بطريقة مستمرة وبالتبادل وبالبيئة وبالحركات الطويلة ( خا – خي – خو )\n" +
                        "\t( غا – غي – غو) (عا – عي – عو ) (حا – حي – حو )\n" +
                        "\tتكرار كلمة هو هو هو بقوة عدة مرات والتثاؤب والمضغ\n"
            ),
            TextSection("ثانيا : مرحلة تهيئة الجهاز السمعي :", ""),
            TextSection(
                "أ – التدريب على التمييز السمعي للأصوات :",
                "وتستخدم هذه الطريقة في تعليم الأطفال ضعاف السمع و مهارة الاستماع وتطويرها لديهم ومن ثم التمييز بين الأصوات أو الكلمات باستخدام الوسائل البصرية والمعينات السمعية التي تساعد على نجاحها.\n" +
                        " \tأهداف التدريب السمعي:\n" +
                        "1- استثمار بقايا السمع لدى الطفل ضعاف السمع.\n" +
                        "2- تعزيز قدرة الطفل على التمييز الصوتي..\n" +
                        "3 - استدارة الطفل تجاه الصوت.\n" +
                        "4 – جذب انتباه الآخرين من خلال إصدار بعض الأصوات.\n" +
                        "5– تقليد كلمة بسيطة.\n" +
                        "6 – التعبير عن حاجاته الشخصية.\n" +
                        "7- استخدام كلمات في جمل مفيدة.\n" +
                        " \tومن ثم يتم تدريب الطفل على تمييز بعض أصوات الأشياء المختلفة المحيطة في البيئة من حوله مثل:\n" +
                        "\tالأصوات الموجودة في المنزل مثل صوت– غلق وفتح الباب – جرس الباب – طرق الباب.\n" +
                        "\tأصوات الحيوانات والطيور مثل : الحمار – البقرة – الحصان– القطة. \n" +
                        "\tأصوات الإنسان مثل : الضحك – البكاء – الألم – كحة – عطس.\n" +
                        "\tآلات : صوت سيارة – قطار – مويسيكل – دق مسمار – منشار – طائرة.\n" +
                        "\tسماع الأصوات الطبيعية مثل : المطر – رياح ويتم التدريب بأن يسمع الطفل الصوت ويرى الصورة التي تعبر عنه , ويعرض عليه صورتين ويطلب منه أ، يشير الى الصورة صاحبه الصوت ، ثم يعاد سماعة ويعرض عليه ثلاث صور ويختار الصورة المعبر عنه.\n" +
                        "ويتم إشراك الأم فى ذلك حيث أن الأم هى المساعد الأول فى تنمية المهارات السمعية للطفل وذلك بمساعدة الباحثة والتى تقوم دائما بإرشادها إلى تدريب طفلها بشكل دائم على سماع أصوات البيئة المحيطة بالطفل.\n"
            ),
            TextSection(
                "ب – التدريب على التمييز السمعي للأصوات :ٌ وذلك من خلال ما يلي :",
                "1 – التميز السمعي :\n" +
                        "عن طريق الاستماع الى الصوت الصحيح والتفرقه بينه وبين الصوت الخطأ وعرض كلمات بها الصوت في مواضع مختلفة, وتميز الكلمات التي بها الصوت.\n" +
                        "2- التميز اللمسي:\n" +
                        "تدريب الطفل على الشعور بالذبذبات التى تصاحب نطق الصوت والشعور بسخونة أو برودة الهواء المندفع مع النطق,أو الشعور بحركة عضو من أعضاء النطق عند خروج الصوت,واستخدام وسيلة حسية لشعور الطفل بمكان خروج الصوت كخافض اللسان أو سائل النعناع أو الخيط.\n" +
                        "3-تدريبات لتنمية مهارة التمييز البصري:\n" +
                        "تستخدم الباحثة المرآة أو صور الفيديو أو على c.dتوضح وضع اعضاء النطق عند خروج الصوت,أو اقران صورة الحرف بصوته ليتعرف الطفل على صورة وصوت الحرف,رؤية الباحثة وهى تنطق صوت الحرف,أو رؤية تطاير الأوراق أو اقلام الرصاص الدائرية أو كور تنس الطولة نتيجة خروج الهواء عند نطق صوت الحرف.\n" +
                        "4- تدريبات اخراج الصوت في مقطع:\n" +
                        "ويبدأ بتدريب الطفل على نطق الصوت منفرد بالتشكيل ومصاحب لحرف العلة ( أ ، و ، ي ) لمقاطع أحادية ثم في مقاطع ثنائية ثم مقاطع ثلاثية تمهيداٌ لنطقه في كلمات .\n" +
                        "5- تدريبات لنطق الصوت في بداية الكلمة.\n" +
                        "6- تدريبات لنطق الصوت في وسط الكلمة.\n" +
                        "7- تدريبات لنطق الصوت نهاية الكلمة.\n" +
                        "8- تدريبات لنطق الصوت مكررا في كلمة.\n" +
                        "9- تدريبات لنطق الصوت في جملة:\n" +
                        "وتبدأ بجمل قصيرة ثم تزداد في الطول تدريجياٌ.\n" +
                        "وبمجرد أن يبدأ الطفل استعمال الكلمة الواحدة ( عن طريق النطق أو بالإشارة) تقوم الباحثة بتدريب الأطفال بواسطة الخطة العلاجية الشاملة لتنمية لغة التخاطب من كل النواحي ، وقد يركز على تنمية المفردات الغوية ( مهارات دلالية ) في كثير من الأنشطة الكلية والموضوعية ، مثل عرض لأدوات المطبخ وأدوات المائدة مع استخدام المفردات المتعلقة بالطبخ عند إعداد طعام أو الاهتمام بأنشطة التلوين والرسم مع استخدام المفردات المعلقة بالأشغال اليدوية والتلوين أو ربط مخارج الحروف والكلمات بحركات إيقاعية أثناء اللعب والتمثيل وعند الخروج الخروج إلى الشارع والسوق والرحلات ، ومع مرور الوقت نجد أن الطفل اكتسب كلمات ومفردات جديدة كما يستهدف البرنامج العلاجي إلى زيادة عدد الكلمات المستخدمة في الجملة الواحدة تدريجيا ،هناك تعبيرات كثيرة يستطيع الطفل أن يتواصل بها مع الآخرين باستخدام جملة من كلمتين ( على سبيل المثال على كلمة (تفاحة) تدخلها الباحثة فى أكثر من جملة أكل تفاحة،اغسل تفاحة بالميه، أشرب عصير تفاح،أقطع التفاحة بالسكينة، وبذلك نساعد الطفل على استخدام الكلمة الواحدة فى أكثر من جملة بداية بالجملة البسيطة ومن ثم تضاف الجمل المكونة من ثلاث كلمات وتزداد طول الجملة بشكل تدريجى.\n"
            )
        )
    )

    internal val Article_33 = Article(
        id = 33,
        title = "التدخل المبكر",
        sections = arrayOf(
            TextSection(
                "ماذا يعني التدخل المبكر ؟؟",
                "التدخل المبكر هو تصميم وتنفيذ برامج تربويه خاصه لمرحله الطفوله المبكره وبرامج تدريبيه وارشاديه لاسر الاطفال وخدمات مسانده عديده كالتدريب واستثمار القدرات المتبقيه والمعينات السمعيه.. من ضمن فئات التربيه الخاصه التي يجب ان نقدم لها خدمات التدخل المبكر هي فئه الصم وضعاف السمع ودا لان المراحل الاولي للصم وضعاف السمع مهمه لتكوين النمو اللغوي للطفل والمعرفي والانفعالي والحركي وكذلك اهميه للمستوي الاكاديمي حيث اشار العلماء الي ان انخفاض مستوي الصم وضعاف السمع في المستوي الاكاديمي وخاصه القراءه والكتاب بيأكد انهم محتاجين للتدخل المبكر."
            ),
            ImageSection("3/3/1.png"),
            TextSection(
                "اهميه التدخل المبكر بالنسبه لابني الأصم و ضعيف السمع؟",
                "حقه وتدهور نمائي ودا لان التدخل المبكر بيسهل ويسرع عمليه التعليم في السنوات الاولي ، بالاضافه لان والدي الطفل بحاجه للتدخل المبكر لتعلم انماط التنشئه الصحيحه.\n" +
                        "كمان الاهمال وعدم معالجه الضعف في احدي الجوانب بيؤدي لتدهور جوانب تانيه وعشان كدا التدخل المبكر بيسهل عمليه دمج الطفل الاصم او ضعيف السمع مع الطفل السامع في المستقبل.\n" +
                        "بالاضافه ان التدخل المبكر بيقلل التكلفه الاقتصاديه اللي ممكن نضطر ليها في المستقبل وعشان كدا التدخل المبكر شرط اساسي لتخفيف الاعباء الماديه والمعنويه علي الاسر."
            ),
            ImageSection("3/3/2.png"),
            TextSection(
                "دور الأسره في التدخل المبكر ..",
                "التدخل المبكر والاسرة وجهان لعمله واحدة .\n" +
                        "الاسرة هي الشئ الثابت في حياة الطفل والتدخل المبكر لا يجني ثماره بدون الاسره ووجود علاقه تفاعليه مشتركة مع الوالدين ودا بيلزمنا علي اعداد الوالدين للمشاركه في برامج التدخل ليقوموا بدورهم بفاعليه في تدريب الطفل وهناك اجماع بين الاخصائيين في مجال التدخل المبكر علي ان البرامج والخدمات تكون اكثر فاعليه سواء بالنسبه للطفل او الاسرة عندما تقدم علي نحو يدعم احتياجات الاسره .\n" +
                        "في برامج التدخل المبكر الاسرة بتشارك في تحديد الاهداف ، تصميم الخطه التربوية ، التقييم ، مساعده الاخصائيين وتكمله دورهم في المنزل ، الاطلاع علي مصادر المعلومات ، مساعده الاختصاصين في التقييم وتزويدهم بالتغذيه الراجعه عن الطفل بهدف التطوير والتعديل."
            ),
            ImageSection("3/3/3.png"),
            TextSection(
                "فريق العمل في برامج التدخل المبكر للصم وضعاف السمع",
                "قد يشمل فريق العمل في برامج التدخل المبكر مجموعه من الاختصاصين المؤهلين بما في ذلك معلمي ذوي الهمم ، اخصائي امراض اللغه والكلام ، اخصائي السمع ، اخصائي العلاج المهني ، اخصائي النفسي ، الاخصائي الاجتماعي ، المعالج الاسري ، اخصائئ البصريات، اطباء الاطفال وغيرهم."
            ),
            ImageSection("3/3/4.png"),
            TextSection(
                "انواع برامج التدخل المبكر",
                " برامج التدخل المبكر لیها اشكال كتیره من ابرزها\n" +
                        " ا- البرامج المستنده الي المنزل دراسات وابحاث كتیر اكدت علي فاعلیه البرامج\n" +
                        " القائمه علي التنشئه الاسریه والتفاعل بین الاباء والطفل واثرها الایجابي ودي من\n" +
                        " انواعها الاتي :\n" +
                        " اولا الدعم الاسري : ودا بیأكد علي الخدمات والامكانیات الاسریه المصممه تحدیدا\n" +
                        " لمساعده الاسرة ودعمها علي تلبیه المطالب المرتبطه برعایه الطفل ودا لان اولیاء\n" +
                        " الامور اللي بتتوفرلهم نظم دعم اجتماعي كافیه بیتعرضوا لتوتر اقل واتجاهاتهم نحو\n" +
                        " اطفالهم افضل ودا بیؤدي لتفاعل افضل مع اطفالهم وبالتالي تطور الطفل.\n" +
                        " وأنواع الدعم الرئیسة التي تقدم للأسرة هي: معلومـات عـن نمـو الطفـل\n" +
                        " وفـرص، التعلم والرعایـة الروتینیـة والطارئـة للطفـل والرعایـة الطبیـة، وتـوفیر\n" +
                        " التجهیـزات والمواد وتدریب الوالدین علـى الأسـالیب الصـحیة لتربیـة الطفـل\n" +
                        " والـدعم الاقتصـادي، ومعلومات وتسهیلات تتعلق بوسائل الانتقال وضروریات\n" +
                        " الحیاه وحتى یتم مساعدة الأسرة في تحدید احتیاجاتهـا التـي تتطلـب الـدعم فـإن\n" +
                        " التقیـیم الموجه إلى الأسره یساعد في الكشف عن حاجاتهـا كمـا أنـه یضـمن تنبـأ\n" +
                        " عـن خطـة الخدمات الأسریة الفردیة وهكذا تصبح الأسرة جـزء مـن الحـل وذلـك\n" +
                        " بهـدف تقویتهـا والتقلیل من اعتمادها على الأخصائیین.\n" +
                        " ثانیا برامج الزیاره المنزلیه :\n" +
                        " إن خدمة الأسر في منازلهم هو عمل تقوم به العدیـد مـن المجموعـات المتخصصـة\n" +
                        " خصوصا الممرضین وأخصائي الخدمة الاجتماعیة والمعلمین وقد أصبحت الآن\n" +
                        " العدیـد مـن برامج الزیارت المنزلیة المتوفرة والتي تقدم خدمات للأطفال ذوي\n" +
                        " الإعاقة حیث تركز برامج الزیارات المنزلیة على تقدیم دعم للآباء أو تعلیمهم بعض\n" +
                        " المهارات.\n" +
                        " ویشیر معظم اختصاصي التدخل المبكر إلى أن تعلیم أولیاء الأمور وتـدریبهم یشـكل\n" +
                        " جزءا رئیسا من مسؤولیتهم المهنیة بحیث ینبغي على العاملین في مجـال التـدخل\n" +
                        " المبكـر معرفة المهارات التي یقدمونها لأولیاء الأمور فیما یتعلق بما یجب علیهم\n" +
                        " أن یفعلوه وما یجب ان یجتنبوه.\n" +
                        " ثالثا : منازل الرعایه الصحیه الاسریه النهاریه :\n" +
                        " وتعمل هذه العناصر غالبا مع الأطفال القادمین من أوضاع اقتصـادیة متدنیـة\n" +
                        " ومنـازل الرعایة الأسریة النهاریة كفاءتها اقل من تلك التي تقدم خدمات من قبل\n" +
                        " مجموعات متخصصة وذلك بسبب أن خبرات الأشخاص العاملین فیها اقل، ومع\n" +
                        " ذلك فان منازل الرعایـة النهاریـة الأسریة تعتبر واسعة الانتشار ومصدر لتقدیم\n" +
                        " الخدمات.\n" +
                        " ومن ایجابیات البرامج المستندة إلى المنزل أنها غیر مكلفة اقتصادیاً مقارنـة\n" +
                        " بـالبرامج المستندة إلى المركز وأنها توفر الخدمات للأطفال في بیئاتهم الطبیعیة مما\n" +
                        " یساهم فـي تعمـیم ، المهارات المكتسبة وأنها تشمل على مشاركة الأسرة الفاعلة في\n" +
                        " برنامج طفلها ، أما السـلبیات في هذه البرامج فتتمثل في الوقت الذي یستلزمه\n" +
                        " الانتقال إلى المنـزل ووضـع قیـود علـى ، الفرص المتاحة للطفل للتفاعل الاجتماعي\n" +
                        " إضافة إلى عدم قدرة بعض أولیاء الأمـور علـى تدریب أطفالهم بشكل فعال.\n" +
                        " ب – البرامج المستنده الي المركز :\n" +
                        " وتعتمد البرامج المستندة إلى المركز على تقدیم الخدمـة مـن خـلال إحضـار\n" +
                        " الأسـرة طفلها في برنامج تدخل مبكر فـي أحـد المراكـز حیـث یـتم تقـدیم الخدمـة\n" +
                        " المطلوبـة بواسطة مهنیین یتم التدخل على أساس فـردي أو جماعـة صـغیرة العـدد\n" +
                        " وتمیـل معظـم المناهج إلى استخدام النماذج النمائیة والعلاجیة.\n" +
                        " ومن ایجابیات البرامج المستندة إلى المركز قیام فریق متعدد التخصصـات بتخطـیط\n" +
                        " ، وتنفیذ الخدمات، وإتاحة الفرص للطفل للتفاعل مع الأطفال الآخرین وتوفیر\n" +
                        " الفرص لتوعیـة المجتمع المحلي بالأمور المتعلقة بالتدخل المبكر والحصول على\n" +
                        " الدعم اللازم سواء كان مادیا ، أو فنیاً ام سلبیات هذه البرامج فتتمثل في مشكلات\n" +
                        " توفیر المواصلات والصعوبة المرتبطـة ، بها والكلفة المادیة العالیة احیانا."
            ),
            ImageSection("3/3/5.png"),
            TextSection(
                "كيفية اختيار برنامج التدخل المبكر الفعال ؟",
                "بشكل عام تعتمد فاعلیة خدمات التدخل المبكر ونجاح برامجه على مدى الكفایـة فـي\n" +
                        " استخدام مبادئه الأساسیة وكذلك المرونة في تنفیذ مختلف الإجراءات المتعلقة بتلـك\n" +
                        " البـرامج ویتفق معظم التربویون على انه لا یوجد أسلوب واحد أو طریقة مثلى\n" +
                        " لإعداد وتقـدیم بـرامج التدخل المبكر.\n" +
                        " وبالتالي فان بدائل أو نماذج تقدیم الخدمة في التدخل المبكر یمكن أن توصـف علـى\n" +
                        " نحو أفضل وذلك ضمن سبعة عناصر رئیسة على النحو التالي :\n" +
                        "1 - المستهدف في الخدمات : أي خصائص المجتمع الذین یجب أن تقدم لهم الخدمة\n" +
                        " فمـن هـم الأفراد الذین سوف یتلقون خدمات.\n" +
                        "2 - العمر الذي یبدأ به تقدیم الخدمات : أي ما هو عمر الطفل عند التدخل هل من\n" +
                        " المیلاد أو من عمر سنتین ونصف أم من ثلاث إلى أربع سنوات حیث أن بعض\n" +
                        " برامج التدخل المبكـر لهـا أعمار محددة في تقدیم الخدمات.\n" +
                        "3 - نوع الخدمات الخاصة المقدمة: وأفضل الخدمات هي تلك التي تستند إلى\n" +
                        " احتیاجـات الطفـل وأسرته.\n" +
                        "4 - مكان تقدیم خدمات التدخل المبكر: ما هو المكان المناسب الذي تقدم فیـه\n" +
                        " الخـدمات وهـل الخدمات تقدم في المنزل أو المركز أو كلیهما.\n" +
                        "5 - الشخص الذي یقدم خدمات التدخل المبكر: أي تحدید من الذي سوف یلعب الدور\n" +
                        " الرئیسـي في تقدیم الخدمات هل هو الأب أم الأم أو الاختصاصي.\n" +
                        "6 - البیئة الاجتماعیة للخدمات : إذا كان الأطفال الصغار هم المستهدفون في\n" +
                        " خـدمات التـدخل المبكر فمع من سوف یصنفون والى أي مدى سوف یتفاعلون مع\n" +
                        " غیرهم مـن الأطفـال ذوي الهمم والأطفال السامعین.\n" +
                        "7 - المؤسسات التي تقدم الخدمات : من هي المؤسسة التي تقوم بتقدیم الخدمات\n" +
                        " فعلـى سـبیل المثال المدرسة هي مؤسسة مفوضة لتقدیم الخدمات و مسئولة عنهـا\n" +
                        " إذا كانـت الخـدمات للطلاب وفي مجال میدان التربیة الخاصة في الطفولة المبكرة\n" +
                        " هناك العدید من المؤسسات التي تقوم بتقدیم الخدمات وتنسیقها"
            ),
            ImageSection("3/3/6.png"),
            TextSection(
                "مؤشرات برنامج التدخل الناجح :",
                "إن نجاح أي برنامج تدخل مبكر یعتمد علـى عـدة خصـائص وكفایـات لا بـد\n" +
                        " مـن توفرها لیكون برنامج نموذجي یقدم مـن خلالـه خـدمات تـدخل مبكـر للأطفـال\n" +
                        " الصـم وضعاف السمع نذكر منها :\n" +
                        "1 - تفهم تطور الموالیـد والرضـع والأطفـال الصـغار الصـم وضـعاف السـمع\n" +
                        " والذي یتضمن السمعیات المتخصصة وحاجات التواصل.\n" +
                        "2 - تتعاون مع الاختصاصیین في السمعیات والتعلـیم وعلـم الـنفس والصـحة\n" +
                        " والخـدمات الاجتماعیة بشكل منظم وتزویـد الخـدمات للأطفـال ذوي الفقـدان\n" +
                        " السـمعي واسـتعراض الأبحاث المتعلقة بالطفولة المبكرة والتدخل المبكر.\n" +
                        "3 - تقیم التطور للأطفال الموالیـد والصـغار وأعـداد خطـة الخـدمات الأسـریة\n" +
                        " الفردیـة والتي تشمل على الاحتیاجـات الاجتماعیـة والنفسـیة والصـحیة\n" +
                        " والاحتیاجـات التعلیمیـة للأطفال وأسرهم والتي تعكس تعدد الثقافات.\n" +
                        "4 - تطبق استراتیجیات التدخل المرتكزة على الأسرة والتـي تؤكـد علـى الـدور\n" +
                        " الفعـال للأسرة في تطویر الطفل الأصم أو ضـعیف السـمع واسـتخدام اسـتراتیجیات\n" +
                        " الإستشـارة والتي تشمل التوصیات ووقت الحاجة.\n" +
                        "5 - تطور مناهج وخطـة تعلیمیـة فعالـة تتضـمن التقنیـات الملائمـة والاسـتراتیجیات\n" +
                        " والمصادر والأدوات والمواد والتجهیزات والوسائل للأطفال.\n" +
                        "6 - إدارة البرامج وتطویر المهارات لمقـدمي الخـدمات الإشـرافیة فـي التـدخل\n" +
                        " المبكـر والطفولة المبكرة في تربیة الصم "
            ),
            ImageSection("3/3/7.png"),
        )
    )

    internal val Article_34 = Article(
        id = 34,
        title = "مواضيع توعوية",
        sections = emptyArray()
    )

    internal val Article_41 = Article(
        id = 41,
        title = "المعينات السمعية",
        sections = arrayOf(
            TextSection(
                "",
                "قد شهدت الأعوام القليلة الماضية تقدما ملحوظا في الوسائل التكنولوجية المستخدمة في تأهيل المعاقين سمعيا فعلى سبيل المثال أصبح متاحا حاليا المعينات السمعية على درجة عالية من الدقة وبمواصفات فنية خاصة يمكن ضبطها لكي تلائم الفقدان السمعي لدى كل فرد\n" +
                        "إن تنوع المساعدات السمعية التكنولوجية في الوقت الحاضر للأفراد المعاقين سمعيا تحسن مهارات التواصل وتعزز وعي الفرد المعاق سمعيا وإدراكه بالأصوات البيئية. كما تعمل تكنولوجيا السمع على تزويد الطفل المعاق سمعيا بنوعية أفضل من الأصوات التي تمكنه من الوصول إلى اللغة المنطوقة كما تعطيهم الفرصة في البدء بالتعلم لفهم الكلام والأصوات البيئية في بيئاتهم\n" +
                        "وتتنوع وسائل تكنولوجيا التأهيل السمعي الخاصة بالأطفال المعاقين سمعيا ومنها\n"
            ),
            ImageSection("4/1/1.jpg"),
            TextSection(
                "المعينات السمعية:",
                "تعتبر إحدى المساعدات التكنولوجية التي تساعد ضعاف السمع والصم أيضا على استعادة بعض وظائف السمع من خلال توفير وسائط بديلة للاتصال مع الآخرين أو ممارسة أنشطة الحياة اليومية\n" +
                        "وهذه الأدوات هي عبارة عن السماعات الطبية التي تساعد ثقيلي السمع على استغلال أفضل البقايا السمعية والتي تعمل على تضخيم الأصوات لتسمح للشخص سماعها بشكل أسهل وضمن المدى الطبيعي، بالشكل الذي يساعد ثقيلي السمع على الاستفادة وحضور برامج التعليم العام. إلا أن استخدام السماعات الطبية لا يعني شفاء الفرد من الإعاقة السمعية ولكنها تساعد على استغلال البقايا السمعية لديهم\n"
            ),
            TextSection(
                "متى يجب استشارة طبيب أذن ؟",
                "كل يوم تتعرض للعديد من الأصوات فإذا كنت تشعر بمعاناة عند سماع الأصوات أو لا يمكنك سماعها بوضوح، فقد يكون هذا دليل على ضعف السمع\n" +
                        "• كذلك إذا كنت غير قادر على تمييز نغمات الموسيقى أو الأصوات المنخفضة مثل الهمس\n" +
                        "• رفع مستوى صوت التلفزيون والراديو إلى أعلى مستوى يعد علامة أخري على ضعف السمع\n" +
                        "• عند إجراء المحادثات في الأماكن الصاخبة مثل المطاعم فإنك لا تسمعها أو تجد صعوبة في إجراء المحادثات عبر الهاتف، وبالتالي تضطر إلى تجنب حياتك الاجتماعية واستقبال مكالمات الهاتف، فهذه إشارة قوية على ضعف السمع لا تغض النظر عنها\n"
            ),
            ImageSection("4/1/2.jpg"),
            TextSection(
                "مكونات السماعات الطبية:",
                "\n" +
                        "2. مضخم لتضخيم الأصوات: عبارة عن سلك خاص يزيد من شدة الصوت .\n" +
                        "3. مستقبل:  لنقل الصوت المضخم إلي داخل الأذن ؛ وتحويل الطاقة الكهربائية إلى صوت جديد .\n" +
                        "4. قطعة بلاستيكية: توضع فى الأذن وتنقل الصوت من المعين السمعي (السماعات) إلي القناة السمعية.\n" +
                        "5. بطاريات: لتزويد الأجزاء الكهربائية بالطاقة.\n" +
                        "بالإضافة إلى بعض السماعات الطبية التي لها قوالب الأذن وتعمل على توجيه الصوت إلي الأذن وتقوية نوعية الصوت\n"
            ),
            TextSection(
                "ما هي أنواع السماعات الطبية:",
                "تنقسم أنواع  السماعات الطبية إلى قسمين رئيسيين وكل قسم منهما يندرج أسفله عدة أنواع، هيا نتعرف على أنواع سماعات الأذن  \n" +
                        "• سماعات طبية داخل الأذن\n" +
                        "• سماعات طبية خارج الأذن\n" +
                        " \n" +
                        " أولاً :السماعات الطبية داخل الأذن\n" +
                        "سماعة مخفية داخل قناة السمع (IIC)\n" +
                        "يعتبر هذا النوع من السماعات الأصغر حجمًا بين كل انواع السماعات الطبية فهي مصممة بأحدث وأدق التقنيات التي تجعلها مستقرة داخل قناة الأذن ومخفية عن أعين الناس لذلك يفضلها الكثيرين لأنها تشعرهم بالراحة النفسية والثقة بالنفس\n" +
                        "وهذه السماعة مناسبة كثيرًا للأشخاص الذين لديهم نسبة بسيطة من ضعف السمع أو نسبة متوسطة، وبالطبع المتخصص هو من يحكم في هذا الأمر ويقرر الأنسب لحالتك\n" +
                        "تتميز تلك السماعات بالآتي\n" +
                        "• أقل ظهورًا في الأذن من التصميمات الأكبر حجمًا\n" +
                        "• توفر ميزات لا يتسع لها تصميم المعينات السمعية المركبة بالكامل في عمق قناة الأذن، ولكن قد يكون من الصعب التحكم فيها بسبب صغر حجمها\n" +
                        "• عرضة لانسداد مكبر الصوت بسبب شمع الأذن\n" +
                        "يبلغ سعر السماعات المخفية داخل قناة السمع  حوالي ٣٠٠٠ جنيه مصري، ويمكن أن يختلف سعرها من مكان إلى آخر\n" +
                        " \n" +
                        "سماعة داخل قناة السمع بالكامل (CIC)\n" +
                        "تتميز IIC سماعة صغيرة الحجم أيضًا ولكنها أكبر بقليل من سماعة CIC   بخيارات عديدة تساعد المصاب على عيش حياته بأريحية، وهي مناسبة لضعف السمع الخفيف إلى المتوسط فهي تتيح للشخص المصاب بضعف السمع خاصية التحكم في مستوى الصوت، بالإضافة إلى وجود أزرار لتغيير البرامج حسب حاجة الشخص\n" +
                        "كذلك يمكنك استخدام الهاتف أثناء وضعها في أذنك ولن تسمع صوت صفير مثل باقي سماعات الأذن\n" +
                        "تتميز المعينات السمعية المركبة بالكامل في عمق قناة الأذن بما يلي  \n" +
                        "• أصغر الأنواع وأقلها ظهورًا\n" +
                        "• أقل احتمالاً لأن تلتقط ضجيج الرياح\n" +
                        "• تستخدم بطاريات صغيرة جدًا ما يجعل عمرها أقصر وقد تكون أصعب في التعامل\n" +
                        "لا تحتوي غالبًا على أي ميزات إضافية، مثل التحكم في الصوت أو ميكروفون اتجاهي\n" +
                        "• عرضة لانسداد مكبر الصوت بسبب شمع الأذن\n" +
                        "تتراوح تكلفة السماعات من نوع CIC في مصر ما بين حوالي ٣٠٠٠ جنية مصري إلى حوالي ٣٥٠٠ جنية مصري.\n" +
                        "وتختلف تكلفة السماعات من نوع CIC في مصر عن التكلفة في البلاد خارج مصر\n" +
                        "سماعة داخل قناة السمع (ITC) \n" +
                        "سماعة الأذن الطبية تلك مثلها مثل باقي أنواع السماعات المخفية تتميز بصغر حجمها وخفة وزنها، لذلك تعتبر واحدة من أكثر سماعات اذن طبية حديثة  ومريحة الاستخدام\n" +
                        "يوصي المتخصصين بهذا النوع للأشخاص المصابين بضعف السمع المتوسط إلى الشديد، ولكنها غير ملائمة للمصابين بضعف السمع الشديد جدًا\n" +
                        "من أهم مميزات هذا النوع أنها قابلة للاتصال بالهواتف الذكية وبث المكالمات الهاتفية\n" +
                        "تتميز ذلك النوع من السماعات بما يلي\n" +
                        "• أقل ظهورًا في الأذن من التصميمات الأكبر حجمًا\n" +
                        "• توفر ميزات لا يتسع لها تصميم المعينات السمعية المركبة بالكامل في عمق قناة الأذن، ولكن قد يكون من الصعب التحكم فيها بسبب صغر حجمها\n" +
                        "• عرضة لانسداد مكبر الصوت بسبب شمع الأذن\n" +
                        "سماعات داخل الأذن (ITE)\n" +
                        "تعتبر تلك السماعات من أفضل سماعات أذن طبية المناسبة لضعف السمع الخفيف إلى الشديد، وتقدم بشكلين؛ بشكل غلاف نصفي وغلاف كامل وبالطبع النوع ذو الغلاف النصفي هو الأكثر شعبية نظرًا لخفة وزنه \n" +
                        "ومن أهم مميزاتها إمكانية الاتصال اللاسلكي والاتصال بنظام الأيفون، ومن أهم انواع السماعات الطبية التي تجعل الكلام أسهل في الفهم أثناء الضوضاء وفي المناطق الصخبة\n" +
                        "تتميز المعينات السمعية المركبة داخل الأذن بما يلي\n" +
                        "• توفر ميزات لا يتسع لها تصميم المعينات السمعية الأصغر حجمًا مثل التحكم في الصوت\n" +
                        "• قد تكون أسهل في التعامل معها\n" +
                        "• تستخدم بطارية أكبر لعمر أطول ويتوفر لها العديد من خيارات البطاريات القابلة لإعادة الشحن\n" +
                        "• عرضة لانسداد مكبر الصوت بسبب شمع الأذن\n" +
                        "• قد تلتقط ضجيج الرياح بشكل أكثر من الأجهزة الأصغر حجمًا\n" +
                        "• أكثر وضوحًا في الأذن من الأجهزة الأصغر حجمًا\n" +
                        " \n" +
                        "تتراوح تكلفة هذه السماعات من حوالي ٥٠٠ جنية مصري إلى حوالي ١٠٠٠ جنيه مصري\n" +
                        "ميكروفون داخل حتار الأذن (MIH)\n" +
                        "هذا النوع من السماعات يمكنك أن تجده حصريًا بشركة ريساوند حيث قاموا بتصمميها بأحدث التقنيات التي تسهل على المصاب بضعف السمع أمور حياته كلها\n" +
                        "تتميز السماعة  بتقليل ضوضاء الرياح في أذن المصاب على الرغم من وجود ميكروفون خارجي صغير، وهذا الميكروفون يجعل جودة الصوت أفضل وأكثر وضوحًا\n" +
                        " \n" +
                        "ثانياً: السماعات الطبية خارج الأذن\n" +
                        " \n" +
                        "السماعات الطبية ذات المستقبل داخل الأذن (RIE)\n" +
                        "    تتكون من مستقبل صغير جدًا داخل قناة الأذن وأنبوب خارجي رفيع جدًا وغير مرئي والجزء الخارجي المتواجد خلف الأذن يكون صغير الحجم إلى حدٍ ما\n" +
                        " \n" +
                        "انواع السماعات الطبية خلف الأذن (BTE)\n" +
                        "تُثبت تلك السماعات في أعلى الأذن وتستقر خلفها. يربط أنبوب بين الجهاز وقطعة للأذن يتم تصنيعها حسب الطلب وتُعرف باسم قالب الأذن وتُركب في قناة الأذن. يناسب هذا النوع من المعينات السمعية كل أنواع فقدان السمع تقريبًا وكل الأعمار \n" +
                        "تتميز المعينات السمعية المركبة خلف الأذن بما يلي\n" +
                        "• ذات تصميم تقليدي، وهو الأكبر حجمًا من بين المعينات السمعية على الرغم من وجود تصميمات أحدث صغيرة الحجم وانسيابية الشكل ولا تكاد تُرى بالعين\n" +
                        "• مزودة بميكروفونات اتجاهية\n" +
                        "• يمكنها تضخيم الصوت بطريقة أكبر من أي طرز أخرى\n" +
                        "• قد تلتقط ضجيج الرياح بشكل أكثر من التصاميم الأخرى\n" +
                        "• قد تكون متوفرة ببطارية قابلة لإعادة الشحن\n" +
                        "هذا النوع يدوم لفترة أطول من أي نوع بسبب بقاء مكوناته الإلكترونية خارج الأذن بعيدًا عن شمع الأذن والتعرق\n"
            ),
            ImageSection("4/1/3.jpg"),
            TextSection(" ", ""),
            ImageSection("4/1/4.jpg"),
            TextSection(" ", ""),
            ImageSection("4/1/5.jpg"),
            TextSection(" ", ""),
            ImageSection("4/1/6.jpg"),
            TextSection(" ", ""),
            ImageSection("4/1/7.jpg"),
            TextSection(" ", ""),
            ImageSection("4/1/8.jpg"),
            TextSection(
                "ازاي اختار نوع السماعة المناسبة لي ؟",
                "عند البحث عن إحدى المعينات السمعية، استكشف الخيارات الممكنة لك لفهم نوع الأداة المعينة على السمع الأنسب لك. أيضًا:\n" +
                        "\n" +
                        "• اطلب فحصك. ينبغي زيارة الطبيب لاستبعاد الأسباب التي قد تسبب فقدان السمع القابلة للتصحيح، مثل شمع الأذن أو العدوى. اطلب أيضًا من اختصاصي سمع أن يفحصك.\n" +
                        "• اطلب الإحالة إلى اختصاصي سمع ذي سمعة طيبة. وإذا كنت لا تعرف اختصاصي سمع جيد، فاطلب الإحالة من طبيبك. سيقيّم اختصاصي سمعك ويساعدك في اختيار أنسب المعينات السمعية وتعديل الجهاز لتلبية احتياجاتك. وفي حال فقدان السمع في الأذنين، فسيؤدي استخدام معينتين سمعيتين إلى تحقيق أفضل النتائج.\n" +
                        "• اطلب فترة تجربة. يمكنك عادةً الحصول على المعينة السمعية لتجربتها لفترة. وقد يستغرق الأمر بعض الوقت للتعود على الجهاز وتحديد ما إذا كان مناسبًا لك أم لا. اطلب من الموزع كتابة تكلفة التجربة وما إذا كان هذا المبلغ يُنسب إلى التكلفة النهائية لوسيلة المساعدة السمعية ومقدار المبلغ القابل للاسترداد إذا أعدت وسيلة المساعدة السمعية خلال فترة التجربة.\n" +
                        "• فكر في الاحتياجات المستقبلية. اسأل ما إذا كان من الممكن زيادة قدرة المعينة السمعية التي اخترتها بحيث تظل مفيدة إذا كانت حالة فقدان السمع آخذة في التفاقم. لا تعمل المعينات السمعية إلى الأبد، وإنما يتوقع أن تعيش لمدة خمس سنوات تقريبًا.\n" +
                        "• تحقق من الضمان. تأكد من أن وسيلة المساعدة السمعية معها ضمان يغطي قطع غيارها وعملها لفترة محددة. وقد يشمل بعض الموزعين في الضمان زيارات العيادات أو تقديم خدمات احترافية.\n" +
                        "• احذر من الادعاءات المضللة. لا تستطيع المعينات السمعية استعادة السمع الطبيعي أو القضاء على كل الضوضاء الخلفية. فاحذر من الإعلانات أو الموزعين الذين يدعون غير ذلك.\n" +
                        "• خطط للنفقات. تتفاوت تكاليف المعينات السمعية تفاوتًا كبيرًا، فمنها ما يبدأ من 1500 دولار أمريكي وما يصل إلى آلاف الدولارات لكل قطعة. وقد تكلف الرسوم المهنية وأجهزة التحكم عن بعد وملحقات المعينات السمعية وغيرها من مكملات تلك المعينات مزيدًا من التكاليف. تحدث مع اختصاصي السمع عن احتياجاتك وتوقعاتك.\n" +
                        "تغطي بعض وثائق التأمين الخاصة جزءًا من تكلفة المعينات السمعية أو كل التكلفة، فتحقق من وثيقة التأمين الخاصة بك للتأكد من ذلك. لا يغطي برنامج Medicare تكاليف المعينات السمعية للبالغين. يُطلب من شركات التأمين الخاصة في بعض الولايات دفع تكاليف المعينات السمعية للأطفال. تغطي المعونات الطبية المعينات السمعية في معظم الولايات. قد تتمكن إذا كنت من المحاربين القدامى من الحصول على المعينات السمعية بدون تكلفة من خلال إدارة شؤون المحاربين القدامى الأمريكية\n"
            ),
            ImageSection("4/1/9.jpg"),
            TextSection(
                "جوانب يجب مراعاتها عند تدريب الطفل علي إرتداء السماعه:",
                "يبدأ تدريب الطفل على لبس السماعه في المنزل بدون وجود أصوات مزعجه ويفضل إنتقاء الأوقات التي لا يعاني الطفل فيها من أمراض أو تنتابه مشاعر الضيق والقلق.\n" +
                        "2 – يبدأ لبس السماعه بصوره تدريجيه بدء بخمس دقائق ثم عشره وتزداد تدريجياً حتي يعتاد الطفل إرتدائها طوال اليوم ماعدا وقت الإستحمام والنوم .\n" +
                        "3 – فيفضل إرتباط إرتداء السماعه باللعب بلعبه يفضلها الطفل وتجذب إهتمامه وفي وجود أفراد يميل إلي التواصل أو اللعب معهم .\n" +
                        "4 – مشاركة الأخوه في عملية تدريب الطفل والمحافظه علي سلامة السماعه\n" +
                        "5 – بعد أسبوعين إلي ثلاثه أسابيع من التأقلم التدريجي بالمنزل يمكن للطفل الخروج بها إلي الشارع فى صحبة الآخرين مع توخي الحذر في المحافظه عليها وعدم ضياعها .\n" +
                        "6 – وأخيراً يجب عدم فرض السماعه علي الطفل بالقوه أو إستخدام العنف في إرغامه علي إرتدائها حتي لا يكون إتجاهاً سلبياً حيالها خاصة  وأنها تسبب له ضيقاً في البدايه بإعتبارها جزء غريب عن جسمه\n"
            ),
            TextSection(
                "ازاي أركب السماعات الطبية ؟",
                "بعد اختيار السماعة المناسبة لحالتك وشكل أذنك يأتي دور تركيبها في الأذن أو عليها حسب نوعها، هيا بنا نتعلم كيفية تركيب انواع السماعات الطبية المختلفة:\n" +
                        " \n" +
                        "1- تركيب السماعات الطبية المخفية ( داخل الأذن) :\n" +
                        "● قبل البدء في أي خطوة يجب أن تطهر يدك وتتأكد أنها نظيفة تمامًا.\n" +
                        "● بعد ذلك قم بإمساك السماعة بين أصبعيك الإبهام والسبابة وأدخلها في أذنك برفق.\n" +
                        "● بعد إدخالها تأكد من كونها ثابتة بالضغط الخفيف عليها.\n" +
                        " \n" +
                        "2- تركيب السماعات الطبية خارج الأذن:\n" +
                        "● معظم السماعات التي تكون خارج الأذن تتكون من أكثر من جزء وهم؛ المستقبل والأنبوب والجزء الخارجي.\n" +
                        "● أولًا تقوم بتركيب الجزء الخارجي خلف أذنك ثم تقوم بتثبيت الأنبوب حول أذنك بشكل يجعله ثابتًا.\n" +
                        "● بعد ذلك تقوم بإدخال المستقبل داخل أذنك.\n"
            ),
            TextSection(
                "نصائح عند ارتداء السماعات الطبية:",
                "\n" +
                        "● البحث عن أهم التعليمات والإرشادات التي تساعدك على معرفة كيفية الحفاظ على أي سماعة طبية للأذن وبقائها لفترة أطول.\n" +
                        "● عند الشعور بعدم الراحة أو أي ألم قم باستشارة متخصص السمع.\n" +
                        "● من الأفضل أن ترتدي سماعة الأذن في غرفة هادئة أولًا حتى لا تؤلمك أذنك من الأصوات المفاجئة.\n"
            ),
            TextSection(
                "العوامل المؤثرة فى درجة الاستفادة من السماعات الطبية:",
                "\n" +
                        "• ملائمة السماعة لدرجة الفقدان.\n" +
                        "• مدة استعمال السماعة.\n" +
                        "• عمر الطفل أثناء تشخيص الإعاقة السمعية ؛ كلما كان الاكتشاف مبكراً كلما كانت الاستفادة من السماعة أكثر.\n" +
                        "• اتجاهات الآباء حول استعمال السماعة ؛ حيث أن الآباء إذا كانت لديهم اتجاهات إيجابية نحو السماعات فسوف يساعدون طفلهم علي الاستفادة من السماعات لأقصي حد ممكن ؛ وعلي العكس إذا كانت اتجاهاتهم سلبية\n" +
                        "• سبب الإعاقة السمعية ؛ فربما تكون الإعاقة السمعية أثناء الولادة أو قبل الولادة.\n" +
                        "• مدي ملائمة الخبرات السمعية للطفل .\n" +
                        "• القدرة العقلية للطفل.\n" +
                        "• نوع البيئة المحيطة بالطفل.\n" +
                        "• نوع البطارية المستعملة وجودتها.\n" +
                        "• نوع السماعة.\n" +
                        "• نوع الإعاقة السمعية  ∷( توصيلية -عصبية – مختلطة) .\n"
            ),
            TextSection(
                "ازاي اتعود واتكيف علي ارتداء السماعات الطبية ؟",
                "يستغرق التكيف مع سماعات المساعدة السمعية بعض الوقت. فالأمر يحتاج إلى بعض الإلتزام، والتعلم، والتأنى. ويمكن للنصائح التالية والمعلومات أن تساعدك في عملية التكيف هذه:\n" +
                        "• تعرف أكثر على كيفية عمل السماعة بمساعدة أحد أخصائى السمعيات.\n" +
                        "• تفهم أن التكيف مع ارتداء السماعة يستغرق بعض الوقت.\n" +
                        "• حاول التعود على الإستفادة من السماعة بعيدا عن أى ظروف قد تسبب لك ضغطا نفسيا ، وذلك لعدة ساعات في المرة الواحدة.\n" +
                        "• تعرف على ما هو متوقع حدوثه.\n" +
                        "• إن إستخدام سماعات المساعدة السمعية لا يعالج ضعف السمع، ولا يؤدى إلى إستعادة السمع إلى المستوى الطبيعي أيضا ولا يمكنه القضاء على الضوضاء التى تسمعها فى خلفية الأصوات التى تسمعها.\n" +
                        "• توقع أن الأصوات تبدو عالية في البداية.\n" +
                        "• قد يبدو صوتك أيضا مختلف وعال جدا بالنسبة لك.\n" +
                        "• قد تسمع صوت ضجيج فى خلفية الأصوات التى تريد سماعها حيث أن السماعة لا يمكنها التفرقة تماما بين الأصوات التى تريد سماعها والأصوات التى لا نريد سماعها. إلا أنه بمرور الوقت سوف تتعلم تصفية هذا الضجيج لتسمع بشكل أوضح.\n"
            ),
            TextSection(
                "ازاي أحافظ على السماعة ؟",
                "\n" +
                        "• قم بتنظيف اجزاء السماعة الخارجية بعد خروجها من أذنك باستخدم قطعة من القماش والقيام بمسحها بها فهذا يقي الجهاز من تراكم الأتربة التي قد تؤذى لانسداد مستقبلات الصوت وانقطاع الصوت .\n" +
                        "• إن كان على الاجزاء الداخلية للسماعة بعض الشمع اطلب عند شراء السماعة أدوات العناية بها حتى لا تؤذي طبلة الأذن وتؤدي إلى دخول الشمع في السماعة ولا تقم بتنظيف السماعة بواسطة أعواد تنظيف أو فرشاة.\n" +
                        "• لا تقم بتعريضها إلى درجة حرارة عالية حتى لا تتلف.\n" +
                        "• لا تستخدم منتجات العناية بالشعر أثناء ارتداء السماعة والحرص عليها من المياه فهى تؤدي الى تلفها.\n" +
                        "• قم بتهوئة البطارية بفتح باب البطارية للتهوئة وعدم ترك البطارية داخل السماعه أثناء تخزينها فقد تؤدى الرطوبه ودرجة الحراره الى تكون أملاح على البطاريه.\n" +
                        "• تعود أن تضع السماعة في مكان آمن حتى لا تسقط.\n" +
                        "• قم بإيقاف تشغيل السماعة عـند عـدم الاستعمال.\n" +
                        "• ابعد السماعة بعيدا عن أيدي الأطفال.\n" +
                        "• عدم النوم بالسماعة فقد يؤدى الى كسرها او تلف بعض القطع الداخلية في السماعة وفي بعض الحالات يؤدي الى التهاب في الاذن .\n" +
                        "• وضع السماعه عند النوم فى جهاز التجفيف لامتصاص الرطوبه والتى قد تتسبب فى كثير من المشاكل .\n" +
                        "• حاول ألا تعبث في البطارية وتأكد من أن بطاريتك سليمة لأن البطارية التالفة تسبب التشويش وعدم القدرة على السمع.\n" +
                        "• ارتداء سماعة الاذن بالشكل الصحيح لان التثبيت الخاطئ وارتداء سماعة الاذن الطبية بطريقة خاطئة قد يسبب لك بعض الإزعاج والألم فحاول تجنب ذلك\n"
            ),
            TextSection(
                "كيفية تنظيف غطاء السمع ؟",
                "الغلاف هو الجزء الخارجي من معينتك السمعية. يمكنك تنظيفه بالطرق التالية:\n" +
                        "1. بلل منديلًا أو قطعة قماش قليلاً لإزالة تراكمات الشمع.\n" +
                        "2. استخدم الفرشاة التي تأتي مع معيناتك السمعية للتخلص من التراكمات العنيدة.\n" +
                        "3. بالنسبة للمعينات السمعية التي توضع خلف الأذن ، يمكنك تنظيف قالب الأذن باتباع الخطوات التالية:\n" +
                        "• بإزالته من خطاف الأذن\n" +
                        "• ضع المعينة السمعية في مكان جاف وآمن\n" +
                        "• استخدم الماء الدافئ والصابون لغسل قالب الأذن برفق \n" +
                        "• تخلص من الماء الزائد\n" +
                        "• اترك قالب الأذن يجف طوال الليل\n" +
                        "• يمكنك أيضًا استخدام منفاخ هواء لإزالة الماء من الأنبوب \n" +
                        "• تأكد من جفاف الأنبوب وقطعة الأذن قبل إعادة توصيلهما بالسماعة الطبية.\n"
            ),
            TextSection(
                "كيفية تنظيف ميركوفون السماعة ؟",
                "نظف ميكروفون المعينة السمعية بعناية ، حيث إنه أحد أكثر الأجزاء حساسية\n" +
                        "• اقلب السماعة رأسًا على عقب عند تنظيف الميكروفون. سيضمن ذلك سقوط أي حطام من الميكروفون وليس داخله \n" +
                        "• استخدم الفرشاة المتوفرة مع المعينة السمعية لتنظيف منفذ الميكروفون\n" +
                        "• لا تدخل أي شيء في منفذ الميكروفون ، فقد يؤدي ذلك إلى إتلافه\n"
            ),
            TextSection(
                "كيفية تنظيف جهاز استقبال السمع ؟",
                "جهاز الاستقبال هو الفتحة التي تنقل الصوت من سماعة المعينة السمعية إلى أذنك. السبب الأكثر شيوعًا لفشل المعينة السمعية هو تراكم شمع الأذن في جهاز الاستقبال. \n" +
                        "فيما يلي كيفية تنظيف جهاز استقبال معينتك السمعية\n" +
                        "• كن لطيفًا عند تنظيف جهاز الاستقبال. قد يؤدي استخدام القوة المفرطة إلى إتلافه. \n" +
                        "• نظفه يوميًا بالفرشاة المتوفرة. يجب أن يكون هذا كافيًا لإزالة معظم التراكمات.\n" +
                        "• استخدم حلقة الأسلاك الصغيرة المتوفرة لتنظيف جهاز الاستقبال. أدخل قطعة الشمع في فتحة جهاز الاستقبال حتى تكون هناك مقاومة. ثم استخرجها مرة أخرى. كرر حتى لا يوجد المزيد من الشمع\n"
            ),
            TextSection(
                "كيفية تطهير المعين السمعي ؟",
                "يمكنك استخدام محلول معقم للسمع لتنظيف المعينة السمعية. استخدم فقط المطهر الذي أوصى به أخصائي السمعيات الخاص بك. لا تستخدم مواد التنظيف أو الكحول الأخرى ، فقد يؤدي ذلك إلى الإضرار بالمعينات السمعية.\n" +
                        "رش المحلول على منشفة ورقية ناعمة أو منديل. استخدمه لمسح سماعة الأذن.\n"
            ),
            TextSection(
                "كم مرة يجب تنظيف السماعات ؟",
                "يمكن أن يتراكم شمع الأذن والحطام والغبار على المعينة السمعية. لمنع انسدادها ، يجب تنظيف معيناتك السمعية كل يوم.\n" +
                        "إذا كانت معيناتك السمعية من النوع الذي يحتوي على مصيدة الشمع أو واقي الشمع ، فاستبدلها بانتظام. تحدث إلى أخصائي السمع أو أخصائي السمع حول عدد المرات التي يجب عليك استبدالها وكيف. قد تتمكن من شراء بدائل عبر الإنترنت أو من أخصائي السمعيات الخاص بك.\n"
            ),
            TextSection(
                "أحدث السماعات الطبية:",
                "• سماعة الأذن الطبية Audeo، سماعة أذن طبية عصرية جدا تعمل بطريقة المستقبل داخل قناة الأذن (RIC)، توضع خلف الأذن وتتميز بصغر الحجم، وتصلح هذه الفئة من سماعات الاذن الطبية الرائعة لمختلف أنماط ضعف السمع من البسيط إلى الشديد.\n" +
                        " \n" +
                        "• سماعة الأذن الطبية Bolero، سماعة الأذن الطبية المتطورة ذات التصميم الحديث والتي تتميز بخصائص فنية مختلفة، تمكنك بالاستمتاع بالتواصل مع الجميع من حولك وفي مختلف البيئات الصوتية المتنوعة من خلال عدة اختيارات وأحجام مختلفة تغطي مجال ضف السمع من البسيط الى الشديد.\n" +
                        "• سماعة الأذن الطبية Virto، إذا أردت الاستمتاع بكافة الأصوات المحيطة بك والتواصل الكامل مع جميع من حولك دون الشعور بالحرج من استخدام سماعة الأذن التقليدية فيمكنك الاختيار من عدة أشكال وأحجام من السماعات التي توضع داخل الأذن والتي تغطي مجال ضعف السمع من البسيط الى الشديد، ويتم تصميمها خصيصا على حسب حجم قناة الأذن بعد الاستعانة باستشارة أقرب اخصائي سمع لك.\n" +
                        "• سماعة الأذن الطبية Naida، أحدث جيل من السماعات الرقمية وأكثرها قوة في العالم، والمخصصة لدرجات ضعف السمع الشديد والحاد العميق مع تميزها بحجمها الصغير مقارنة بجميع منافسيها ومن الأجيال السابقة بمقدار 25%..\n" +
                        "• سماعة ديجتال بنظام قنوات ويتم ضبط هذا النوع من خلال البرمجة باستخدام الكمبيوتر ويوجد قناة إلى 32 قناة.\n" +
                        "• ديجتال فري تشانل وهي من أحدث الأنواع ويتم البرمجة باستخدام الكمبيوتر.\n" +
                        "وهناك أيضاً سماعات ولكن يتم التعامل معها بطريقة تلقيدية مثل سماعة ديجتال ترم ويتم ضبط هذا النوع بشكل يدوي عن طريق مفاتيح توجد بالسماعة.\n"
            ),
            TextSection(
                "أفضل أنواع السماعات الطبية:",
                "في واقع الأمر يُعد سوق صناعة سماعات الأذن الطبية من الأسواق المُزدهرة في الوقت الراهن، ويرجع السبب وراء ذلك إلى كثرة الطلب عليها، وهي تدر مليارات الدولارات بشكلٍ سنوي على الشركات المُنتجة لها، ومن أبرز الدُول المُصنعة لها ما يلي:\n" +
                        "أولًا: سماعات الأذن الطبية الألمانية\n" +
                        "يُعرف عن ألمانيا كونها من أكثر الدول تقدمًا على الإطلاق في كافة المجالات، وهذا يشمل المجالات الصناعية، الطبية والتعليمية على وجه الخُصوص، فلا عجب في كونها تُنتج سماعات بجودة لا مثيل لها، ومن أبرز الشركات هُناك شركة Siemens.\n" +
                        " \n" +
                        "هذه الشركة هي واحدة من أهم الشركات المصنعة لأجهزة السمع في العالم، وهي معروفة بجودتها ودقتها، وتبهر العالم باستمرار بأحدث التقنيات وأجهزة المعينات السمعية المتطورة.\n" +
                        " \n" +
                        "في هذه الشركة سمعك هو أولويتهم الأولى، حيث يتم تصميم مجموعة المعينات السمعية الألمانية لتقديم تجربة استماع طبيعية في كل مرة، وفيما يلي نُعرفكم بأفضل ماركات سماعات الأذن الطبية واسعارها:\n" +
                        " \n" +
                        "السماعة\n" +
                        "السعر بالدُولار الأمريكي\n" +
                        "Siemens Signia Insio Primax\n" +
                        "7,800\n" +
                        "Siemens Signia Silk Primax.\n" +
                        "2,480\n" +
                        "Siemens Signia Silk Nx.\n" +
                        "1,400 – 3,200\n" +
                        "Siemens Signia Cros Nx.\n" +
                        "1,500 – 2,500\n" +
                        "Simenes Signia Pure Charge Go Nx.\n" +
                        "1,800 – 2,500\n" +
                        "Siemens Signia Insio Nx.\n" +
                        "1,500 – 2,500\n" +
                        " \n" +
                        "ثانيًا: سماعات الأذن الطبية الدنماركية\n" +
                        "ومن الجدير بالذكر أن أول من اخترع السماعات الطبية كانت دولة الدنمارك لذلك سماعتها تتفوق عن السماعات الأخرى الموجودة بالسوق ويليها السماعات الكندية ثم السماعات السويسرية ويليهم أمريكا وألمانيا وتركيا.  \n" +
                        "ولكن بالنسبة للسعر فيختلف باختلاف الشكل والفئة العمرية المستخدمة لها متوسط أسعار السماعات الدنماركية تصل28.27 دولار\n" +
                        "و تُعتبر الدنمارك واحدةً من أبرز الدُول المُصنعة للمُساعدات السمعية على الإطلاق، وتشتمل على عدد كبير من الشركات التي لها باع في هذه الصناعة، مثل:\n" +
                        " \n" +
                        "• سماعة ReSound\n" +
                        "يقع المقر الرئيسي للشركة المصنعة للسماعة ReSound في الدنمارك، وقد تم تأسيسها في عام 1943م على يد الدكتور رودني بيركنز من جامعة ستانفورد وتشتهر السماعة GN ReSound بجودة الصوت الرائعة.\n" +
                        "بالإضافة إلى التميز في التصميم، والحلول الهادفة التي تساعد ضعاف السمع على إعادة اكتشاف الأصوات، فالسماعة تعتبر مبتكرة في صناعة السمع لتكون على رأس مجال السماعات الطبية، وتتمتع بتقنية متطورة، وكُل ذلك بأسعار مُتفاوتة تتراوح بين 600 وحتى 3,000 دولار أمريكي وفقًا للتقنية المُستعملة فيها، ما يجعلها مُلائمة لكافة الفئات.\n" +
                        "• Oticon سماعة\n" +
                        "Oticon هي شركة مصنعة لأجهزة السمع مقرها في كوبنهاغن، وموجود في الدنمارك بشكل خاص، ولقد تأسست هذه الشركة في عام 1904م، من قبل هانز ديمانت، حيث كان منبع الفكرة هي أن كانت زوجته تعاني من ضعف السمع.\n" +
                        "يتم التحكم في شركة Oticon بواسطة منظمة Oticon، وهي منظمة خيرية لها تفويض لتنمية أعمالها ومساعدة الأشخاص الذين يعانون من ضعف السمع، وتُقدم الشركة سماعاتها بأسعار تبدأ من 790 وحتى 1,790 دولار أمريكي.\n" +
                        " \n" +
                        "• Signia سماعة\n" +
                        "Signia هي شركة تصنيع أجهزة سمعية مملوكة لمجموعة Sivantos Group منذ مارس 2019، ومع الوقت أصبحت Sivantos Group جزءًا من WS Audiology، وهي شركة تأسست في ذلك اليوم من خلال الجمع بين Sivantos ومقرها سنغافورة، مع Widex ومقرها الدنمارك، ويتراوح سعر السماعات التي تُقدمها بين 700 – 2,300 دولار أمريكي.\n"
            ),
            ImageSection("4/1/10.jpg"),
            TextSection(
                "أفضل أماكن لبيع سماعات الأذن الطبية في مصر:",
                "•\tمركز بيور فون سماعات طبية\n" +
                        "مركز بيور فون بيوفرلك عروض مختلفة على أنواع السماعات الطبية إلى ممكن تحتاجها لعلاج ضعف السمع او طنين ووش الأذن دا غير انك تقدر تستبدل سماعتك القديمة بواحدة تانية جديدة من المركز ده غير خدمات الصيانة. إلى بيقدمها بشكل دوري على جميع السماعات إلى ممكن تلاقيها بأشكال مختلفة تقدر تختار منها اللي يناسبك بأسعار متفاوتة. \n" +
                        "•\tمركز Golf hearing aids \n" +
                        "يتميز المركز دا بسهولة وجودة في التعامل مع العملاء، هتضمن انك تختار سماعات جديدة بجودة عالية ودرجة صوت ووضوح قويه، كمان بتوفرلك خدمات صيانه دوريه على السماعه بعد عملية الشراء، يتم في المركز اختيار السماعة بعد قياس مستوى السمع ودرجة الضعف فيها، في المركز هتقدر تشتري السماعات إلى هتناسب كبار السن والأطفال ومختلف الفئات باحجام متنوعة. \n" +
                        "•\tالمشرق للسماعات\n" +
                        "بيوفرلك المركز دا عدة خصومات على السماعات اللى هتشتريها بنسبة تصل إلى 30%، كمان هتقدر تقييس مستوى السمع عندك بشكل مجاني، هتلاقي أشكال مميزة للسماعات الخارجية الداخلية دا غير السماعات السحرية إلى تخفيها جوه الأذن، متوفر في المركز سماعات للرضع والأطفال وكبار السن عشان ترفع نسبة السمع وتقدر تسمع حبايبك بوضوح من غير اي تشويش في درجة نقاء الصوت. \n"
            ),
            TextSection(
                "بعض عناوين لشركات سماعات الأذن الطبية في مصر:",
                "• امبليفون الشرق الأوسط: التواصل من خلال العنوان التالي: 11 ش نادى الصيد، المهندسين\n" +
                        "• المتحدة للسمعيات: التواصل من خلال العنوان التالي: 21 ش ذكى عثمان بجوار إدارة مرور الجيزة، الدقي. الجيزة\n" +
                        "• الاقتصادية العربية للتجارة والتوكيلات: التواصل من خلال العنوان التالي٢٩ ش محمد بهاء الدين الغتورى، سموحة، الإسكندرية\n" +
                        "• مسك للتجارة والاستيراد: التواصل من خلال العنوان التالي: ش محمد على وسعد زغلول، العرب\n" +
                        "• انترتون لسماعات الاذن الطبية: التواصل من خلال العنوان التالي: 42 ش الدقي عمارة مصر للتأمين – الجيزة – الدقي\n" +
                        "• شركة نداء للسماعات الطبية: التواصل من خلال العنوان التالي: 42 شارع الدقى عمارة مصر للتأمين – الدقى –الجيزة\n" +
                        "• فيوتشر تك: التواصل من خلال العنوان التالي: 110ا ش 26 يوليو الزمالك. القاهرة\n" +
                        "• مال للمساعدات الطبية: التواصل من خلال العنوان التالي: 42 ش نزيه خليفه، بجوار بارون سنتر مصر الجديدة. القاهرة\n" +
                        "• هاتكو للاستيراد والتصدير والتوكيلات التجارية: التواصل من خلال العنوان التالي: 38ب ش منصور، باب اللوق عابدين. القاهرة\n" +
                        "• مؤسسه النزهة التجارية: التواصل من خلال العنوان التالي: 152 ش النزهة ميدان سانت فاتيما 11361 مصر الجديدة. القاهرة\n" +
                        "• ويدر ايجيبت: التواصل من خلال العنوان التالي: 17 ش إبراهيم أبو النجا امتداد ش عباس العقاد مدينه نصر، القاهرة\n" +
                        "• الرحمة للأجهزة الطبية: التواصل من خلال العنوان التالي: 45 ش معمل الألبان، أمام مركز شباب الساحل شبرا. القاهرة\n" +
                        "• الأركان للتجارة والمقاولات: التواصل من خلال العنوان التالي عمارات العبور 3 ط. صلاح سالم مدينه نصر. القاهرة\n" +
                        "• ميديكال شوب: التواصل من خلال العنوان التالي: برج العروبة 3 ش حسن صادق، المرغنى مصر الجديدة. القاهرة\n" +
                        "• المكتب المصري للاستيراد: التواصل من خلال العنوان التالي 18  ش الرشيدي، أمام القصر العيني القديم  جاردن سيتى. القاهرة\n" +
                        "• ويدكس ايجيبت: التواصل من خلال العنوان التالي: 25 ش الخليفه المأمون مدينه نصر. القاهره\n" +
                        "• النهار التجارية: التواصل من خلال العنوان التالي: ١٦ ش جواد حسنى، باب اللوق عابدين. القاهرة\n" +
                        "• الهدى للأجهزة التعويضية والأطراف الصناعية: التواصل من خلال العنوان التالي: 4 محمد نوفل، من ش شبرا, محطه سانت تريز شبرا\n" +
