    )

    internal val Article_42 = Article(
        id = 42,
        title = "الوسائل و الاجهزة المساعدة",
        sections = arrayOf(
            TextSection(
                "",
                "أنعم الله سبحانه وتعالى على الإنسان فعلمه الكلام، الذي هو الوسيلة الأولى والأساسية للتعامل بين الناس، وقد أثبتت التجارب العلمية أن قدرة الإنسان على الكلام ما هي إلا نتيجة طبيعية لحاسة السمع. فالشخص الذي يصاب بنقص في قدرته السمعية كثيراً ما يعاني من اضطرابات تخاطبيه ونفسية ناتجة عن عدم القدرة على التعايش أو التعامل مع الآخرين.\n" +
                        "وتتفاقم هذه المشاكل الناتجة عن ضعف السمع كلما ازدادت درجة الفقدان السمعي عند الفرد، ودون أن يعالج طبياً أو جراحياً أو تعويضياً، وقد شهدت الأعوام القليلة الماضية تقدماً ملحوظاً في الوسائل التكنولوجية المستخدمة في تأهيل الأشخاص ذوي الإعاقة السمعية، فعلى سبيل المثال أصبح متاحاً حالياً المعينات السمعية على درجة عالية من الدقة وبمواصفات فنية خاصة يمكن ضبطها لكي تلائم الفقدان السمعي لدى كل فرد.\n" +
                        "وهذا ما يؤكده من تنوع المساعدات السمعية التكنولوجية في الوقت الحاضر للأفراد ذوي الإعاقة السمعية. وتحسن الأدوات المساعدة مهارات التواصل وتعزز وعي الفرد ذي الإعاقة السمعية وإدراكه للأصوات البيئية. كما تعمل تكنولوجيا السمع على تزويد الأطفال ذوي الإعاقة السمعية بنوعية أفضل من الأصوات التي تمكنهم من الوصول إلى اللغة المنطوقة كما تعطيهم الفرصة للبدء في التعلم لفهم الكلام والأصوات البيئية في بيئاتهم\n"
            ),
            TextSection(
                "",
                "عملية السمع البشري من أعقد النظم الميكانيكية والعصبية ويمكن لهذا النظام ان يصيبه العطب نتيجة الحوادث أو المرض أو بسبب وراثي، لذلك كان لابد من استخدام أدوات مساندة تساعد في عملية التواصل السمعي وبالتالي تعلم ضعاف السمع (الأصم). \n" +
                        "يعتبر موضوع طرق وأساليب تعليم الطلبة ذوي الإعاقة السمعية من الموضوعات الرئيسة في ميدان التربية الخاصة، لذلك هناك العديد من الأساليب التقنية المساندة والمساعدة لذوي الإعاقة السمعية التي تسهم في عملية تعلمهم. وقد عملت الجهات المعينة المهتمة بفئة الصم وضعاف السمع على تسهيل عملية دمجهم من خلال توظيف بعض الأدوات المساندة والمساعدة في تعليمهم \n" +
                        "ومنها:\n"
            ),
            TextSection(
                "استخدام جهاز عرض الصور المعتمة (الفانوس السحري):",
                ""
            ),
            ImageSection("4/2/1.jpg"),
            TextSection(
                "",
                "هو من الأجهزة الحديثة المخصصة لعرض الصورة المعتمة عن طريق المرأة العاكسة، وهذا الجهاز متوفر في أغلب مدارسنا المهتمة \n" +
                        "بعملية الدمج، حيث يؤدي إلى خدمات تفيد الطالب من ذوي الإعاقة السمعية، فيقوم هذا الجهاز بتكبير الصورة المعتمة والرسومات والخرائط \n"
            ),
            TextSection(
                "المادة التعليمية التي تعرض مع هذا الجهاز:",
                "المواد المعتمة غير الشفافة أي غير المنفذة للضوء مثل الخرائط Maps أو الرسومات Graphs أو الصور الفوتوغرافية Photographs أو الملصقات أو العملات المعدنية أو أجزاء من النباتات أو قطعة نسيج أو المواد المطبوعة و الوثائق (جرائد، مجلات ، كتب ، نشرات ،مخطوطات ) أو الأشكال الهندسية ، هي التي يمكن عرضها على جهاز عرض المواد المعتمة ويمكن الحصول على المواد المعتمة باستخدام آلة التصوير الفوتوغرافي ، أو قيام التلميذ برسم لوحة ، أو قص بعض الصور من مجلات أو كتب أو يحصل التلميذ على أوراق نباتات من البيئة المحلية."
            ),
            TextSection(
                "استخدامات الجهاز:",
                "يستخدم هذا الجهاز كأداة من أدوات التكبير في عرض المواد والصور المعتمة بأشكالها المختلفة كما يستخدم في عرض الأشياء ثلاثية الأبعاد وكذلك المجسمات والعينات البسيطة من الصخور والقواقع والمعادن والحبوب."
            ),
            TextSection(
                "مميزات الجهاز:",
                "1ـ من أسهل أجهزة العرض من حيث التشغيل حيث يكي لتشغيله في معظم الأجهزة توصيل مقبس الجهاز بالتيار الكهربائي.\n" +
                        "2ـ صغير الحجم وحفيف الوزن حيث ظهرت أجيال جديدة من هذا الجهاز.\n" +
                        "3ـ تمتاز الأجيال الحديثة من هذا الجهاز بأنها على درجة جودة عالية في عرض المادة المعتمة.\n" +
                        "4ـ تعرض هذه الأجهزة كم كبير من المواد والصور المعتمة بينما جميع الأجهزة الأخرى تعرض الصور فقط.\n" +
                        "5ـ يساعد في عرض إنتاج التلاميذ من موضوعات تعبير مميزة ورسومات ومقالات صحفية.\n"
            ),
            TextSection(
                "عيوب الجهاز:",
                "1ـ تحتاج عملية العرض إلى إظلام تام للمكان.\n" +
                        "2ـ لا يعرض غير المواد المعتمة، فلا يمكن عرض الشفافيات والشرائح الشفافة.\n" +
                        "3ـ ارتفاع درجة الحرارة بالجهاز قد يؤثر على المادة المعروضة.\n" +
                        "4ـ عدم توفر الصوت والحركة في العرض.\n"
            ),
            TextSection(
                "الأعطال التي تطرأ على الجهاز أثناء التشغيل:",
                "1ـ تعرض منصة العرض للكسر لأنها عبارة عن لوح زجاجي.\n" +
                        "2ـ حرق المصباح الكهربائي.\n" +
                        "3ـ توقف مروحة التبريد.\n"
            ),
            TextSection(
                "طريقة تشغيل جهاز عرض الصور المعتمة (الفانوس السحري):",
                "يعتمد هذا الجهاز في عمله على الإضاءة المنعكسة عن الجسم المعتم بواسطة المرآة العاكسة، فهو من أجهزة العرض المباشر، وعند تشغيله يجب مراعاة ما يلي:\n" +
                        "1-اضبط كهرباء الجهاز بما يتوافق مع التيار العام في المدرسة، ثم قم بتوصيل الكهرباء للجهاز\n" +
                        "2-أدر مفتاح التشغيل إلى النقطة الأولى المروحة (للتبريد) وتأكد من أن المروحة تعمل بشكل طبيعي.\n" +
                        "3-أنزل حامل الصورة إلى أسفل عن طريق رفع الذراع الخلفي إلى أعلى.\n" +
                        "4-قم بوضع الصورة المطلوب عرضها بحيث تكون معكوسة، ثم قم برفع الصورة إلى أعلى عن طريق إنزال الذراع إلى أسفل.\n" +
                        "5-أدر مفتاح التشغيل الآن إلى النقطة الثانية (الإضاءة).\n" +
                        "6-إذا كانت الصورة غير واضحة حرك العدسة الأمامية حتى توضح الصورة.\n" +
                        "7-حين الانتهاء من عمل الجهاز دع المروحة لتعمل لمدة 3-5 دقائق حتى يبرد الجهاز ومن ثم أقفل المروحة وأغلق العدسة.\n"
            ),
            TextSection(
                "صيانة جهاز عرض الصور المعتمة",
                "1-\tيجب التأكد من فولت التيار الواصل للجهاز.\n" +
                        "2-\tنتأكد من عمل المروحة في أثناء التشغيل.\n" +
                        "3-\tيجب إزالة الغبار والأتربة عن الجهاز وخاصة العدسة حتى لا تتسبب في عتمة العرض وذلك بقطعة من القماش النظيف أو الفرشاة ذات المنفاخ.\n" +
                        "4-\tيجب ألا يستمر العرض لفترات طويلة إلا عند الحاجة فقط حتى لا يتسبب ذلك في انتهاء عمر الجهاز.\n" +
                        "5-\tيجب عدم فك الجهاز والعبث به لأي خلل، ولكن يرسل فوراً إلى المختصين بالصيانة.\n" +
                        "6-\tيحفظ الجهاز بعد الانتهاء من التشغيل في مكان آمن بعيداً عن العبث والغبار والأتربة بعد تغطيته بالكيس الخاص به.\n"
            ),
            TextSection(
                "استخدام جهاز عرض الرأسي (الأوفر هيد)",
                "ويوفر هذا الجهاز في جميع المدارس، وفد يستخدم المعلم هذا الجهاز في غرض بعض الرسومات والصور المصممة على الشفافيات\n" +
                        "هو جهاز يستخدم كوسيله تعليميه ويتوافر هذا الجهاز في غالبية المدارس ويسمى (الأوفر هيد) وهو سهل الاستخدام، سهل الصيانة، إلا أنه يتطلب منا الحذر في أثناء تشغيله، وإطفائه، للمحافظة على المصباح لأنه غالي الثمن ونادر وجوده في السوق \n"
            ),
            TextSection(
                "جهاز عرض الشفافيات (السلايد بروجيكتور)",
                ""
            ),
            ImageSection("4/2/2.jpg"),
            TextSection(
                "",
                "يعتبر هذا الجهاز من الأجهزة العلمية التي شاع استخدامها مؤخرا في مدارسنا وذلك لسهولة تشغيلها من ناحية وسهولة إنتاج البرامج الخاصة بها من ناحية أخرى والتي يمكن للمعلم إنتاجها بنفسه\n" +
                        "يعتبر جهاز عرض الشفافيات (السلايد بروجيكتور) من الأجهزة العلمية التي شاع استعمالها أيضاً في المجال التربوي لسهولة تشغيلها من ناحية وسهولة إنتاج البرامج الخاصة بها من ناحية أخرى والتي يمكن للمعلم إنتاجها بنفسه إذا ما توفرت لديه الإمكانات، بالإضافة إلى سهولة نقله واستخدام الجهاز داخل الفصل مع ما يحققه استخدام مثل هذا الجهاز من شد انتباه التلاميذ للمادة العلمية المقدمة من خلاله.\n" +
                        "وهو مجهز لعرض الصور الشفافة التي يمكن للضوء اختراقها فتظهر الصورة مكبرة على الشاشة أو على الحائط، وهو من أجهزة العرض المباشر\n"
            ),
            TextSection(
                "مميزات هذا الجهاز:",
                "-انه يعمل في الإضاءة العادية. \n" +
                        "2-مواجهة المعلم للطالب والمحاضر للمستمع والمشاهد.\n" +
                        "3-يوضع في مقدمة الفصل.\n" +
                        "4-سهولة نقله من مكان لآخر. \n" +
                        "5-مفيد في عرض الدروس ذات التسلسل المنطقي والذي يحتوي على خطوات \n" +
                        "متتالية \n" +
                        "6-سرعة عرض الشفافيات في وقت قصير، والفترة بين عرض الشفافية والأخرى قصير جدا \n" +
                        "7-عرض الصور بالتزامن مع الصوت مما يزيد من فاعلية العرض وإثارة اهتمام الطلاب \n" +
                        "8-يستخدم كوسيلة للعروض الفردية أو الجماعية. \t\n" +
                        "9-سهولة انتاج المواد التعليمية المستخدمة فيه. \n" +
                        "10-امكانية اختيار الشريحة المناسبة للعرض من بين الشرائح. \n" +
                        "11-امكانية تثبيت الشريحة واعادة عرض الشريحة مرة أخرى. \n" +
                        "12-تكبير الصورة وتصغيرها. \n" +
                        "13-مفيد لحل الأسئلة والتمارين الجماعية، حيث يقوم المعلم بعرض الأسئلة بعد تصويرها من الكتاب وحلها مع التلاميذ.\n" +
                        "14-امكانية التحكم عن بعد.\n"
            ),
            TextSection(
                "عيوب استخدام جهاز عرض الشفافيات:",
                "-لابد من إعتام غرفة التعلم بنسبة 75% - 95%. \n" +
                        "2-تكاليف إنتاج الشفافيات مرتفعة نوعاً ما. \n" +
                        "3-لابد من تواجد شاشة عرض في مكان العرض.\n"
            ),
            TextSection(
                "ارشادات وتوجيهات للاستخدام:",
                "اولا: تجهيز المادة التي تريد عرضها:\n" +
                        "1. اطبع ما تريد عرضة بواسطة الحاسوب، وإذا لم يكن لديك الوقت الكافي، قم بنسخ المادة في ورقة خارجية A4 بواسطة آلة النسخ. \n" +
                        "2. تأكد من وضوح الكتابة والرسومات عليها، وراجع أيضا الأملاء وكل شيء، تجنبا للأحراج اثناء الشرح، حاول ذلك قدر ما تستطيع. \n" +
                        "3. حاول الحصول على ورق شفاف بحجم A4، وقم بإدخاله في آلة النسخ مكان الورق الذي يُطبع عليه. \n" +
                        "4. قم الآن بعمل نسخ مرة أخرى لورقتنا التي تحتوي على المادة التي تريد عرضها، من المفترض ان تظهر الآن بوضوح على الورقة الشفافة. \n" +
                        "5. أصبح لديك الآن مادة جاهزة للعرض على جهاز العرض الرأس\n"
