            TextSection(
                "أجهزة الارسال بالذبذبات المعدلة (نظام جهاز اف إم) FM مكبر الصوت",
                "يعد نظام FM المستخدم في تعليم الأطفال المصابين بحاسة السمع أو المستخدمة في الصفوف الدراسية العادية التي يدرس بها هذه الفئة إلى أذان الطفل المصاب دون توصل أصوات الضجيج المحيطة به وبالتالي تمكنه من سماع شرح المدرس بشكل واضح ومفهوم. وتتنوع هذه الأجهزة من ناحية الشكل والحجم والتقنية التي تعمل بها إلا أنها تتشابه بكونها تعمل على تحسين مستوي الإشارة الصوتية مقابل أصوات الضجيج المحيطة وذلك من خلال تكبير أو تضخيم مستوي الإشارة الصوتية لما فوق أصوات الضجيج المحيطة."
