            ImageSection("4/2/7.jpg"),
            TextSection(
                "",
                "وتهدف هذه الأجهزة إلى تحسين قدرة الأفراد المعوقين سمعياً على السمع بوضوح وبخاصة في المواقف الصفية، لأن المسافة، والصدى، والضوضاء تعيق غالبا قدرة الشخص المعوق سمعيا على فهم الاشارات الصوتية بوضوح بالاعتماد على المعينات السمعية. وتستطيع اجهزة الارسال بالذبذبات المعدلة التغلب على هذه المشكلات في الاوضاع الصفية. \n" +
                        " \u200Fورغم ذلك، فان هذه الاجهزة لا تستخدم كبديل للمعينات السمعية ولكنها أدوات معززة لها. \n" +
                        " \u200Fوعند استخدام هذه الأجهزة، يتكلم المعلم عبر ميكرفون ويستقبل الطالب الصوت بمستقبل على أذنيه أو بالمعينة السمعية. ولا تستخدم الأسلاك الموصلة في هذه الحالات مما يتيح للمعلم والطلاب الحركة بحرية في غرفة الصف. \n" +
                        "\n" +
                        " \u200Fويستخدم أحيانا جهاز معدل بالدائرة السمعية (Audio Loop) وبه ينتقل الصوت من مصدره مباشرة إلى أذن الطالب عبر اسلاك موصلة أو باستخدام الموجات الصوتية المنقولة عبر ترددات (FM) الإذاعية Radio -Frequent (Amplification وتطلق الادبيات المتخصصة على أجهزة الارسال بالذبذبات المعدلة اسماء اخرى مثل اجهزة التدريب السمعية Auditory Trainers أو وحدات التدريب السمعية (Auditory Training Units)\n"
