            TextSection(
                "",
                "Omni directional - \n" +
                        "وهو الميكروفون يلتقط الصوت من جميع الاتجاهات حيث يمكنه التقاط أصوات الطلاب الآخرين إضافة إلى صوت المدرس.\n" +
                        "الميكروفون الموجه: \n" +
                        "يلتقط الصوت من الجهة الأمامية أي من فم المتحدث فقط، وبذلك يقل مستوى الأصوات التي يلتقطها من الجوانب المحيطة. \n" +
                        "الميكروفون المرتبط: \n" +
                        "وهو نوع من الميكروفونات يكون مرتبطاً برابط خاص على الرأس وبذلك يكون قريبا جدا من فم المدرس ويتحرك بتحرك المدرس، ويوفر بذلك صوت عال دون ضجيج وحرية بالتحرك للمدرس. الميكروفون المرتبط بقميص المدرس من جهة وبجهاز المرسل من جهة أخرى ويوضع عادة أسفل الفم \n" +
                        "\n" +
                        "وفيما يتعلق بالجهاز المرسل Transmitter \n" +
                        "هناك خيارات فيما يتعلق بترددات ال صوتFrequencies التي يثبتها الجهاز والخياران هنا: \n" +
                        "- بث تردد ثابت Fixed Frequency: \n" +
                        "حيث يتم اختيار تردد واحد من بين 40 نطاقا من الترددات. \n" +
                        "- ترددات متنوعة Frequency Variable: \n" +
                        "\n" +
                        "وبهذا النوع يتم التحكم بالترددات بشكل يدوي بعض أجهزة الإرسال يمكنها استقبال الصوت من الميكروفون فقط (صوت المدرس)، والبعض منها مصمم لاستقبال الصوت من جهاز التسجيل، والنوع الثالث يمكنه استقبال الأصوات من المصدرين في الوقت ذاته. فعلى سبيل المثال أثناء عرض فيديو أو مشاهدة التلفاز للمدرس التعليق على شيء معين فيلتقط الطفل الصوت الصادر من الجهاز. ومن المدرس.\n" +
                        "\n" +
                        "وهناك أجهزة إرسال مزودة بلوحات تحكم ومؤشرات معينة مثل مؤشر الميكروفون يضئ بلون معين في حالة كون الميكروفون غير متصل بالجهاز ومؤشر لحالة بطارية الجهاز يشير إلى نفاذ الطاقة بلون أحمر إضافة إلى ذلك هناك زر للتحكم بعلو الصوت الصادر من الجهاز وحالة الاتصال. يعتبر جهاز الإرسال من النوع الجيد في حالة ما إذا كان يحتوي على ميزات مثل تعدد القنوات وقدرة الجهاز على بث أصوات من أجهزة سمعية أخرى مثل جهاز التسجيل، وصوت المدرس عندما يكون هناك شرح او تعليق من قبل المدرس، واحتواء الجهاز على مؤشرات حول نفاذ البطارية او توقف البث  وفيما يتعلق بأجهزة الاستقبال فهناك خيارات تتعلق بالترددات التي يستقبلها الجهاز مثل أن يستقبل من جهاز واحد أو قناة واحدة (فردية) Single Channel أو أن يستقبل من قناتين Dual Channel والبعض من الأجهزة لا يستقبل ترددات محددة أو يتم ضبطه لتعزيز الصوت على ترددات معينة تبعا لطبيعة مشكلة السمع التي يعانيها الطفل. وهناك مجموعة من المؤشرات ومفاتيح التحكم تتواجد علي جهاز المستقبل تمكن المستخدم من ضبط الجهاز أو تعديله مثل مؤشر لحالة استقبال إشارة FM فقط أو استقبال أصوات من البيئة أو استقبال كل من الصوتين معا وكذلك مفتاح للتحكم بعلو الصوت، وفيما يتعلق بتوصيل الصوت من المستقبل إلى الأذن هناك خيارات وأنواع متعددة من الموصلات مثل التواصل إلى الأذن بشكل مباشر، أو التواصل إلى أداة توضع خلف الأذن ومن ثم إلى قالب الأذن، أو أن يتم التواصل عبر وظيفة T- Coil في المعين السمعي، وغير ذلك من الخيارات التي تعتمد على الشركة المصنعة للجهاز. \n" +
                        "\n" +
                        "ويعتبر جهاز المستقبل جيدا في حالة كونه يستقبل أكثر من قناة ويحتوى على ميزة التحكم بنوع الإشارة الصوتية المستقبلة ويحتوي كذلك على مؤشر لحالة البطارية المستخدمة والشاحن من حيث طول فترة الشحن والفترة الزمنية التي يعمل بها الجهاز قبل إعادة شحن البطارية وإمكانية الشحم دون الجهاز وغير ذلك من الخيارات ونختم حديثنا بالتأكيد على أهمية جلوس الطفل المصاب بحاسة السمع في المقاعد الأمامية بالقرب من المدرس وبعيداً عن مصدر الضجيج الداخلية والخارجية حتى مع استخدام نظام FM. \n"
            ),
            ImageSection("4/2/8.jpg"),
            TextSection(
