            TextSection(
                "متى يستخدم نظام FM ؟",
                "بشكل عام يستخدم هذا النظام في المدارس بشكل واسع للتغلب على الضجيج والاصوات الدخيلة في فصل المدرسة. ينصح أخصائيو السمعيات باستخدام هذا النظام خارج نطاق المدارس وعلى مجال أوسع حيث ان هذا الجهاز يتوفر بحجم صغير ووزن خفيف ليسهل استخدامه بشكل يومي\n" +
                        "\n" +
                        "يوفر نظام FM فوائد عدة للأطفال حيث أثبتت الدراسات الحديثة والبحوث العلمية ان الحصيلة اللغوية للأطفال تزداد مع سماعهم للمحادثات بوضوح بالإضافة إلى تنمية المصطلحات لديهم. فالأطفال الذين يستخدمون السماعات بدون نظام FMلا يستطيعون سماع المحادثات بشكل واضح إذ كانوا على بعد (3 اقدام) من المتحدث. وحيث أن جهازFM يقلل من هذه المسافة تصبح الفرص أكبر لسماع محادثات أكثر.\n" +
                        "زيادة التحصيل العلمي والأكاديمي\n" +
                        "مساعدة أهالي مستخدمي النظام على التواصل مع أطفالهم في النشاطات خارج المنزل حيث تتضمن هذه النشاطات (السفر بالسيارة – زيارة الحدائق وحديقة الحيوانات -وخلال تبضعهم من الأسواق)\n"
            ),
            TextSection(
