                "عند توصيل الجهاز بالسماعات يجب على الوالدين أن يقرروا متى يتم تفعيل النظام ويصل الصوت عن طريق:\n" +
                        "مكبر السماعة\n" +
                        "مكبر الجهاز \n" +
                        "دمج مكبر السماعة ومكبر جهاز (الاف/ام) معا.\n" +
                        "يكون مكبر جهاز (الاف/ام) على وضع التشغيل عند:\n" +
                        "\n" +
                        "محادثة الاهل والاقارب للطفل في بيئة مرتفعة الضجيج.\n" +
                        "عندما يبتعد المتحدث مسافة 3 اقدام عن الطفل\n"
            ),
            TextSection(
                "الأجهزة الاهتزازية اللمسية Vibrotactile Devices",
                "يتكون الجهاز الاهتزازي اللمسي من ميكرفون ومستقبل محلل صوتی إلكتروني يضعه الشخص الأصم على رسغه. ويهدف هذا الجهاز إلى مساعدة الشخص المعوق على وعي الأصوات البيئية وذلك بتحويل الأصوات إلى اهتزازات ويتعلم الشخص الأصم كيفية تفسيرها بالخبرة والتدريب. ويمكن لهذه الأجهزة أيضاً أن تحسن قدرة الشخص على قراءة الشفاه وقدرته على الكلام.  \n" +
                        "الأجهزة المساعدة على السمع (Assistive Listening Devices (ALDS الأجهزة المساعدة للسمع هي أدوات إلكترونية تمكن الأشخاص المعوقين سمعياً من استخدام قدراتهم السمعية المتبقية بشكل أفضل وتشمل هذه الأجهزة الشماعات الطبية وأجهزة الأرسال الصوتي الخاصة والأجهزة الإلكترونية التي توظف حاستي البصر واللمسية\n"
            ),
            ImageSection("4/2/9.jpg"),
            TextSection(
                "",
                "الأجهزة المنبهة Alerting Devices تعمل هذه الأجهزة على مساعدة الأشخاص الصم على وعي حديث معين أو صوت مهم في البيئة. وتحقق هذه الأجهزة الأهداف المرجوة منها وذلك يبث إشارات ضوئية متقطعة أو أصوات عالية أو اهتزازات للإشارة إلى أصوات جرس الباب أو إنذار الحريق أو أضواء جرس الهاتف وتتوفر عشرات الأجهزة المنبهة في الوقت الراهن إلا أن تكفتها العالية تحرم أعداد كبيرة من الشخاص الصم من الحصول عليها."
            ),
            ImageSection("4/2/10.jpg"),
            TextSection(
                "البرامج المعنوية Captioned Programs",
                "تساعد البرامج التلفازية وأفلام الفيديو المعنوية الأشخاص الصم على متابعة الأحداث عند مشاهدة الأخبار أو الأفلام وتحقق البرامج المعنوية أهدافها من خلال كتابة أهم الكلمات المنطوقة أسفل ال الشاشة كالعبارات التي تكتب عند ترجمة الأفلام والبرامج الأجنبية. \n" +
                        "- والبرامج المعنوية نوعان: \n" +
                        "أحدهما متوفر لجميع المشاهدين\n" +
                        "وثانيهما خاص يحتاج فيه المشاهدة إلى استخدام جهاز لتحليل الشفرة (Decoder) حتى يحصل على المعنوية المطلوبة. \n"
            ),
            TextSection(
                "المعينات السمعية Hearing Aids",
                "تعتبر المعينات السمعية إحدى المساعدات التكنولوجية التي تساعد ضعاف السمع والصم أيضاً على استعادة بعض وظائف السمع من خلال توفير وسائط بديلة للاتصال مع آخرين أو ممارسة أنشطة الحياة اليومية وهذه الأدوات هي عبارة عن السماعات الطبية التي تساعد ضعيفي السمع علي استغلال افضل البقايا السمعية التي تعمل علي تضخيم الاصوات لتسمح للشخص بسماعها بشكل اسهل وضمن المدي الطبيعي بالشكل الذي يساعد ضعيفي السمع علي حضور برامج التعليم العام الا ان استخدام السماعات الطبية لا يعني شفاء الفرد من الاعاقة السمعية ولكنها تساعد علي الاستفادة من البقايا السمعية لديهم."
            )
        )
    )

    internal val Article_51 = Article(
        id = 51,
        title = "كل ما يخص عملية زراعة القوقعة",
        sections = arrayOf(
            ImageSection("5/1/1.jpg"),
            TextSection(
                "كيفية اختيار الأذن المناسبة لزراعة القوقعة ؟",
                "هناك عدة عوامل تؤخذ في الحسبان عند اختيار الأذن الانسب للزراعة فيتم تفضيل الاذن التي تخلو من تشوهات ويتم الكشف عنها باجراء الاشعة المحورية للأذن. كما يتم اختيار الأذن التي من المتوقع أن تعطي أفضل النتائج وتكون أقل خطورة. \n" +
                        "   ومع ذلك ، هناك اعتبارات أخرى ، مثل توازن الجسم وتجنب زراعة الأذن ، والتي يعتمد عليها توازن المريض. وبالمثل ، فإن رغبة المريض في إجراء عملية زراعة ، مثل الأذن المصابة حديثًا ذات السمع الأقوى ، تعطي نتائج أفضل ، لكن العديد من المرضى يرفضون زراعة تلك الأذن لأنها قريبة منه ويستخدمها للسمع ويخافون من فقدانها عند زراعة القوقعة ولا يمكن تجاهل رغبة ذلك المريض إذا طلبها المريض ويتم تقديمها إلى الأفضل النتائج .\n"
            ),
            TextSection(
                "كيفية التحضير لعملية زراعة القوقعة ؟",
                "عامة ما يتم إخضاع المريض إلى مجموعة من الفحوصات التي يمكن تلخيصها، في النقاط التالية:\n" +
                        "1- فحص شامل للأذن.\n" +
                        "2- فحص طبي شامل.\n" +
                        "3- مخطط سمع.\n" +
                        "4-  التحضير للتخدير الكلي\n" +
                        "5- اختبارات نفسية لمعرفة ما إذا كان المريض قادرا على التعامل مع الغرسة الصناعية أم لا .\n" +
                        "   ضرورة القيام بعملية فحص عميقة وعلى مستويات متعددة :\n" +
                        "1- اختبار التنبيه الكهربائي\n" +
                        "2- الفحص الإشعاعي\n" +
                        "3- الفحص السمعي\n" +
                        "4- فحص التوازن : والذي بالكشف عن وجود أي إصابة على مستوى الجهة الخلفية للأذن الداخلية والدهليز المسؤول.\n" +
                        "5- الفحص النفسي \n"
            ),
            TextSection(
                "ماذا يتم قبل عملية زراعة القوقعة ؟",
                "- مرحلة ما قبل زراعة القوقعة :\n" +
                        "يتم اعلام الأهل بـ :                       \n" +
                        "• ضرورة اجراء فحوصات اضافية\n" +
                        "• امكانية وجود دلائل غير مساعدة للعملية\n" +
                        "• اهمية قرار الاهل اذ يتطلب الأمر التزاماً لتطوير اللغة المحكية والتزاماً ببرنامج المتابعة ما بعد زراعة القوقعة .\n" +
                        "    أضف إلى ذلك ضرورة ترك الوقت الكافي للأهل لطرح الأسئلة بطرق متعددة، من خلال افساح المجال أمامهم للقاء :\n" +
                        "• اشخاص صم\n" +
                        "• أهل أولاد خضعوا لعملية زراعة القوقعة أو لم يخضعوا لها.             \n" +
                        "• اعضاء جمعيات وأهل لأولاد صم خضعوا أو لم يخضعوا لعملية زراعة القوقعة.\n" +
                        " يمكن للعائلة ان تعيش فترة صعبة قبل اتخاذ القرار مما يتطلب مساعدة نفسية خاصة في هذه المرحلة .\n" +
                        "توجیه او توجه العائلة نحو الفريق المتخصص بزراعة القوقعة :\n" +
                        "  يتصل الفريق المتخصص بزراعة القوقعة بأعضاء الفريق المتعدد الاختصاصات الذي يتابع الولد. يطلب منه ملف الولد الكامل، يطلع على فحواه لاتخاذ المعلومات الضرورية.  \n" +
                        " ان هدف اللقاءات جمع المعلومات، والفحوصات الأولية هو دراسة امكانية اجراء العملية أم لا.               \n" +
                        "2- مرافقة وارشاد الاهل :\n" +
                        "    في هذه المرحلة يجب مساعدة أهل الأولاد الذين لديهم صمم خلقي أو مكتسب في مرحلة ما قبل أو ما بعد اكتساب اللغة على التفكير :\n" +
                        " • في ضعف السمع ومضاعفاته.\n" +
                        "• في اختيار وسيلة التواصل.\n" +
                        "• في التزامهم المتابعة النفسية، اللغوية والتربوية المناسبة لخيارهم.\n" +
                        "    يمكن اعطاء معلومات واضحة وعامة حول زراعة القوقعة منذ فترة التشخيص شرط ألا تقلل هذه المعلومات من أهمية المتابعة مع التجهيز السمعي والتشديد على النقاط التالية:                                \n" +
                        "1- ان زراعة القوقعة ليست بجراحة \"معجزة\"، أنها لا تعني إعادة السمع إلى طبيعته، انه جهاز له مواصفات دقيقة وله محدوديته.                    \n" +
                        "2- من الضروري أن لا تعرض زراعة القوقعة على الشخص الأصم إلا بعد مرحلة كافية من المراقبة للتأكد من عدم قدرته الاستفادة من الاجهزة السمعية وتطور الولد.\n" +
                        "من المهم خلال هذه الفترة وبمشاركة الأهل القيام بـ :                 \n" +
                        "• متابعة التجهيز السمعي مع اعطاء الوقت الكاف للمس النتائج.     \n" +
                        "• تدريب سمعي حسي ملائم ومنتظم.\n" +
                        "• تطوير قدرة الولد على التواصل لاكتساب لغة.\n" +
                        "• التأكد من ان الولد لا يعاني من اعاقات اضافية، وفي حال وجودها، التأكد من قدرته على الاستفادة منها. \n" +
                        "3- مرحلة مراقبة وتحضير الولد بهدف اجراء عملية الزراعة:\n" +
                        "    لا يتخذ قرار زراعة القوقعة عادة إلا بعد فترة مراقبة لا تقل عن الستة أشهر إلا في الحالات الاستثنائية الطارئة (طبية).\n" +
                        "    هذه المهلة ضرورية للولد في عمر مبكر لتقييم تطوره في فترة المتابعة وقدرته على الاستفادة من التجهيز السمعي التقليدي.\n" +
                        "   من الضروري مراقبة استفادته من التجهيز السمعي مع السماعة واعادة اجراء الفحوصات عند الضرورة.\n" +
                        "    تسمح هذه الفترة الزمنية للأهل بالتفكير لاتخاذ قرارهم بوعي ونضوج.\n" +
                        "4- تقييم الولد من قبل الفريق المتعدد الاختصاصات :\n" +
                        "ما قبل عملية زراعة القوقعة :\n" +
                        "    دراسة امكانية اجراء العملية تتطلب مشاركة جميع أعضاء الفريق المتعدد الاختصاصات ومن الضروري التوصل الى اتفاق بين الاعضاء على امكانية اجراء العملية.\n" +
                        "دراسة الفعالية تتطلب:\n" +
                        "• فحص اذن، انف وحنجرة\n" +
                        "• فحص عام للسمع تقرير عن اللغة   \n" +
                        "• تقرير عن الاستفادة من السماعة\n" +
                        "• تقرير سيكولوجي\n" +
                        "• بحث في اسباب الصمم\n" +
                        "• بحث في امكانية وجود اعاقات أخرى .\n"
            ),
            TextSection(
                "انواع زراعة القوقعة ؟",
                "- زراعة القوقعة الخاصة بالكبار: هذه مخصصة للأشخاص الذين ولدوا صماء أو يعانون من ضعف السمع بعد الولادة, بالنسبة لهؤلاء الأشخاص ، يمكن استخدام زراعة القوقعة كوسيلة مساعدة لقراءة الشفاه ، حيث أظهرت بعض الدراسات أن البالغين الذين يعانون من الصمم منذ الولادة يعانون من ضعف شديد في الفهم والاستجابة للكلام بواسطة الزراعة .\n" +
                        "- زراعة القوقعة الخاصة بالأطفال الصغار : هم أطفال يعانون من ضعف شديد في السمع ولا يستفيدون من المعينات السمعية الطبية التقليدية لأن عملية الزرع تبدأ من السنة الثانية من العمر ، أي منذ بداية تطور اللغة , فكلما كان السن مبكرا كانت نتائج هذه الدراسات حول فقدان السمع الشديد لدى الأطفال المصابين أفضل ، بالإضافة إلى حقيقة أن قدرة زراعة القوقعة على التواصل والسمع والكلام قد تحسنت بشكل ملحوظ أثناء متابعتها على المدى الطويل .\n"
            ),
            TextSection(
                "ما هى خطوات زراعة القوقعة ؟",
                "تمر زراعة القوقعة بثلاث خطوات هي : ما قبل العملية الجراحية، وفترة الجراحة والنقاهة، وفترة ما بعد الجراحة أو ما تعرف بفترة إعادة التأهيل. وسنتناول كل منها بالتفصيل فيما يلي:\n" +
                        "أولا: فترة ما قبل الجراحة \n" +
                        "1- إجراء اختبارات سمعية وطبية متتابعة قبل إجراء الجراحة لتقييم مدى استفادتهم من عملية الزراعة.\n" +
                        " 2- إجراء تقييم نفسي للمعاقين سمعيا وآباءهم للتأكد من معرفتهم بخطوات العملية وما قد يترتب عليها من آثار .\n" +
                        "3- تحديد نقاط القوة والضعف التي يمكن أن تساعد أو تعيق التكيف قبل عملية الزراعة.\n" +
                        "4- تطوير خطة سلوكية لإعادة التأهيل السمعي\n" +
                        " 5- تحديد المشكلات السلوكية التي يعاني منها المعاقين سمعيا الذين سيخضعون للعملية كالشعور بالإحباط.\n" +
                        "6- إجراء مقابلات مع المرضى يتم من خلالها عرض كافة المعلومات الضرورية عن عملية الزراعة وكيفية حدوثها وما يسبقها ويعقبها، وما هي مزاياها وسلبياتها المحتملة.\n" +
                        "ثانيا: فترة الجراحة والنقاهة\n" +
                        "عادة ما تتطلب فترة النقاهة الصبر والتكيف من المرضى نتيجة لما يشعرونه من الإحباط والخوف والتوقع، لذا هم يدركون أن الأسابيع الأولى هي الفترة الأصعب.\n" +
                        "وهذا يتطلب أن يقدم الفريق المسؤول عنهم برنامجًا مكثفًا يتضمن التثقيف والعلاج النفسي لمشاعر الخوف والقلق الناجم عن نتائج العملية والمخاوف بشأن مظهرهم حول وضع الشعر والرأس بعد الجراحة.\n" +
                        "ثالثا: فترة إعادة التأهيل:\n" +
                        "وتتم فترة إعادة التأهيل بعد 3-5 أسابيع من اجراء العملية ، يتم خلالها تفصيل الأجهزة لمساعدة المريض على استقبال الإشارات غير الطبيعية التي يرسلها الجهاز إليه لتدريبهم على المهارة الأولى من خلال جمع النماذج الصوتية الكهربائية مع النماذج التي كانوا يسمعونها والتي تكون ذات معنى. لذلك من الأفضل لهم استخدام الجهاز بسرعة لأنه سيساعدهم على التعلم بسرعة وتحسين مهارات التحدث والتواصل لديهم خلال تلك الفترة.\n"
            ),
            TextSection(
                "كيف تتم عملية زراعة القوقعة ؟",
                "تستغرق هذه العملية حوالي ساعتين ويتم إجراؤها تحت تأثير التخدير العام وباستخدام المنظار والاجهزة الكاشفة لعصب الوجه , يتم وضع جهاز الكشف أولاً على العصب الوجهي ثم يتم إزالة الشعر من منطقة صغيرة من فروة الرأس خلف الأذن مباشرة , ثم يتم عمل شق في الجلد ، وبعد ذلك يتم الوصول إلى الأذن الوسطى والقوقعة (الأذن الداخلية) ، حيث توضع أقطاب القوقعة ويتم تثبيت الجزء المستقبل خلف الأذن ، وبعد ذلك يتم إغلاق الجرح. بعد ذلك يتم اختبار الجهاز أثناء العملية ويتم أخذ صور بالأشعة السينية لتأكيد نتائج العملية , ويبقى المريض في المستشفى حوالي يومين ويتم تطعيمه للوقاية من الالتهابات.\n" +
                        "   تنطوي هذه الجراحة على بعض مخاطر التخدير أو التهابات الجروح ، كما هو الحال مع العمليات الجراحية الأخرى ، ولكن هناك أمور مهمة يجب الانتباه لها في هذه العمليات ، وهي احتمال حدوث ضعف في العصب الوجهي ، وهو أمر نادر الحدوث بسبب الجراحة, من أطباء الأذن ذوي الخبرة ومتمرسين في هذه العمليات, ووجود جهاز يكتشف هذا العصب , وأحد مضاعفات هذه العملية مفقود أو اختراق جزئي للزراعة في القوقعة ، كما أنه من النادر أن يكون هناك تصوير مقطعي دقيق  يوضح القوقعة جيدًا قبل الجراحة أو الحاجة لإجراء أشعة التصوير بالرنين المغناطيسي لتأكيد ذلك.\n" +
                        "   هناك أيضًا خطر فشل الجهاز وهذا يحدث في 2٪ من الحالات التي يتعين فيها إزالة الجهاز وزرع جهاز آخر. أريد أن أخبر المريض أن أحد مضاعفات عملية الزراعة القضاء على بقية السمع ، وهذا أحد الأسباب التي تجعل المرضى يختارون أضعف الاذنين سمعا لتجنب فقدان السمع في الاذن الافضل ، على الرغم من أنها تعطي نتائج أقل وهذا من أسباب خوف الكثير من الأطباء والمرضى من عمليات الزرع. في كلتا الأذنين. سنجد هنا مؤشرًا على أن تطوير هذه العملية سمح بإجراء عمليات تقلل من مخاطر فقد السمع ، وبهذا تم استخدام زراعة القوقعة بترددات معينة وفقًا لحاجتها ويزداد خطر الإصابة بالتهاب السحايا 30 مرة, لذلك يتلقى المريض التطعيمات التي تحميه من هذه العدوى بإذن الله.\n" +
                        "  بعد حوالي ثلاثة أسابيع ، يكون الجرح مهيئًا جيدًا ، مما يسمح بوضع وتنشيط الجهاز الخارجي ، عادة لا تكون النتائج فورية ، لأن الدماغ يحتاج إلى مزيد من الوقت للتكيف مع سماع هذه الأصوات الجديدة ، لمن سمع من قبل ، ولكن من لا يمتلكها  يمكن أن تستغرق إعادة التأهيل سنوات ، والتي تختلف بشكل كبير حسب تعاون أسرة المريض.\n"
            ),
            TextSection(
                "اتخاذ تقييم قرار زراعة القوقعة ؟",
                "يتم التقييم فى ثلاث مجالات: \n" +
                        "● نفسى.\t\t● طبى.\t\t● لغوى.\n"
            ),
            TextSection(
                "أولاً : التقييم والتحضير النفسي لزارعى القوقعة :",
                "أ- اللقاءات الأولى (الأهداف) :\n" +
                        "• لقاء (أو أكثر، حسب الحاجة) مع الأهل بغية التعرف عليهم، وجمع المعلومات الضرورية عن العائلة بشكل عام والولد او المراهق بشكل خاص المعلومات تتعلق بالماضي الطبي و النفسي (تعبئة استمارة خاصة بهذه المواضيع).  \n" +
                        "• لقاء (أو أكثر، حسب الحاجة) مع الولد أو المراهق بغية التعرف عليه وكسب ثقته، بالاضافة الى تحضيره نفسيا لجلسات المتابعة ما قبل وما بعد زراعة القوقعة.  \n" +
                        "• اللقاءات المتعددة مع الأهل والولد أو المراهق هي ايضاً لقاءات توجيهية حيث يتم الشرح الكامل عن مراحل زراعة القوقعة التقييم، جلسات التحضير العملية، الشق التقني الحسنات الصعوبات الاكتساب اللغوي المستقبل التربوي.\n" +
                        "• تهدف هذه اللقاءات من جهة أخرى الى توعية الأهل على أبعاد ومحدودية عملية زراعة القوقعة وعلى أهمية المحافظة على الجهاز وضبطه وصيانة قطعه بشكل مستمر، ومتابعة جلسات النطق مع معالج النطق.\n" +
                        "• دور المعالج النفسي مرافقة الأهل كلما لزم الأمر وذلك لمساعدتهم بداية على قبول واقع ولدهم كشخص أصم، وفي مرحلة ثانية اعتبار جهاز زراعة القوقعة كوسيلة متطورة تساعد الولد على اكتساب لغوي أكبر وليس كجهاز يعيد السمع كليا.\n" +
                        "ب- التشخيص والتقييم النفسي والمعرفي :\n" +
                        "• يقوم المعالج النفسي بالتقييم الفكري وهو كناية عن مجموعة من الاختبارات بهدف معرفة المستوى الفكري ،المكتسبات الصعوبات التعلمية (إذا وجدت)، التركيز الذاكرة الخ... عند الولد أو المراهق.              \n" +
                        " • التشخيص النفسي و هو كناية عن مجموعة من الاختبارات الإسقاطية الشخصية والاجتماعية التي تعكس نفسية وشخصية الولد أو المراهق. هنالك نوعان من التشخيص النفسي :\n" +
                        "- الاختبارات التي تعطي صورة واضحة عن الاضطرابات النفسية أو السلوكية من نوع العصاب بشتى الفئات عند الولد أو المراهق.  \n" +
                        "- الاختبارات النفسية التي يمكن ان تدل على أمراض عقلية من نوع الفصام (بشتي الفئات) عند الشخص الراشد أو من نوع التوحد عند الولد. \n" +
                        "ج- تقييم الاختصاصي اللغوي :\n" +
                        "      من خلال اللقاء مع الأهل والولد يستطيع الإختصاصي اللغوي الاطلاع على تاريخ تطور الإصابة بالصمم وتحديد المستوى المدرسي الذي توصل إليه الولد فيما يحاول أن يتبين طريقة التواصل السائدة في العائلة وفي المحيط المباشر للطفل الأصم.\n" +
                        "       كما يهتم أيضا بتقييم توقعات العائلته بالنسبة لعملية الزرع وتقدير مدى التزامها بالمتوجبات التي تفرضها العملية ودوافعها لإجرائها. كما يتيح له اللقاء شرح الفوائد المرتقبة للعملية والتطرق إلى بعض من المشاكل التي يمكن أن تتولد منها وإلى محدوديتها وتقصيرها في الإجابة عن بعض ما يمكن أن يأمله الأهل منها.  \n" +
                        "يحدد عمر الولد الأصم طريقة التقييم المتبعة :\n" +
                        "1- دون ثلاث سنوات :\n" +
                        "      يمكن للاختصاصي اللغوي التعرف إلى وسيلة تواصل الولد المفضلة مع المحيط وقياس مدى إستفادة الولد سمعيًّا، ومدى قدرته على التركيز البصري، ومدى قدرته على التركيز المزدوج، وقدرته على الإندماج في اللعب مع الأولاد الآخرين ومع الراشدين وتقدير درجة إستقلاليته.\n" +
                        "      وعليه بالأخص أن يتنبه لوجود أي من الإمارات التالية، كونها تشكل علامات مواقع ضد إجراء عملية الزرع :\n" +
                        "• الحركات النمطية المتكررةSTEREOTYPIES) )\n" +
                        "• ترديد الأصوات أو الكلمات أو أجزاء منها كرجع صدى.         \n" +
                        "•  البطء في استيعاب المعلومات وفي تطبيق الأنشطة المطلوبة.           \n" +
                        "2- عمر الولد ثلاث سنوات وما فوق :\n" +
                        "يستطيع الاختصاصي اللغوي استخدام الروائز وهى نوع من الاختبارات للقيام بتقييم دقيق يشمل:    \n" +
                        " • تقييم كامل للقدرات السمعية من ناحية تمييز الأصوات والأحرف والكلمات والجمل.                       \n" +
                        "• تقييم لغوي كامل على صعيد الفهم كما على صعيد التعبير، باستعمال الإشارات والتحرك الجسدي.      \n" +
                        "•  تقييم لغوي كامل على صعيد الفهم كما على صعيد التعبير، باستعمال اللغة المحكية.   \n" +
                        "• تقييم قدرات الولد على استعمال اللغة المكتوبة بحسب عمره وبحسب تطور مستواه المدرسي.\n" +
                        "•  تقييم قدرة الولد على المشاركة والانخراط في النشاطات الجماعية.\n"
            ),
            TextSection(
                "ثانياُ :التقييم الطبي:",
                "وهو كناية عن سلسلة لقاءات مع العائلة والولد أو المراهق، فحوصات، اختبارات طبية وتصوير بالرنين المغناطيسي وغيرها..."
            ),
            TextSection(
                "ثالثاً : تقييم الاختصاصي اللغوى ما بعد زراعة القوقعة :",
                "إن المتابعة اللغوية ما بعد العملية ضرورية جدًا. من خلالها يستطيه الاختصاصي اللغوي :\n" +
                        "• تقييم استفادة الولد من عملية الزرع وتقييم تقدمه سمعيا ولغويا وذلك من خلال روائز محددة حسب عمر الولد.\n" +
                        "• كما يمكنه مساعدة الفريق الطبي على برمجة جهاز السمع الجديد بصورة سليمة ومناسبة.\n" +
                        " • رصد مدى استفادة الولد من جهازه، ومدى تفاعله مع المعلومات السمعية الجديدة، ومدى قدرته على فهم الأصوات الجديدة.\n" +
                        "• تقيم قدراته الكلامية واللغوية في أوجهها المختلفة.\n" +
                        "• إستنباط برنامج للمتابعة واتخاذ القرارات المناسبة بشأن التوجيه المدرسي المناسب لوضع الولد.\n"
            ),
        )
    )
    internal val Article_52 = Article(
        id = 52,
        title = "مفهوم وشروط وفوائد زراعة القوقعة",
        sections = arrayOf(
            ImageSection("5/2/1.jpg"),
            TextSection(
                "ما هى زراعة القوقعة ؟",
                "زراعة قوقعة بالأذن الداخلية هي إجراء جراحي يتم خلاله زرع جهاز إلكتروني يوفر حاسة السمع للأشخاص الذين يعانون بصعوبة شديدة في السمع ، وعلى عكس أجهزة السمع ، لا تقوم زراعة القوقعة بتضخيم الصوت ، ولكنها تعمل من خلال تحفيز الأعصاب السمعية داخل القوقعة المصابة بموجات كهربائية.\n" +
                        "    و يعتبر هذا الجهاز من التطورات العلمية الحديثة ويتكون من جزئين( داخلي وخارجي )، وتشمل العناصر الخارجية للقوقعة مكبر صوت و المعالج الذي يتحكم في مستوى الصوت والمرسل.و يوجد تحت الجلد مستقبل تردد لاسلكي يحتوي على مغناطيس يجذب الجزء الخارجي إلى الجلد ، وعندما تصل الإشارة إلى جهاز الاستقبال ، يتم نقلها إلى أقطاب القوقعة.\n"
            ),
            TextSection(
                "الأجزاء الأساسية (مكونات) القوقعة :-",
                "الاجزاء الخارجية :\n" +
                        "١- مكبر الصوت (المايكروفون) : الذي يلتقط الصوت من البيئة . \n" +
                        "٢- المعالج : الذي قزم بتصفية الاصوات المسموعة ومن ثم يرسل إشارات كهربائية الى جهاز الإرسال.\n" +
                        "3- جهاز الإرسال : وهو عبارة عن حلقة خلف الأذن وتتثبت بمغناطيس مع جهاز الاستقبال تحت الجلد والذي بدوره ينقل الصوت الى الجزء المزروع بموجات كهرومغناطيسية .\n" +
                        "الاجزاء الداخلية :\n" +
                        "1- جهاز استقبال : يستقبل الموجات من خلال الجلد ويرسلها إلى المنشط .  \n" +
                        " 2- المنشط (المحفز) : يقوم بتحويل الإشارة إلى نبضات كهربائية وتوزيعها على الألياف.  \n" +
                        " 3- الألياف : هي أقطاب كهربائية متعددة القنوات يتم زرعها في القوقعة المصابة وتنقل الموجات الكهربائية إلى مناطق متفرقة من القوقعة التي تحفز العصب السمعي والتي بدوره ينقل هذه الإشارات إلى المخ لتحليلها.\n"
            ),
            TextSection(
                "ما هى شروط وفوائد زراعة القوقعة ؟",
                "ترتبط عملية الزرع القوقعي بمجموعة من الشروط الضرورية التي يجب مراعتها هي :\n" +
                        "1- ضعف سمعي حسي عصبي في كلا الاذنين .\n" +
                        "2- عدم استفادة المريض من المعينات السمعية بعد ستة أشهر من المحاولة على الأقل.\n" +
                        "3- لا يوجد عائق صحي لمريض عند خضوعة للتخدير العام.  \n" +
                        "4- التزام المريض والمسؤلين عنه بالتدريب على الجهاز قبل وبعد العملية .\n" +
                        "5- توقعات المريض المنطقية حول نتائج زراعة القوقعة .\n" +
                        "6- وجود القوقعة واعصاب الأذن السمعية . \n" +
                        "7- تجاوز المريض للاختبارات النفسية والذكاء والتخاطب . \n" +
                        "8- وجود مجتمع للمريض يتفهمون ويقبلون ويدعمون هذه العملية.\n" +
                        "9- السن حيث يفضل أن يتم إخضاع الأشخاص المستفيدين من الزرع القوقعي في سن مبكر من أجل الحصول على أفضل النتائج .\n" +
                        "10- وجود حالة من الصمم العصبي الحسي الشديد المزدوج، ومنهم: الأشخاص ذوو الصمم الحاد، الأشخاص ذوو الصمم العميق والأشخاص ذو الصمم الكلي.\n" +
                        "    إن أهمية القيام بعملية الزرع القوقعي مرتبطة أساسا بالفوائد التي تعود على المريض، والتي يمكن حصرها في :\n" +
                        "1- يتيح السمع لدى أشخاص يعانون ضعف سمع شديدا وعميقا نتيجة وجود إصابة على مستوى الأذن الوسطى.\n" +
                        "2- تمكن الأطفال المولودين صما من \"تعلّم\" السمع والمشاركة في أطر تربوية عادية. \n" +
                        "3- الإسهام في زيادة اليقظة للضجيج الخلفي، وتحسين القدرة على تحديد الكلام وفهمه وكذا تحسين القدرة على الحديث وقراءة الشفاه .\n"
            )
        )
    )

    internal val Article_53 = Article(
        id = 53,
        title = "نجاح زراعة القوقعة",
        sections = arrayOf(
            ImageSection("5/3/thumb.jpg"),
            TextSection(
                "الأمور التى يجب معرفتها والحذر منها بعد زراعة القوقعة :-",
                "- ينصح به بعد الغوص لاعماق كبيرة و يمكن الاستحمام والسباحة والغطس في الماء بعد إزالة الجزء الخارجي .\n" +
                        "2- يجب تجنب المناطق ذات المجال المغناطيسي القوي مثل التصوير بالرنين المغناطيسي وعند الحاجة يتم اجراء عملية لازالة الجزء الممغنط من تحت الجلد ومن ثم يتم ارجاعه بعد اجراء الاشعة. \n" +
                        "3- يجب إطلاع جميع الأطباء وخاصة الجراحين على هذه الجراحة لأخذ الاحتياطات اللازمة أثناء أي عملية جراحية ، لأن العديد من الأجهزة الجراحية تتداخل مع عمل جهاز القوقعة .  \n" +
                        "4- تجنب التمارين والرياضات البدنية التي يمكن أن تلحق الضرر بالجهاز أو بأعضاء الجسم الداخلية.  \n" +
                        " 5- في حالة حدوث انسداد أو تورم في المنطقة المزروعة يجب استشارة الطبيب في أسرع وقت ممكن ، كما يجب عليه استشارة أخصائي السمعيات عند تغيير الجهاز.\n" +
                        "6- لا تعد زراعة القوقعة في الأذن علاجًا للصمم ، بل هي علاج مدى الحياة وبديل اصطناعي لا يضاهي عظمة الخالق أبدًا ، ولكنه على أي حال أفضل من عدم العلاج وجميع مضاعفاته يجب ان لا تكون سبب تردد لاجرائها. \n" +
                        "7- وجد أن مرضى زراعة القوقعة لديهم معدل إصابة بالتهاب السحايا بمقدار 30 ضعفًا ، ولهذا يوصى بتطعيم المرضى أثناء هذه الإجراءات.  \n" +
                        "8- عدم القدرة على سماع الأصوات البعيدة أو فهم الكلام جيدًا عند وجود ضوضاء بشكل جيد.  \n" +
                        " 9- احياناً لا يسمع المريض فيها كالسباحة والاستحمام والنوم لانه نزع الجزء الخارجي.\n"
            ),
            TextSection(
                "المعوقات التى تعوق انتشار زراعة القوقعة :",
                "يكمن أكبر معوق في انتشار هذه التقنية على عدة عوامل منها :-\n" +
                        "1- الجهل الكبير من قبل العديد من المرضى وأسرهم بأهمية العلاج والتحيز لفشل هذه التقنية والمضاعفات الناجمة عن أداء هذه الإجراءات من قبل المتخصصين. ناهيك عن أن بعض المرضى الذين يعانون من ضعف السمع أنفسهم يرفضون من اجراء زراعة القوقعة للأطفال لان هذا سوف يقلل من وجودهم كتجمع قوي يحافض على افراده. لا يتم إخفاء هذا عن أي شخص لديه علاقة بمريض ضعيف السمع. ، وقوة الترابط بين أفراد هذه المجموعة ، وهذا أمر لا يثير الدهشة ، لأن التواصل من أقوى روابط الحب. تعتبر زراعة القوقعة أيضًا نقطة اختلاف بين أعضاء هذا المجتمع المتماسك. وتثير المنظمات الكبيرة التي ترعى هذه الإعاقة وفي الدول المتقدمة العديد من الحالات حول هذه التكنولوجيا ، ويذهب البعض إلى أبعد من ذلك ويطلب من الآباء إزالة الثقة إذا قرروا زرع الجهاز في أطفالهم في مجتمع خاص. . لذلك يجب أن يكون الوصي على هؤلاء الأطفال أو يترك هؤلاء الأطفال حتى يكبروا ويقرروا زرع القوقعة بأنفسهم ، ولكن في هذه الحالة ستكون استجابة المريض لهذه العملية سيئة مع نموهم.\n" +
                        "2- لا توجد مراكز تقدم جميع الخدمات اللازمة لهؤلاء المرضى من أخصائيين وأخصائي سمع ونطق وأخصائي إعادة تأهيل. على سبيل المثال ، الولايات المتحدة لديها مركز مجهز بأحدث التقنيات والجراحين والمتخصصين لكل مليون شخص ، في حين أن المملكة العربية السعودية ليس لديها أي مركز. من ناحية أخرى ، يوجد في ألمانيا 1000 عملية زرع سنويًا لثمانين مليون شخص. إذا افترضنا أن ضعف السمع الشديد هو نفسه في ألمانيا ، فإننا نفترض حوالي ثلاثمائة وخمسين. تم اتخاذ الإجراءات ، لكن معظم التقديرات لا تتجاوز خُمس هذا المبلغ.\n" +
                        "3- المراكز الخاصة داخل وخارج المملكة العربية السعودية تتلقى مبالغ مالية كبيرة جدًا مقابل هذه العمليات الجراحية ، لذلك فهي مفيدة لها إذا كانت هذه التقنية غير متوفرة في المستشفيات العامة أو غيرها من المراكز الخاصة ، مما يؤدي إلى انخفاض هذه العمليات الجراحية المنفعة  .\n" +
                        "4- هناك نقص في البحوث الحديثة ومميزة في هذا المجال للوقوف على مدى هذه الإعاقة وأسبابها وأفضل طرق علاجها وتأهيل المرضى بشكل وتأهيل المرضى بما يحقق ما يتطلع اليه كل مريض او ممارس طبي في هذا المجال .\n" +
                        "5- عدم وجود منظومة حكومية مختصة تجمع الجهود المبعثرة وتوحد الاهداف وتكون مرجعية علمية وتثقيفية ومجال للتنافس الشريف في تقديم افضل الخدمات.\n" +
                        "    في مواجهة هذه التحديات ، قبلت جامعة الملك سعود هذه المشاكل وحاولت إيجاد حلول لها من خلال إرسال أطباء للتخصص في هذا المجال ، وإنشاء منحة تخصص ودعم إنشاء كرسي بحث في هذا المجال يأخذ على عاتقه تثقيف المجتمع والقيام بالعديد من الابحاث في هذا المجال على أمل ان يكون نواة لمركز متخصص يخرج من رحمة مراكزها المتخصصة العديدة لتلبية احتياجات البلاد ، وإنشاء الجمعية السعودية لزراعة القوقعة التي تضم خبراء من الأطباء والمتخصصين والباحثين والتربويين.\n"
            ),
            TextSection(
                "العوامل المؤثرة في نجاح زراعة القوقعة ؟",
                "أجمع العديد من العلماء أن هناك عددا من العوامل التي قد تؤثر على نجاح زراعة القوقعة للمعاقين سمعيا من حيث الاستفادة، وتلك العوامل بالآتي:\n" +
                        "1- العمر : يستحسن أن تتم الزراعة بعمر مبكر (قبل البدء بالنطق) ما يسمح للطفل بسماع الأصوات وتعلم النطق, وأما بالنسبة للأشخاص الكبار فاقدي السمع الكلي أو الشديد، والذين يكونون قد تعلموا النطق سابقا وتوجد لديهم ذاكرة لمفهوم الكلمات.\n" +
                        "2- المستوى التعليمي والأداء الأكاديمي للشخص.\n" +
                        "3- مدى تأثير البيئة المنزلية على الشخص من حيث القبول والتقبل.\n" +
                        "4- التأهيل بعد العملية : حيث أن ٦٠% من نسبة نجاح زراعة القوقعة تعتمد على التأهيل السمعي والتخاطب للطفل قبل وبعد العملية ( لمدة أربع سنوات) .\n" +
                        "5- الاعتبارات والاحتياطات اليومية للمحافظة على الجهاز : ومنها حفظ الأجزاء الخارجية للجهاز بعيدا عن الماء، وتجنب تعريضها للكهرباء الساكنة، وتجنب بعض الرياضات العنيفة التي قد تسبب ضربات قوية للرأس ( كالملاكمة)، وعدم مرور المريض خلال أجهزة كشف المعادن الموجودة في المطارات وبعض المحلات التجارية. \n" +
                        "6- القدرة على استيعاب الكلام قبل فقدان السمع : وهو ما يقلل من فترة التأهيل.\n" +
                        "7- استعمال السماعة العادية : فالطفل المعتمد على السماعة العادية يستطيع التكيف مع القوقعة بسهولة أكبر.\n" +
                        "8- فترة فقدان السمع فكلما قلت فترة فقدان السمع كلما زادت فائدة زراعة القوقعة. \n" +
                        "9- التقييم قبل العملية ويتعلق الأمر هنا باحترام شروط ومعايير إجراء العملية (الفحوصات السمعية، الأشعة .إلخ) .\n"
            )
        )
    )

    internal val Article_54 = Article(
        id = 54,
        title = "المستشفيات والدكاترة المتخصصة وأسئلة من زارعى القوقعة",
        sections = arrayOf(
            ImageSection("5/4/thumb.jpg"),
            TextSection(
                "بعض المستشفيات والدكاترة المتخصصة فى عمليات زراعة القوقعة ؟",
                "أ- المستشفيات المتخصصة فى عمليات زراعة القوقعة:"
            ),
            TextSection(
                "• مستشفيات زراعة قوقعة الأذن فى القاهرة :- ",
                "(1) مستشفى بهمان للطب النفسى\n" +
                        "(2) المستشفى السعودى الالمانى بالقاهرة\n" +
                        "(3) مستشفى السلام الدولى بالقاهرة \n" +
                        "(4) مستشفى أندلسية المعادى بالقاهرة \n" +
                        "للمزيد بالمعلومات الخاصة بهذه المستشفيات وطريقة التواصل معهم من خلال هذا الموقع :\n" +
