                "(1) مستشفى أصيل للرعاية الطبية بالغردقة\n" +
                        "(2) مستشفى النيل بالغردقة \n" +
                        "للمزيد عن المعلومات الخاصة بهذه المستشفيات وطريقة التواصل معهم من خلال هذا الموقع :\n" +
                        "https://www.vaidam.com/ar/hospitals/ent-surgery/cochlear-implantation/egypt/hurghada"
            ),
            TextSection(
                "• مستشفيات زراعة قوقعة الأذن فى مصر الجديدة :-",
                "(1) مستشفى كليوباترا\n" +
                        "للمزيد عن المعلومات الخاصة بهذه المستشفى وطريقة التواصل معها من خلال هذا الموقع :\n" +
                        "https://www.vaidam.com/ar/hospitals/ent-surgery/cochlear-implantation/egypt/heliopolis"
            ),
            TextSection(
                "• مستشفيات زراعة قوقعة الأذن فى مصر الأقصر :-",
                "(1) مستشفى المدينة التخصصى بالأقصر\n" +
                        "للمزيد عن المعلومات الخاصة بهذه المستشفى وطريقة التواصل معها من خلال هذا الموقع :\n" +
                        "https://www.vaidam.com/ar/hospitals/ent-surgery/cochlear-implantation/egypt/luxor"
            ),
            TextSection(
                "• مستشفيات زراعة قوقعة الأذن فى شرم الشيخ :-",
                "(1) مستشفى جنوب سيناء بشرم الشيخ \n" +
                        "للمزيد عن المعلومات الخاصة بهذه المستشفى وطريقة التواصل معها من خلال هذا الموقع :\n" +
                        "https://www.vaidam.com/ar/hospitals/south-sinai-hospital-sharm-el-sheikh"
            ), TextSection(
                "• مستشفيات زراعة قوقعة الأذن فى الاسكندرية :-",
                "(1) مستشفى النخبة بالاسكندرية \n" +
                        "للمزيد عن المعلومات الخاصة بهذه المستشفى وطريقة التواصل معها من خلال هذا الموقع :\n" +
                        "https://www.vaidam.com/ar/hospitals/ent-surgery/cochlear-implantation/egypt/alexandria"
            ),
            TextSection(
                "",
                ""
            ), TextSection(
                "ب- الدكاترة المتخصصة فى عمليات زراعة القوقعة :",
                "يوجد العديد من الدكاترة المتخصصة فى زراعة القوقعة وهم دكاترة انف واذن وحنجرة لمعرفهم كامل المعلومات وطريقة الحجز معهم من خلال المواقع التالية :-\n" +
                        "● https://clinido.com/en/search/كل-التخصصات/كل-المناطق/كل-المناطق/زراعة-القوقعة?page=1 \n" +
                        "● https://www.vezeeta.com/ar/دكتور/خدمة/زراعة-القوقعة/كل-التخصصات/مصر \n" +
                        "● https://koshofat.com/doctors/all/service/زراعة-القوقعة/ \n"
            ),
            TextSection(
                "الأسئلة الشائعة حول خدمات زراعة قوقعة الأذن من المرضى ؟",
                ""
            ), TextSection(
                "",
                ""
            ), TextSection(
                "1- كيف يمكن أن تساعدني زراعة قوقعة الأذن؟",
                "إذا كنت تستخدم سماعات الأذن ولكنك لا تزال تواجه صعوبة في السمع على الهاتف أو إذا كنت تطلب تكرار الكلام بشكل ثابت أثناء المحادثة اليومية، فقد تكون زراعة قوقعة الأذن هي الخطوة التالية الجيدة بالنسبة لك. يمكن الأخصائي السمع إجراء بعض الاختبارات البسيطة لتحديد ما إذا كانت زراعة قوقعة الأذن قادرة على تزويدك بمستوى صوت أفضل ووضوح أفضل مقارنة بسماعات الأذن."
            ), TextSection(
                "2- ما هو الفرق بين زراعات القوقعة وسماعات الأذن؟",
                "توفر سماعات الأذن صوتاً مضخماً بدقة في أذن من يرتديها بحيث يمكن سماعه عند ضعف السمع الطبيعي. ومع ذلك، فقد تصل سماعات الأذن إلى أقصى قدرة لها عندما يكون الضرر كبيراً، تتجاوز زراعات القوقعة الهياكل التالفة في الأذن الداخلية أو \"القوقعة\" وتحفز أعصاب السمع مباشرة.\n" +
                        "تحتوي زراعات القوقعة على مكوّن خارجي يسمى معالج الكلام، والذي يشبه جهاز السمع. يتم ارتداؤه خلف الأذن أو على جانب الرأس. وعلى العكس من سماعات الأذن. يستخدم معالج الكلام إشارة لاسلكية لإرسال المعلومات الجلد إلى \"القوقعة المزروعة\" التي يتم وضعها . جراحياً تحت الجلد يُحفز المكون المزروع أعصاب السمع ويسمح للمخ يتلقي الصوت..\n"
            ), TextSection(
                "3- كم تبلغ فترة الانتظار قبل إجراء الجراحة ؟",
                "يمكن أن تختلف قوائم الانتظار الجراحية، ولكنها عادة ما تتراوح بين 6-12 شهرا للمرضى في النظام الصحي العام وتكون أقصر بكثير للمرضى في النظام الخاص."
            ), TextSection(
                "4- هل سني متقدم لإجراء زراعة قوقعة الأذن؟",
                "يمكن أن تساعد زراعة القوقعة الأشخاص في أي سن على تحسين سمعهم ونوعية حياتهم. وقد استفاد الأطفال الرضع الذين يبلغون من العمر بضعة أشهر وحتى الأشخاص في سن التسعين وأكبر من تكنولوجيا زراعة قوقعة الأذن."
            ), TextSection(
                "5- ما الذي تبدو عليه زراعة قوقعة الأذن؟",
                "تعتبر التجربة الأولية لكل شخص مع زراعة القوقعة فريدة من نوعها لأنهم لم يسمعوا بهذه الطريقة من قبل. يصف العديد من مستخدمي زراعة القوقعة الصوت بأنه مختلف تماماً عن سماعات الأذن، خاصة في البداية.  يتغير هذا بمرور الوقت ويقول معظم المستخدمين إنه يتحسن كل يوم ."
            ), TextSection(
                "6- أشعر بالتوتر من الجراحة. هل هي خطرة؟",
                "قبل أن تتخذ قرارك بشأن جراحة زرع قوقعة الأذن. سيقوم الفريق الطبي والسريري المتخصص لك بإبلاغك بشكل كامل بالمخاطر والاحتياطات، وسوف ينصحك إذا كانت هناك أية مشکلات تنطبق بشكل خاص على ظروفك الطبية.\n" +
                        "تستغرق الجراحة نفسها ساعة واحدة تحت تأثيرالتخدير العام يقوم الجراح بعمل شق صغير خلف أنتك، ويضع القوقعة المزروعة تحت الجلد، ثم يُدخل مجموعة الأقطاب الكهربائية في أذنك الداخلية. يتم إجراء الاختيارات للتأكد من أن القوقعة المزروعة تعمل.\n" +
                        "يقضي معظم العملاء ليلة واحدة في المستشفى ويمكنهم العودة إلى العمل والأنشطة العادية في غضون أسبوع تقريباً من العملية. هذا هو الوقت الذي يتم فيه تنشيط أو \"تشغيل\" القوقعة المزروعة لأول مرة.\n"
            ),
            TextSection(
                "7- هل يجب أن أنتظر التطورات التكنولوجية الجديدة أو أبحاث الخلايا الجذعية؟",
                "إذا كان بإمكانك الاستفادة من زراعة القوقعة، فكلما أسرعت في الحصول عليها كلما كان ذلك أفضل. هناك قدر كبير من الأدلة التي تثبت أنه كلما طالت مدة بقاء الشخص يعاني من ضعف شديد في السمع، زادت الآثار السلبية التي يتعرض لها نتيجة فقدان السمع. يمكن أن تشمل آثار العيش مع فقدان السمع الشديد العزلة الاجتماعية والتأثيرات العاطفية والانسحاب من الأنشطة التي كانت ممتعة في السابق والتدهور المعرفي المحتمل تعلم أيضاً أن الأشخاص الذين يحصلون على زراعات القوقعة مبكراً غالباً ما يحرزون تقدماً في الاستفادة من قوقعاتهم المزروعة.\n" +
                        "لن يؤدي الحصول على زراعة القوقعة الآن إلى استبعادك من الاستفادة من تقنية معالجة الصوت المستقبلية. تم تصميم معظم معالجات الصوت الآن للسماح لك بالاستفادة الترقيات المستقبلية، دون الحاجة إلى من جراحة إضافية.\n"
            ), TextSection(
                "8- هل احتاج إلى القوقعة المزروعة في كلتا الأذنين؟",
                "بينما يحصل بعض الأشخاص على زراعة قوقعة في كل أذن إلا أن الأغلبية يستخدمون زراعة قوقعة واحدة ويستمرون في استخدام سماعة الأذن في الأذن الأخرى. يمكن أن يمنح هذا \" أفضل ما في العالمين\" مع النغمة الصوتية الطبيعية لسماعة الأذن جنباً إلى جنب مع وصول أفضل إلى أصوات الكلام الناعمة والنقية التي توفرها زراعة القوقعة. ثبت أن ارتداء كليهما يعطي فهما أفضل للكلام، لا سيما في الضوضاء، وتحديداً أفضل لمصدر الأصوات، وتقدير صوت أفضل لصالح الموسيقى."
            )
        )
    )

    internal val Article_55 = Article(
        id = 55,
        title = "التأهيل اللغوى لزراعى القوقعة",
        sections = arrayOf(
            TextSection(
                "",
                " تعتمد عملية التأهيل في الأساس على تدريب الدماغ لكيفية سماع وفهم الكلام من خلال القوقعة الالكترونية ونظرا لان القوقعة الالكترونية تعيد القدرة للمريض على سماع غالبية الأصوات فإن تجربة السمع الأولى من خلال القوقعة الالكترونية تكون مجهدة نظرا للزخم الكبير في الأصوات المسموعة فعلى سبيل المثال تكون الأصوات البيئية منها والكلامية مختلفة عما يتذكره الدماغ للذين فقدوا سمعهم في مرحلة متأخرة اي بعد اكتسابهم للغة أما الأطفال الذين فقدوا سمعهم منذ الولادة فقد يحتاج الدماغ لبعض الوقت ليميز ماهية هذه الأصوات وما تؤديه من معاني ودلالات وعادة ما تكون العملية مستمرة لفترة طويلة المدى وفي الأغلب تحصل أفضل النتائج عندما يقوم المريض باستخدام القوقعة طوال الوقت.\n" +
                        "    يتمكن الأطفال المستفيدون من الزرع القوقعي والتأهيل اللغوي من اكتساب اللغة الشفوية والقراءة والكتابة وتتمثل خطوات البرنامج في :\n"
            ),
            TextSection(
                "1- إشعار الطفل بوجود صوت:",
                "الخطوة الأولى في التدريب السمعي ، ويمكن تحقيقها عن طريق القرع على أدوات مختلفة تصدر أصوات عالية و كالقرع على طبل ، دق الباب ، النفخ في آلة موسيقية."
            ),
            TextSection(
                "2- الاستجابة الحركية للمثير الصوتي:",
                "هي الخطوة الثانية في التدريب السمعي، ويمكن تحقيقها من خلال اقتران الأصوات الناتجة من الأدوات بحركات معينة يستجيب لها الطفل عند سماعه لها. مثال على ذلك :\n" +
                        "- وضع قطعاً من الحلوى أمام الطفل وحين سماعه للصوت يتناول قطعة الحلوى.\n" +
                        "- وضع أدوات أمام الطفل مماثلة للأدوات التي تقرعها لإحداث الصوت ، على أن يطلب من الطفل قرع الأداء التي أمامه المماثلة للأداة التي أحدثت الصوت.\n" +
                        "- وضع مجموعة ألعاب أمام الطفل ويربط كل لعبة من هذه الألعاب بصوت معين ، بحيث يأخذ الطفل اللعبة عند سماع الصوت المقترن بها.\n" +
                        " - يطلب من الطفل أن يرفع يده حين سماعه للصوت أو يربط بين الصوت وصورة الأداة التي أحدثت الصوت ، مثل صورة الطبلة بصوتها ، أو صورة الديك بصوته.\n" +
                        "- يطلب من الطفل التصفيق أو الوقوف أو الدوران حين سماعه للصوت.\n"
            ),
            TextSection(
                "3- تمييز عدد الطرقات الصادرة عن صوت الأداة :",
                " الخطوة الثالثة في التدريب السمعي، فبعد أن يتعرف الطفل ضعيف السمع على صوت الأدوات المختلفة يطلب منه المدرب أن يميز عدد هذه الطرقات. ويمكن استخدام نفس أساليب الاستجابة التي اتبعت في الخطوة الثانية؛ فعلى سبيل المثال: يمكن أن يأخذ الطفل ثلاث قطع من الحلوى عند سماعه لثلاث طرقات على الطبلة . وهكذا .. إلا أنه يتعين على المدرب أن يضع في اعتباره قدرة الطفل على العد، إضافة إلى فهمه لمفهوم العدد."
            ),
            TextSection(
                "4- تمييز مصدر الصوت :",
                "الخطوة الرابعة في التدريب السمعي ، فبعد أن يتعرف الطفل ضعيف السمع على أصوات أدوات مألوفة لديه في بيئته ، يبدأ المدرب التقدم خطوة للأمام، وذلك بأن يصدر صوتين ، ويطلب من الطفل أن يتعرف عليهما ( يميز بينهما ) . فعلى سبيل المثال، يمكن أن يصدر المدرب صوت تغير وصوت طبلة .. وما إلى ذلك. كما انه يمكن في هذه الخطوة أن يطلب من الطفل أن يميز بين أصوات المواصلات والبيئة والإنسان والحيوان والطيور."
            ),
            TextSection(
                "5- التعرف على مصدر (اتجاه) الصوت :",
                "هي الخطوة الخامسة في التدريب السمعي، ويمكن تحقيقها عن طريق قيام المدرب بإصدار صوت ما، ثم بعد ذلك - يطلب من الطفل ضعيف السمع أن يتعرف على الجهة التي صدر منها الصوت. وفي هذه الخطوة يتعين على المدرب أن يركز على عملية التدريب على معرفة مصدر الصوت، وليس على الأذن التي يسمع بها تلك الطفل الصوت."
            ), TextSection(
                "6- تمييز شدة الصوت :",
                " الخطوة السادسة من خطوات التدريب السمعي، ويمكن تحقيقها عن طريق طلب المدرب من الطفل ضعيف السمع التعرف على الصوت المرتفع و الصوت المنخفض وأن يميز بينهما. وفى هذه الخطوة يمكن الاستعانة بأشرطة الكاسيت وبرامج الحاسب."
            ), TextSection(
                "7- التدريب على التركيز والانتباه السمعي :",
                "الخطوة السابعة من خطوات التدريب السمعي، ويمكن تحقيقها عن طريق طلب المدرب من الطفل ضعيف السمع الاستجابة بالحركة عند سماعه الصوت ؛ ذلك أنه في بعض الأحيان تصبح حركة الطفل روتينية دون إدراك أو تركيز على ما يسمع ، كما قد يقوم الطفل بالحركة كاستجابة تلقائية دون صدور الصوت ، ولذلك يتعين على المدرب أن يتنبه إلى ذلك في أثناء التدريب السمعي ، وأن يراعى التنوع في إصدار الأصوات من حيث الشدة و النوع وذلك حتى يتأكد القائم بعملية التدريب من استفادة الطفل من التدريبات السمعية ويتم ذلك من خلال الخطوات التالية :         \n" +
                        " • نعود الطفل على الانتباه قبل بداية الكلام للنظر مباشرة في الفم لكي يتعلم القراءة على الشفاه ويعرف مكان النطق.                          \n" +
                        "• يجب مشاركة كل المحيطين بالطفل في عملية التعلم.                   \n" +
                        "• كل فرد من أفراد العائلة ملزم بتخصيص وقت مع الطفل للتعلم.  \n" +
                        "• عدم استعمال أي شكل من أشكال لغة الإشارة للتواصل مع الطفل والتركيز على استعمال وتطوير السمع. \n" +
                        "• قبل بداية تربية الصوت يجب تطوير التنفس واستعمال طريقة النسف على الهواء.\n" +
                        "• نبدأ بالمصوتات ثم نذهب إلى الحروف.   \n" +
                        "• كل حرف يتعلمه الطفل في مدة لا تقل عن ثلاثة أيام يعيده كل من في البيت لكي يرسخ في ذهن الطفل.    \n" +
                        "• عند تعلم الطفل الحرف يجب أن نختار له كلمات قصيرة بها هذا الحرف مع مراعاة أن هذا الحرف يجب أن يكون في بداية ووسط و نهاية الكلمة.\n" +
                        "• بعد ثلاث سنوات يجب أن يتبع كل عملية تعلم حرف كتابته.              \n" +
                        "• عملية الكتابة تكون بشكل كبير.             \n" +
                        "• تتبع عملية تعلم كل حرف والكلمات القصيرة بالصور.     \n" +
                        "• استعمال تمارين الإيقاع الموسيقى للتعود على التدرج الصوتي الصحيح للكلمة. الحواس الأيام الألوان أسماء أفراد العائلة أسماء الصلوات وأسماء الفواكه وأسماء الحيوانات.\n" +
                        "•  أصوات الإنسان الذكر والأنثى وأصوات الحيوانات وأصوات الباب التلفاز كل هذه الأصوات مهمة ومعرفة الفرق بينها .                  \n" +
                        "•  في نهاية كل أسبوع يجب إجراء حصة الرسم الحر للطفل لان الرسم إسقاطي ويعبر عن كل ما يفرح ويزعج الطفل فنقول له مثلا ارسم العائلة أو ارسم المنزل أو الأصدقاء أو ماذا يجري في المنزل أو الشارع.     \n" +
                        "• في بعض الأحيان نؤتى ببعض أصدقائه إلى المنزل أو أبناء الأخ أو الأخت أو العم أو الخال ونترك المجال مفتوح للتعبير واللعب شرط عدم استعمال لغة الإشارة.\n"
            ), TextSection(
                "8- التدريب على سماع أصوات حية مألوفة في البيئة :",
                " وهي الخطوة الثامنة والأخيرة من خطوات التدريب السمعي، ويمكن تحقيقها عن طريق تدريب الطفل ضعيف السمع على الأصوات الحية المألوفة في بيئته، كأن يقوم الطفل بزيارة حديقة الحيوان ، وتعريفه بأصوات الحيوانات الموجودة. وتبدو أهمية هذه الخطوة في أنها تتيح للطفل فرصة التدريب على الأصوات المتحركة رات الأصوات ، وفي حالة عدم توفر حديقة الحيوانات ، يمكن للمدرب تدريبه على سماع هذه الأصوات عن ريق أشرطة الكاسيت ، ويمكن تعميم هذه الخطوة على باقي الأصوات الحية المألوفة الموجودة في نطاق بيئة الطفل."
            )
        )
    )

    // Sub articles of article 34
    internal val Article_341 = Article(
        id = 341,
        title = "الإرشاد الأسري كاستراتيجية وقائية للحد من مشكلات الأشخاص الصم وضعاف السمع",
        sections = arrayOf(
            ImageSection("3/4/1/thumb.jpg"),
            TextSection(
                "أولاً - استراتيجيات الإرشاد الأسري للأشخاص الصم وضعاف السمع:",
                "المحاضرة : عن طريق تقديم معلومات لأسرتك عن الإعاقة وأسبابها وآثارها عليهم وعلى الطفل.\n" +
                        "\n" +
                        "الحوار: عن طريق استخدام أسلوب المناقشة.\n" +
                        "\n" +
                        "إعادة الصياغة: عن طريق إعادة تنظيم المواقف التي تواجه عضو الأسرة وإعادة صياغة الأفكار اللاعقلانية للأسرة تجاه الطفل وسلوكه وتبني رؤية جديدة تجاهه.\n" +
                        "\n" +
                        "التجسيد الأسري: وهو العمل على زيادة وعي أعضاء اسرتك وخاصة الوالدين بطريقة تواصلهم والصورة التي ينظرون بها إلى الطفل.\n" +
                        "\n" +
                        "التواصل: عن طريق العمل على تحسين التواصل بين أعضاء الأسرة.\n" +
                        "\n" +
                        "التعزيز الايجابي: عن طريق تقديم مدعمات ايجابية \n" +
                        "(مادية أو اجتماعية) لطفلك الأصم وضعيف السمع عند قيامه بسلوك مرغوب.\n" +
                        "لعب الدور، وتبادل الدور: من خلال إسناد دور ما لعضو الأسرة؛ ثم تبادل الأدوار بحيث يضع الفرد نفسه مكان الآخر، يتمثل الهدف الإرشادي لهذه الفنية في معايشة عضو الأسرة للدور ومهامه خاصة إذا قام عضو الأسرة بدور الأصم مثلاً فإنه يشعر بمدى المعاناة التي يجدها أثناء التواصل مع الأشخاص السامعين.\n"
            ),
            TextSection(
                "ثانياً ـ أهداف إرشاد أسر الأشخاص الصم وضعاف السمع",
                "/ يجب توفير الدعم الاجتماعي والانفعالي للأطفال الصم ولأسرهم.\n" +
                        "\n" +
                        "2/ من الواجب تعليم وتثقيف الفرد وأسرته من خلال البرامج التدريبية الفردية والجماعية.\n" +
                        "\n" +
                        "3/ لابد من مساعدتهم في علاج المشاكل السلوكية والانفعالية وكذلك على التكيف الاجتماعي.\n" +
                        "\n" +
                        "4/ المساهمة في تنمية قدراتهم إلى أقصى حد ممكن وتطوير مهاراتهم الحياتية التي تساعدهم على الاستقلال إلى أقصى درجة.\n" +
                        "\n" +
                        "5/ توعية الأشخاص الصم وضعاف السمع وأسرهم بالامتيازات والتشريعات الممنوحة لهم، مثل القانون الإماراتي رقم (29) لسنة 2006 وتعديلاته سنة 2009.\n" +
                        "\n" +
                        "6/ مساعدة أسر الأشخاص الصم وضعاف السمع في الحصول على المعلومات التي يحتاجونها فيما يتعلق بتربية وتعليم الفرد من ذوي الإعاقة وتأهيله.\n" +
                        "\n" +
                        "7/ تعريفهم بالمهن المتوفرة في البيئة المحلية وأماكن التدريب المناسبة لهم لتوفير الاستقلال الاقتصادي للأشخاص الصم وضعاف السمع ما أمكن.\n" +
                        "\n" +
                        "8/ مساعدة أسر الأشخاص الصم وضعاف السمع على التكيف والاندماج في الحياة الاجتماعية في المجتمع بإيجابية والقيام بأدوارهم الطبيعية خارج الأسرة.\n" +
                        "\n" +
                        "9/ مساعدة أسر الأشخاص الصم وضعاف السمع على تقبل حقيقة إعاقة ابنهم والتكيف معها والتعايش والتعامل المناسب مع الواقع الجديد الذي فرضه وجود طفل أصم أو ضعيف سمع في الأسرة.\n"
            ),
            TextSection(
                "ثالثاً ـ متطلبات نجاح إرشاد أسر الأشخاص الصم وضعاف السمع",
                "/ من الواجب تحديد جوانب القوة وجوانب الضعف لدي الأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "2/ لابد من تحديد الأوضاع البيئية (المعهد / البرنامج / المدرسة / النادي….. إلخ) التي تحدث فيها المشكلة، وكذلك المواقع، والأوقات، والأشخاص.\n" +
                        "\n" +
                        "3/ مهم جدا الكشف عن العوامل المسؤولة عن تلك المشكلات ومبرراتها من وجهة نظر كل فريق.\n" +
                        "\n" +
                        "4/ ضرورى عقد ورش عمل / دورات تدريبية تكيفية لتعديل السلوكيات غير المرغوبة.\n" +
                        "\n" +
                        "5/ ولابد من تدريب الوالدين على كيفية استخدام برامج تعديل السلوك واقتراح جدول زمني محدد لمتابعة سلوك الطفل الأصم أو ضعيف السمع.\n" +
                        "\n" +
                        "6/ تفعيل دور المؤسسات والجمعيات التي تقدم خدمات للأسرة.\n" +
                        "\n" +
                        "7/ النظرة الواقعية لإمكانيات الطفل الأصم أو ضعيف السمع وما يستطيع القيام به.\n" +
                        "\n" +
                        "8/ تحديد خطة تطبيق لبرنامج الإرشادي الفردي والجماعي.\n" +
                        "\n" +
                        "9/ يجب مراعاة الاحتياجات البدنية والطبية للأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "10/ ضرورى توافر فريق متكامل يتضمن (الأخصائي الاجتماعي، الأخصائي النفسي، الطبيب، أساتذة التربية الخاصة).\n" +
                        "\n" +
                        "11/ والتواصل بين المدرسة والأسرة حتى تتكامل الخدمة الإرشادية.\n"
            ),
            TextSection(
                "رابعاً ـ معوقات إرشاد أسر الأشخاص الصم وضعاف السمع",
                "1 ـ معوقات لها علاقة بالأسرة:\n" +
                        "\n" +
                        "ان الأسرة هى أكثر معرفة بمشكلات طفلهم الأصم أو ضعيف السمع واحتياجاته وقد تقدم له خدمات قد لا تتوفر في مراكز الرعاية المحلية ، فضلا عما توفره الأسرة من مشاعر الأمن والحنان بدرجة قد لا يشعر بها الطفل في مكان آخر.\n" +
                        "\n" +
                        "وهناك بعض التحديات التي تواجه الإرشاد الأسري للأشخاص الصم وضعاف السمع والمرتبطة بالأسرة ومنها ما يلي:\n" +
                        "\n" +
                        "1/ عدم تعاون بعض أسر الأشخاص الصم وضعاف السمع في تنفيذ البرنامج التربوي الفردي لأطفالهم.\n" +
                        "\n" +
                        "2/ التعاون غير المستمر بين الأسرة والمعهد / البرنامج، حيث مع بداية العام الدراسي يبدأ المرشد النفسي ببرنامج ارشادي جديد بسبب أن الأسرة لم تكمل البرنامج الذي أعد للطفل في العام السابق.\n" +
                        "\n" +
                        "3/ وضع أهداف وتوقعات أعلى من قدرات الطفل الأصم وضعيف السمع بشكل يحد من عمل المرشد.\n" +
                        "\n" +
                        "4/ تدني مستويات الوعي وتأخر اكتشاف إعاقة الطفل.\n" +
                        "\n" +
                        "5/ قلة المعلومات لدى الأسرة حول الخدمات المتوفرة في المجتمع المحلي.\n" +
                        "\n" +
                        "6/ تدني مستوى الخدمات التربوية والنفسية والتأهيلية المقدمة للأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "7/ نقص معلومات وخبرات الأسرة عن الإعاقة وآثارها ودورهما تجاه المعوق وإعاقته.\n" +
                        "\n" +
                        "8/ عدم التحلي بالصبر والتحمل عند التعامل مع الطفل الأصم وضعيف السمع.\n" +
                        "\n" +
                        "9/ افتقار أعضاء الأسرة لطرق التواصل (لغة الإشارة، التهجي الإصبعي، قراءة الشفاه) أو التواصل الكلى للأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "2 – معوقات لها علاقة بالمرشد الأسري:\n" +
                        "\n" +
                        "هناك العديد من التحديات التي تواجه المرشد في مجال التربية الخاصة وتشكل عقبة في أداء دوره التربوي منها ما يلي:\n" +
                        "\n" +
                        "1/ تعقيدات السلوك الإنساني خاصة مع حالات الإعاقة.\n" +
                        "\n" +
                        "2/ افتقار بعض المرشدين إلى المعايير اللازمة لممارسة المهنة وقلة الخبرة في هذا المجال.\n" +
                        "\n" +
                        "3/ عدم توافر العدد الكافي من المرشدين المؤهلين.\n" +
                        "\n" +
                        "4/ المفاهيم والاتجاهات السلبية نحو الأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "5/ عدم توافر التسهيلات المادية للمرشد الأسري من كتب ومراجع حديثة وأجهزة تدريب متطورة.\n" +
                        "\n" +
                        "6/ ضعف الإعداد العلمي للمرشد النفسي مما يعيق الإرشاد الأسري.\n" +
                        "\n" +
                        "\n" +
                        "3 – معوقات مجتمعية:\n" +
                        "\n" +
                        "تتمثل تلك المعوقات فيما يلي :\n" +
                        "\n" +
                        "1/ قلة عدد الأخصائيين في مجال الإرشاد الأسري للعمل مع أسر الأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "2/ قلة عدد المراكز التي تقدم خدمات تأهيلية ملائمة.\n" +
                        "\n" +
                        "3/ عدم توافر معلومات مركزية للخدمات والجهات التي تقدمها.\n" +
                        "\n" +
                        "4/ قلة الاختبارات والمقاييس التي تعطي رؤية شاملة للأداء الأسري الموجهة إليه الخدمة.\n" +
                        "\n" +
                        "5/ المواصلات والمعوقات البيئية قد تقف حائلاً دون استفادة الأسر وأطفالها من الخدمات.\n" +
                        "\n" +
                        "6/ تحكم المهنيين بالقرارات.\n" +
                        "\n" +
                        "7/ تركيز جميع الخدمات المقدمة للأسر في المدن الكبرى مما يعوق استفادة الأسرة من هذه الخدمات.\n"
            ),
            TextSection(
                "خامساً ـ الإرشاد الأسري كاستراتيجية وقائية للحد من الاثار السلبية الناتجة عن الصمم وضعف السمع",
                "/ أهمية النظر إلى الإرشاد الأسري على أنه جزء لا يتجزأ من حياة الأسر ودورتها.\n" +
                        "\n" +
                        "2/ لابد من العمل على تقديم الإرشاد الزواجي للراغبين في الزواج وتوعيتهم بأهمية الفحوصات الطبية اللازمة لتجنب احتمال إعاقة الأطفال.\n" +
                        "\n" +
                        "3/ من الضرورى تفعيل التواصل المشترك بين الأسرة والبرنامج وكافة الجهات المعنية التي تقدم خدمات للأشخاص الصم وضعاف السمع.\n" +
                        "\n" +
                        "4/ لابد من عقد دورات تدريبية للآباء عن الصمم وضعف السمع ومشاكل الأشخاص الصم وضعاف السمع وكيفية التعامل معها.\n" +
                        "\n" +
                        "5/ من الواجب تبصير الأسرة بأن ما يعانيه الأشخاص الصم وضعاف السمع من المشكلات هو نتاج للتفاعل الأسري أكثر من كونه راجع للإعاقة.\n" +
                        "\n" +
                        "6/ مهم جدا تدريب أعضاء الاسرة على طرق التواصل مع الأشخاص الصم وضعاف السمع واكتسابهم مهارات وأسس وقواعد تلك الطرق.\n" +
                        "\n" +
                        "7/ تفعيل دور مراكز الأمومة والطفولة والرعاية الصحية في التوعية بكيفية تجنب حدوث الإعاقة واكتشافها في مراحل مبكرة.\n" +
                        "\n" +
                        "8/ إعداد الكوادر البشرية المؤهلة للتوعية بالإعاقة في كل قطاعات الدولة.\n" +
                        "\n" +
                        "9/ أهمية إعداد دورات تثقيفية للأمهات قبل وأثناء الحمل وبعد الولادة حول الرعاية الصحية والنفسية لأطفالهم وكيفية تجنب مسببات الصمم وضعف السمع.\n"
            )
        )
    )

    internal val Article_342 = Article(
        id = 342,
        title = "التربيه الجنسيه",
        sections = arrayOf(
            ImageSection("3/4/2/thumb.jpg"),
            TextSection(
                "ايه هى المبادىء السليمه فى  التربية الجنسية للأطفال الصم؟",
                "التربية الجنسية للأطفال الصم هي بتكوين للشخصية نفسها \n" +
                        " ( مبتكونش تقديم معلومات صحيحيه عن الجنس  )، ف عندك التربية الجنسية للأطفال المقصود بيها هى التدعيم العاطفي لابنك، بمعنى انك تذوده بالمهارات الكافيه علشان يقدر ياخد قرارات صح فى علاقتاته وحياته بشكل عام . علشان كدا جهزنالك  10 مبادئ اللى بنتمنى انها تساعدك فى تكوين هويه طفلك الجنسيه ، وتأمينه ضد المعلومات المغلوطة من المجتمع والإعلام.\n"
            ),
            TextSection(
                "وهى دى أهم ١٠ مبادىء في تعليم طفلك اللأصم عن الجنس",
                ""
            ),
            TextSection("", ""),
            TextSection(
                "١- متهربش من المسئوليه:",
                " الآباء هما الأساس فى تعليم اطفالهم التربية الجنسية ف متهربش . لان مفيش حد هيقدر يكون ليه تأثير فى حياه طفلك قدك . وعلشان كدا اوعى تتجنب الكلام مع طفلك وتوعيتهم ازاى يتعامل مع الحاجات اللى زى دى  ؛ لأن كدا كدا طفلك هيتعلم ف انت تعلمه صح احسن ما يتعلم غلط ويضر نفسه واللى حواليه ."
            ),
            TextSection(
                "٢- خليك مستعد ان ابنك هيسألك الاسئله دى:",
                "المشكلة هى لما اطفالنا يجوا يسألونا احنا مبنكونش متوقعين دا والحاجه دى اكبر غلط لان المفروض نتوقع الاسئله دى ونعرف ان اطفالنا بيكبروا ، لازم تبقى مستعد للحظه دى واتكلم معاه وصاحب /ى طفلك الموضوع سهل ليه بتصعبه على نفسك متخلقش فجوه بينك وبين ابنك."
            ),
            TextSection(
                "٣- خد انت الخطوه الاولى وسيبك من الانطباعات الاولى اللى غالبا مبتدومش:",
                "اوعى تبعد عن ابنك وتخليه ياخد افكار عن الجنس عن طريق السوشيال ميديا او حتى صحابه والشارع ، ازرع انت الفكره الصح فى طفلك قبل الغلط ما يتزرع."
            ),
            TextSection(
                "٤- استغل اسئله ابنك عن الجنس استثمر:",
                "فى مواقف معينه بتعدى علينا وبناخد الموضوع كأنه عادى محصلش حاجه لكن دا غلط لان الامر دا مبيعديش على الطفل كدا زيك ، بالعكس دى بتكون فرصه انه يسأل اسئله كتير فى دماغه وبيكون نفسه يلاقى حد يجاوبه صح ، خد عندك مثال لو طفلك شاف سيده حامل ، او لو سمع كلمه عن الجنس من اى مصدر. دى كلها مواقف بتعتبر فرص خليك مستعد للاجابه فى المواقف دى ، وبكدا هيكون انت ساهمت بدور كبير فى حياته ومعرفته السليمه النقيه عن الجنس."
            ),
            TextSection(
                "٥- متقدمش معلومات سطحيه وخلاص كدا:",
                "دور الآباء الناضجين مش يقتصر على  ليس  ترديد معلومات جافة عن الفهم ، لان سؤال طفلك فرصه لتكوين شخصيته وتفكيره عن الجنس والتعامل معه . وسواء كان صح او غلط ، فمعلومات عن الجنس بتوصل لطفلك عن طريق مصادر كتيره جدا ، السوشيال ميديا والقصص والشارع والاصداقاء …الخ فعلشان كدا الاحتياج الحقيقى هو تأكيد المعلومه الصحيحه وتقدمله محتوى اخلاقى جنب المعلومه."
            ),
            TextSection(
                "٦- تأكد من مشاركة المعلومة الصحيحة الواضحة:",
                "طفلك هيفضل وبحبك وهيقرب منك اكتر لأنك متفاهم معاه ويتجاوبه لك وبتسمع منه والطفل هيحس انك بتحبه ومهتم بيه وتقديرك لاسئلته وصبرك وطول بالك ، انك تصلح تكون موضع ثقه ، والعكس بالطبع صحيح."
            ),
            TextSection(
                "٧- قدم اجابه متوازنة وصح للاسئله المتوقعة:",
                "محاولة تخويف طفلك عن الجنس هتيجى بطريقه عكسية، لأنها هتكون حالة من الغموض وعدم الفهم هتشغل تفكير طفلك . علشان كدا المهم توصيل الصورة الصحيحة عن الجنس (كأحد أشكال التعبير عن الحب فقط في إطار الزواج ) ودى أفضل من التخويف المبالَغ فيه من عواقب التسيُّب الجنسي."
            ),
            TextSection(
                "٨- خليك مهتم بتكرار وتعزيز الكلام اللى قلته لابنك:",
                "اوعى تكتفى بأنك قُلتَ لطفلك المعلومة مرة وخلاص كدا ، لأنه مُعرَّض أن ينساها اكيد يعنى. واتوقع انه بالطبع مش هيكون مستعد للاجابه بتاعتك لانه بيسمعها لأول مرة لأن لم يركز معك .ودا بالإضافة إلى إنه يستمع لرسائل متكررة من خارج الأسرة بشكل سلبيّ عن الجنس . المهم أن تستعد لتكرار اللى قولته."
            ),
            TextSection(
                "٩- حصِّن طفلك من القصص السلبية اللى هتوصله مستقبَلًا:",
                "تأمين طفلك مش معناه أنك تعمل دايرة عليه وتتحكم فيه وتحرمه من سماع أيّة كلمة عن الجنس . لأنه في كل الأحوال سيسمع من خارج الأسرة ، أيا كان اللى هيسمعه بقاا ف غالبا هيبقى غلط . حاجه حلوه منك أنك تعرفه حاجات متأكد أنه سيسمعها من خارج الأسرة . علشان يكون مستعد مش يتفاجأ ، ويثق إنك المصدر الجيد للمعرفة الصحيحه."
            ),
            TextSection(
                "١٠- قوي علاقتك الإيجابية بابنك باستمرار:",
                "الطفل لما يكون علاقته قويه بيك هيبقى عنده تشبع من الحب والقبول لا يبحث عن علاقات تشبعه خارج الأسرة . العلاقة الإيجابية بين الاب او الام وطفلهم تؤكد أن الجنس هو تعبير صحيح عن الحب في إطار الزواج المعلَن للجميع . فلا يستسلم لعلاقات تستغله جنسيًا، لأنه في الأساس جائع للحب في أسرته."
            )
        )
    )

    internal val Article_343 = Article(
        id = 343,
        title = "اهم النصائح لمساعدة طفلك الاصم على مواجهة التنمر",
        sections = arrayOf(
            ImageSection("3/4/3/thumb.jpg"),
            TextSection(
                "(1)",
                "من الواجب عليك /ى تتكلم مع طفلك الاصم بشكل دائم وبهدوء وتقرب منه ، لمعرفة سبب التنمر عليه ، خليك انت بمثابه الدعم له والتشجيع بشكل دائم، ولما يلجأ ليك علشان اى مشكله تعرض ليها اقف معاه وتفاهم بكل هدوء علشان بعد كدا يعرف يتصرف لوحده بشكل سليم."
            ),
            TextSection(
                "(2)",
                "لازم تشتغل على تشجيع طفلك الاصم على التواصل بشكل سليم مثلا لما يجى يتكلم معاك او مع غيرك فى مشكله هو تعرض ليها ، والشخص المتنمر عليه ، وازاى تصرفه في مثل هذا الموقف."
            ),
            TextSection(
                "(3)",
                "عزز ثقة طفلك الاصم بنفسه\n" +
                        "- شارك طفلك في التفكير للوصول إلى حل المشكلة اللى تعرض ليها ، ومتشجعوش  على الانتقام من الأشخاص اللى تنمروا عليه\n"
            ),
            TextSection(
                "(4)",
                "اعمل على تعزيز ثقة طفلك بنفسه ، وطمأنته باستمرار .\n" +
                        "- مثلا شجعه على الاشتراك في أنشطة المدرسة ، وتكوين صداقات داخل العائلة أو المدرسة أو النادي…الخ \n"
            ),
            TextSection(
                "(5)",
                "درب طفلك على مهارات الرد بحزم ، مثل الحفاظ على اتصال العين عند مواجهة المتنمر، والحفاظ على صوت هادئ ، والوقوف على مسافة مناسبة منه ، واستخدام اسم المتنمرعند التحدث إليه."
            ),
            TextSection(
                "(6)",
                "علم طفلك الاصم يتصرف بشجاعة ويتجاهل المتنمر:\n" +
                        "\n" +
                        "لازم تعلم طفلك ازاى يقول للمتنمر يتوقف عن اللى بيعمله بكل حزم ، وبعدين يبعد عنه ، وتجاهله ، مثل التصرف بغير اهتمام ، وب كدل هيظهر الطفل بأنه لا يهتم ، وقد يشعر المتنمر بالملل بعد ذلك.\n"
            )
        )
    )

    internal val Article_344 = Article(
        id = 344,
        title = "كيفيه السيطره على السلوكيات غير المقبوله لدى الاطفال الصم داخل الفصل",
        sections = arrayOf(
            ImageSection("3/4/4/thumb.jpg"),
            TextSection(
                "(1)",
                "لازم تفهم التلاميذ اللى قدامك قبل ما تبدأ في منع المشكلات اللى بتواجهك ، ودا من خلال مرحلة النمو اللى فيها غالبا بيواجهوا فيها مشكلات كتير بيتعرضولها أو تعرضولها في المدرسة أو البيت ."
            ),
            TextSection(
                "(2)",
                "من اهم النقط اللى لازم تشتغل عليها هى ضرورة منع المشكلة قبل حدوثها ودا عن طريق  : (التدريس الفعال الذي يشغل التلاميذ بأدائهم لأنشطتهم طيلة الحصة الدراسية – مراقبة الفصل وضبط الحركة\n" +
                        "فيه من أول وهلة يدخل فيها التلميذ والمعلم –\n" +
                        "ج – تجاهل بعض المشكلات السلوكية البسيطة أو التافهة .\n" +
                        "د – الثبات في الأساليب المتخذة لمعالجة المشكلات .\n" +
                        "هـ – حفظ أسماء التلاميذ بأسرع ما يمكن ونطقها نطقا صحيحا ، لأن معرفةأسماء التلاميذ وحفظها يساعدان المعلم على بناء علاقات طيبة معهم .\n" +
                        "و – تجنب مجابهة التلميذ المشاغب أمام زملائه .\n" +
                        "ي – تجنب السخرية والتقليل من شأن التلاميذ.\n" +
                        "– تجنب معاقبة كل التلاميذ بسبب شغب تلميذ واحد\n" +
                        "– ألا يبدأ المعلم الدرس إلا بعد أن يهدأ التلاميذ\n" +
                        "– إبعاد المعلم فكرة أن شغب التلاميذ إهانة له .\n"
            ),
            TextSection(
                "(3) لازم تحدد التلاميذ اللى محتاجين انتباهك:",
                "لازم تعمل عنايه خاصه جدا بالتلميذ اللى بيثير سلوكه السيئ انتباه الجميع في المدرسة.\n" +
                        " أولاً : لازم تعرف هل السلوك دا دائم مع الطفل ولا بيظهر فى ظروف معينه فقط ، وبيتم التعرف على دا من خلال نموذج استبيان للرأي بتيم توزيعه على المدرسين المحيطين بالطالب ذي السلوك السيئ.\n"
            ),
            TextSection(
                "(4) لازم تتأكد من استخدام المواصفات المناسبة لنموذج استطلاع الرأي",
                "لابد ان يكون النموذج صالحاً للاستكمال بأقل مجهود ممكن. ولتكن صفحة النموذج هي الصفحة النموذجية العادية بحجم A4.استخدم أسلوباً واضحاً للأسئلة واترك مساحة مناسبة للإجابات."
            ),
            TextSection(
                "(5) ابحث عن مسببات سلوك التلاميذ غير المقبول",
                "علشان تفهم مسببات السلوك غير المقبول ، فإنه من المفيد أن تتعرف على الدوافع التي أدت إلى ظهور هذا السلوك . السؤال التالي يجب أن يكون بخصوص العوامل التي تعجل بظهور هذا السلوك لدى الطالب. يمكنك كذلك أن تسأل ما إذا كان بإمكان المدرس تحديد السلوك الغالب للطالب عندما لا يظهر لديه السلوك غير المقبول. وقد يكون لذلك فائدة كبيرة، فعلى سبيل المثال، قد يكون المسبب هو غياب طالب أخر أو شيء معين أو يكون مجرد وقت معين من اليوم."
            ),
            TextSection(
                "(6) لاحظ تأثير التلميذ ذي السلوك غير المقبول على التلاميذ الآخريين",
                "يسبب هذا التلميد قلقاً في الفصل ، لكنه أيضاً يتفاعل مع الأخريين، مما قد يؤثر على سلوكهم هم أيضاً. أسأل عن أسماء الطلاب الذين عادة ما يتعاملون مع الطالب ذي السلوك غير المقبول. يمكنك كذلك أن تتساءل عما اكتسبه هؤلاء الطلاب من التعامل مع الطالب ذي السلوك غير المقبول. أسأل عما إذا كانوا قد بدأوا يستجيبوا له وما إذا كان من الواجب تغيير هذه الاستجابات."
            ),
            TextSection(
                "(7) لا تأخذ السلوك السيىء بشكل شخصى",
                "تذكر أن الغضب الذي قد ينفجر فيك قد ينبع لدى الطالب من مشاكل ليس لك يد فيها. حاول ألا تحمل أية ضغينة للطالب مهما كانت درجة تألمك من أسلوب معاملته لك. ولتبدأ كل يوم جديد بقلب جديد خالي من أية ضغائن ومليء بالأمل والتوقع الجيد لسلوك أفضل من هذا الطالب."
            ),
            TextSection(
                "(8) تجنب أنك تفقد أعصابك حتى لو تم استفزازك بشدة",
                "تذكر أنك أنت الإنسان الراشد الذي لديه مسئولية تقديم القدوة الحسنة للطلاب. حاول ألا ترفع صوتك إلا عند اللزوم، فإن السلوك العصبي والصوت العالي من ناحيتك سينعكس على ردود أفعال الطلاب تجاهك."
            ),
            TextSection(
                "(9) حاول انك تستخدم الدعابة لتقليل التوتر",
                "لو منحت التلميذ الغاضب فرصة للتراجع عن هذا السلوك وذلك من خلال مداعبته ، فإن ذلك قد يحول دون وقوع تصرف غير لائق منه. على سبيل المثال، إذا صاح الطالب قائلاً. أنا أكرهك، فإنك قد تتبسم قائلاً: “يا للخزي، مع إنني أحبك!”. ولكن تأكد أن لا تجعل هذا التلميذ مدعاة للسخرية بين أصدقائه بالفصل. فإن الهدف الأساسي هو تقليل التوتر وليس زيادته."
            ),
            TextSection(
                "(10) حاول انك تعمل مجموعة صغيرة من قواعد السلوك",
                "وعلشان يتم تطبيق القواعد دى بصورة منتظمة وبشكل عادل. إن السلوك غير اللائق عادة ما يرجع إلى أن الطالب لا يعرف أين هي حدوده التي لا يجب أن يتخطاها. يجب أن يكون الطلاب على علم وبينة من أن كل نوع من أنواع السلوك غير اللائق سيكون له نوع من العقاب الذي يتفق معه. ويجب أن توضح للطلاب أي مخالفات لقواعد السلوك خارج نطاق المدرسة لا يجب أن يحدث أبداً داخل نطاق المدرسة والفصل. إن الحزم والثبات على المبدأ يولدان الاستقرار."
            ),
            TextSection(
                "(11) حاول انك تاخد إجراءات لتهدئة ثورة الطالب (تشتمل هذه الإجراءات على مشاركتك)",
                ""
            )
        )
    )

    internal val Article_345 = Article(
        id = 345,
        title = "نصائح لأسرة الطفل الأصم وضعيف السمع",
        sections = arrayOf(
            ImageSection("3/4/5/thumb.jpg"),
            TextSection(
                "(1)",
                "مفيش داعي لليأس حتى لو كان فى صعوبات في اتصال طفلك مع الآخرين ومع العالم من حوله عن طريق القناة السمعية فإن هناك قنوات أخرى للاتصال واكتساب المعرفة لسه مفتوحة فالطفل الاصم يستطيع أن يتعلم الكثير ويستطيع أن يتواصل بطرق مختلفة مع الآخرين عن طريق حاسة البصر على سبيل المثال."
            ),
            TextSection(
                "(2)",
                "خليك فاكر إن الطفل الاصم دا له نفس الحاجات الأساسية عند اقرانه من الأطفال الآخرين هو بيحتاج إلى الحب وإلى الفرص المناسبة لاكتساب الخبرات الحياتية ولا يحتاج إلى الشفقة."
            ),
            TextSection(
                "(3)",
                "تجنب الحماية الزائدة أو الإهمال الزائد لطفلك الاصم بمعنى خلى الكافتين متساويه."
            ),
            TextSection(
                "(4)",
                "أعطِ الفرصة لطفلك الصم انه يتكلم ويعبر عن نفسه شجعه على الاستفسار والسؤال وأعمل على إعطائه الإجابة والتفسير المناسب لما يسأل عنه واحرص على ألا تجيب نيابة عنه ولكن يمكنك توضيح ما أراد التعبير عنه ، يعنى تفسر كلامه\n" +
                        " (إن كانت هناك حاجة إلى ذلك) شرط أن يتحدث هو أولاً، فهذا الطفل مثل غيره من الأطفال بحاجة إلى أن يتحدث مع الكبار لا مجرد الإصغاء لهم.\n"
            ),
            TextSection(
                "(5)",
                "احرص على منح الفرصة لطفلك الاصم لاكتساب المفاهيم والمعارف والخبرات الحياتية اللازمة له وتذكر أن الطفل السامع يستطيع اكتساب الكثير اعتماداً على حاسة السمع أما هذا الطفل فهو بحاجة إلى من يفسر له الأحداث من حوله وإلا فإنه سيعيش في عزلة عن غيره وبالتالي لن تتاح له الفرصة لاكتساب الكثير من المفاهيم والمعارف والخبرات الضرورية له."
            ),
            TextSection(
                "(6)",
                "احرص على إلحاق طفلك الاصم بروضة خاصة للصم وضعاف السمع ففيها هيكون له الفرصة للتواصل مع أطفال صم اخريين من عمره وفيها سيكتسب الكثير من الخبرات والمفاهيم لكن لو مكنش متاح اعمل على إلحاقه بأقرب روضة للسامعين إن أمكن ذلك خاصة إن وجدت فيها معلمة يمكن أن تتقبله وأن تتفهم وضعه وتعمل على مساعدته."
            ),
            TextSection(
                "(7)",
                "احرص على أن يتعلم طفلك الاصم القراءة والكتابة حيث أن ذلك سيفتح أمامه قناة جديدة للتواصل مع الآخرين من العاديين وسيعمل على تزويده بالعديد من المعارف والمفاهيم والخبرات الضرورية له."
            ),
            TextSection(
                "(8)",
                "تذكر أن الطفل الاصم بيكون محتاج تنمية شخصية هو من جهة عضو في مجتمع الناس السامعين ومن جهة تانيه بيحتاج إلى الاختلاط مع مجتمع الناس الصم لأنه يستطيع التواصل معهم بسهولة ويستطيع أن يتبادل معهم المشاعر والخبرات وهو شيء ضروري لنمو الطفل الأصم أو ضعيف السمع نفسياً واجتماعياً وبالتالي فإن على الأسرة أن تبادر إلى البحث عن أسر أخرى لديها أطفال صم أو ضعاف سمع من خلال النوادي وغيرها."
            ),
            TextSection(
                "(9)",
                "السماعة الطبية مش هي الحل السحري في جميع الأحوال وبالرغم من فوائد استخدام السماعة الطبية في كثير من الحالات لكن بعض الحالات التي تكون فيها السماعة الطبية قليلة الفائدة بالنسبة للطفل."
            ),
            TextSection(
                "(10)",
                "مفيش داعى للقلق أكثر من اللازم على مستقبل طفلك الاصم لا طفلك الاصم يقدر يتعلم ويستطيع فى المستقبل أن يكتسب مهنة وأن يعمل ويتزوج وأن ينجب في معظم الأحوال أطفالاً سامعين."
            ),
            TextSection(
                "(11)",
                "من ناحية تانيه بيكون للأسرة دور هام في التواصل مع الأسر الأخرى التي لديها أطفال صم أو ضعاف سمع علشان يتبادلوا الخبرات وتبادل الدعم وبعدها لتنظيم الجهود ومن ثم مع التحرك بإيجابية وبانفتاح نستطيع أن نقدم الكثير لأبنائنا الصم أو ضعاف السمع ولأبناء مجتمعنا من الأشخاص الصم عموما بكافه مراحل حياتهم أما السلبية والانغلاق والخجل والخوف فإنها تؤدي إلا إلى النتائج السيئة التي لا نرضاها جميعاً."
            ),
            TextSection(
                "(12)",
                "وأخيرا على الأسرة وبخاصة الأم رعاية لغة الاتصال وعدم الإهمال في تدريب طفلها تدريباً مستمراً وتنمية المفاهيم لديه."
            )
        )
    )

}